// build_notes.py が作るファイル。手で直さない
const NOTES = {"01":[{"g":"レンズで寄る","n":"ズームイン（Zoom in）","b":[["見え方","画面全体が平らなまま大きくなります。手前と奥の大きさの比は変わらず、背景が切り取られて狭くなります。"],["作り方","撮影はズームレンズの輪を回します。3D（Blender）は camera.data.lens を24→72のように動かすと3倍。平面なら絵を拡大率 s で拡大（s＝新しい焦点距離÷元の焦点距離）。なめらかにするなら t*t*(3-2*t) の曲線。"],["使いどころ","「ここを見て」と指さす時。人の目はズームできないので、少し作り物っぽく見えます。多用すると安いテレビ番組風になります。"],["例","『カンバセーション…盗聴…』（1974）冒頭、高い所から広場の人ごみへ長くゆっくり寄る [知識]。自作の見本：ZM01のA"]]},{"g":"レンズで寄る","n":"ズームアウト（Zoom out）","b":[["見え方","細部から始まり、周りがだんだん見えてきます。奥行きは増えず、絵が額縁の中へ下がっていく感じです。"],["作り方","ズームインの逆。焦点距離を大→小、または拡大率を2.0→1.0へ。始まりの構図（細部）と終わりの構図（全体）を先に決めてから間をつなぎます。10〜20秒かけると絵画のようになります。"],["使いどころ","人物を周りの世界の中に置く、状況を明かす、場面を閉じる。"],["例","『ゴッドファーザー』（1972）冒頭、話す男の顔から部屋全体へゆっくり引く [知識]。『バリー・リンドン』（1975）で人物から風景へ引くズームが何度も使われる [知識]"]]},{"g":"レンズで寄る","n":"ゆっくりズーム（スローズーム／Slow zoom）","b":[["見え方","動いていると気づかないほど遅い寄り。気づいた時には顔が大きくなっています。"],["作り方","10〜60秒で1.1〜1.5倍。等速に近い動き（始めと終わりだけ少しゆるめる）。コードでは1コマあたりの拡大を0.05〜0.2%に。"],["使いどころ","不安、見張られている感じ、長い台詞の集中。速いと「ただのズーム」になるので遅さが命です。"],["例","『シャイニング』（1980）のホテルの中の場面 [知識]"]]},{"g":"レンズで寄る","n":"急ズーム（クラッシュズーム／スナップズーム／Crash zoom）","b":[["見え方","一瞬で顔や物へ飛び込みます。"],["作り方","3〜8コマ（0.1〜0.3秒）で1.5〜3倍。曲線は「出だしが速く最後に止まる」1-(1-t)3。3〜5%行きすぎて2〜3コマで戻すと勢いが出ます。動きの最中に放射ブラーを足し、「シュッ」という音を合わせます。"],["使いどころ","驚き、笑い、強い登場。1本の中で何度も使うとギャグの調子になります。"],["例","『ジャンゴ 繋がれざる者』（2012）で農園主が初めて顔を見せる所 [知識]。『ショーン・オブ・ザ・デッド』（2004）の身支度の短いつなぎ [知識]"]]},{"g":"レンズで寄る","n":"ズームの往復（寄って戻る）","b":[["見え方","寄って、すぐ元の大きさへ戻ります。「ん？」と二度見する感じです。"],["作り方","寄り6コマ→止め6〜12コマ→戻り8コマが目安。拡大率1.0→1.4→1.0。戻りは寄りより少し遅く。"],["使いどころ","ツッコミ、強調、音の一拍。戻るので構図を壊さずに使えます。"],["例","なし（確かな映画の場面を挙げられません）"]]},{"g":"レンズで寄る","n":"ドキュメンタリー風の探りズーム（Documentary zoom／Mockumentary zoom）","b":[["見え方","カメラマンがその場であわてて寄ったような、少し雑なズーム。行きすぎて戻したり、ピントが一瞬迷ったりします。"],["作り方","6〜12コマで寄り、5〜10%行きすぎて戻す。同時に小さな手ぶれ（位置を画面の0.5〜1%、回転を0.3度ほど、1秒に1〜3回ゆれる）と、ピントのぼけ→戻りを0.2秒足します。中心も少しずらして直します。"],["使いどころ","「本当に起きている」感じ、気まずい顔を拾う笑い。CGの宇宙船にこれを使うと実写っぽくなります。"],["例","『ザ・オフィス』（米国版 2005〜2013）で気まずい顔へ寄る [知識]。『GALACTICA／ギャラクティカ』（2004〜2009）の宇宙の戦い [知識]"]]},{"g":"レンズで寄る","n":"移動に隠したズーム（追加）","b":[["見え方","カメラが横へ動いたり振ったりしている間に、こっそり大きさも変わっています。ズームの作り物っぽさが消えます。"],["作り方","パンや横移動の最中だけ焦点距離を変え、動きが止まる前にズームも終えます。コードでは位置の動きと拡大に同じ曲線・同じ区間を使います。"],["使いどころ","長回しの中で構図を引き→寄りへ変えたい時。"],["例","なし [不明]"]]},{"g":"カメラが寄る","n":"ドリーイン（プッシュイン／Dolly in, Push in）","b":[["見え方","見ている自分が歩み寄る感じ。背景の見える範囲はあまり変わらず、人物だけが大きくなり、横の物が画面の外へ流れます。"],["作り方","撮影は台車（ドリー）やスライダーで前へ。Blenderはカメラの位置を被写体へ近づけます（例：8m→2.7mで約3倍）。画面上の大きさは「焦点距離÷距離」に比例。平面で真似るなら、層ごとに拡大率を変えます（手前ほど大きく）。"],["使いどころ","気持ちの高まり、気づき、決意。1〜4秒で、最後はなめらかに止めます。"],["例","『ジュラシック・パーク』（1993）で博士たちが初めて恐竜を見る顔へ寄る [知識]。見本：ZM01のB"]]},{"g":"カメラが寄る","n":"ドリーアウト（プルアウト／Dolly out, Pull out）","b":[["見え方","カメラが後ずさりします。人物が小さくなり、手前に物が次々入ってきます。"],["作り方","ドリーインの逆。後ろへ下がる道に物（柱、扉の枠）を置くと、通り過ぎる物で奥行きが出ます。"],["使いどころ","その場を離れる、見ていられない、置き去り、終わり。"],["例","『フレンジー』（1972）で部屋の前から階段を下りて通りまで後ずさる [知識]"]]},{"g":"カメラが寄る","n":"ゆっくり寄り続ける（クリープ／Creep in, Slow push）","b":[["見え方","ほとんど止まって見えるほど遅いドリーイン。ゆっくりズームと違い、奥行きが少しずつ変わるので「近づかれている」生々しさがあります。"],["作り方","10〜60秒で距離を1〜2割だけ縮めます。等速。コードではカメラ位置を1コマ数ミリずつ。"],["使いどころ","会話の緊張、決断の前。台詞の山で止まるように長さを逆算します。"],["例","なし（『ノーカントリー』（2007）のガソリンスタンドの場面を調べましたが、寄りは確かめられませんでした）[不明]"]]},{"g":"カメラが寄る","n":"手持ちで駆け寄る（Handheld rush）","b":[["見え方","カメラを持った人が走って近づく、揺れの大きい寄り。"],["作り方","撮影は手持ちで走る、または板にカメラを付けて2人で運びます。コードでは前進する動きに、上下の揺れ（歩幅に合わせ1秒に2〜3回、画面の1〜3%）と小さな回転を足します。広角（焦点距離18〜24mm）にすると速く感じます。"],["使いどころ","追われる恐怖、あわてた場面、何かの主観。長いと酔うので数秒まで。"],["例","『死霊のはらわた』（1981）で森の中を何かが地面すれすれに突進してくる [知識]"]]},{"g":"寄りと引きを同時に","n":"ドリーズーム（めまいショット／Dolly zoom, Vertigo effect）","b":[["見え方","主役の大きさは変わらないのに、背景だけが迫ってくる（または遠のく）。世界がゆがんだように見えます。"],["作り方","カメラを動かしながら逆向きにズームし、「焦点距離÷距離」を一定に保ちます（距離が3倍なら焦点距離も3倍）。Blenderの見本は ~/mad-lab/cam/zoom3_blender.py のC。平面で真似るなら、主役の層は固定し、背景の層だけ拡大・縮小します。1〜3秒が多いです。"],["使いどころ","衝撃、めまい、「まずいことに気づいた」瞬間。目立つ技法なので1本に1回まで。"],["例","『めまい』（1958）の階段を見下ろす所＝カメラを引きながらズームイン [確認]。『グッドフェローズ』（1990）の食堂の会話＝ゆっくり引きながらズームイン、窓の外の通りが大きくなる [確認]。見本：ZM01のC"]]},{"g":"寄りと引きを同時に","n":"逆ドリーズーム（Reverse dolly zoom）","b":[["見え方","上と逆向き。カメラが寄りながらズームアウトするので、主役はそのままで背景が広がり、後ろへ遠のきます。"],["作り方","式は同じで向きだけ逆（距離を1/3に、焦点距離も1/3に）。広角になるほど顔がゆがむので、寄りすぎに注意。"],["使いどころ","世界から切り離される感じ、強い恐怖の一瞬。どちらを「逆」と呼ぶかは人によって違うので、「引き＋ズームイン」「寄り＋ズームアウト」と書くのが確実です。"],["例","『ジョーズ』（1975）の浜辺で署長が異変に気づく顔＝寄りながらズームアウト [確認]"]]},{"g":"編集で寄る","n":"パンチイン（Punch in）","b":[["見え方","同じカメラの絵が、カットで急に大きくなります。カメラが2台あるように見えます。"],["作り方","同じ素材を115〜150%に拡大してつなぎます。差は15%以上（少ないと失敗のカットに見える）。4Kで撮って1080pで仕上げれば200%まで画質が落ちません。目の高さが変わらないよう中心を合わせます。"],["使いどころ","話す動画の言い直しを隠す、大事な一言の強調。"],["例","なし（YouTubeの話す動画の定番。映画では次の「3段寄り」の形になります）"]]},{"g":"編集で寄る","n":"3段寄り（軸上のカット）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","同じ向きのまま、カットで引き→中→寄りと3回跳んで近づきます。動きがない分、衝撃が強いです。"],["例","『鳥』（1963）で農家の中の死体の顔へ3回跳んで寄る [知識]。『フランケンシュタイン』（1931）の怪物の最初の登場 [知識]"]]},{"g":"編集で寄る","n":"拍ズーム","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","映画本編よりも、音楽ビデオ・予告編・MADの技法です。予告編では太鼓の音に合わせた短い寄りとして使われます。"],["例","なし"]]},{"g":"編集で寄る","n":"ケン・バーンズ（写真にゆっくり寄る／Ken Burns effect）","b":[["見え方","止まった写真が、ゆっくり寄りながら少し横へ動きます。"],["作り方","始まりの枠と終わりの枠の2つを決め、その間を5〜10秒で等速に近く動かします。拡大は1.0→1.1〜1.2倍、横の動きは画面幅の3〜8%。写真は仕上がりの1.5倍以上の大きさを用意します。顔や目など「終わりに見せたい所」へ向かいます。"],["使いどころ","記録もの、思い出、語りの背景。全部の写真を同じ向きにすると単調なので、寄りと引きを交互に。"],["例","『南北戦争』（1990、ケン・バーンズ監督のテレビ記録作品）の古い写真 [知識]"]]},{"g":"編集で寄る","n":"速度つきズーム（スピードランプ／Speed ramp zoom）","b":[["見え方","スローで寄り、急に速くなって戻る。時間と大きさが一緒に伸び縮みします。"],["作り方","高いコマ数（100コマ/秒など）で撮り、再生の速さを「20%→300%→20%」のように曲線で変えます。同時に拡大率を1.0→1.5→1.0。当たる瞬間の3〜5コマ前に一番遅く・一番大きくします。"],["使いどころ","アクションの一撃、スポーツ、踊りの決め。"],["例","『300 〈スリーハンドレッド〉』（2006）で王が敵の中を進む長い戦いの場面。3台のカメラに違うレンズを付けて並べ、後でつないで寄り引きを作った [確認]"]]},{"g":"編集で寄る","n":"追いかけズーム（顔や物に張りつく／Tracking zoom, Lock-on）","b":[["見え方","動いている顔や物が画面の同じ場所に固定され、周りだけが揺れながら大きくなります。"],["作り方","編集ソフトの追跡（トラッキング）で対象の位置を毎コマ取り、その逆の動きを絵にかけて固定します。その上で対象を中心に拡大。コードでは「対象の座標を画面の中心へ移す→拡大」の順です。"],["使いどころ","走る人、踊る人、スポーツの球。本人だけが止まって見える不思議さが出ます。"],["例","なし（旅動画やSNSの技法）"]]},{"g":"編集で寄る","n":"中心をずらしたズーム（Off-center zoom）","b":[["見え方","画面の真ん中ではなく、端にある顔や物へ向かって寄ります。"],["作り方","拡大の中心点（アンカー）を対象の位置に置きます。式は「新しい位置＝中心＋（元の位置−中心）×拡大率」。端すぎると絵の外が見えるので、拡大率に合わせて中心を画面内へ寄せます。"],["使いどころ","2人のうち片方へ、物の一部へ。真ん中へのズームより「選んだ」感じが出ます。"],["例","なし"]]},{"g":"編集で寄る","n":"ズームぼかし（放射ブラー）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","急ズームの最中の流れとして自然に出ます。超高速の移動を表す絵にも使われます。"],["例","『スター・ウォーズ』（1977）で宇宙船が超光速へ入る時、星が放射状の線に伸びる [知識]"]]},{"g":"つなぎとしての寄り","n":"ズーム転換","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","映画では素のズーム転換は少なく、下の「物の中へ入るズーム」のように物語上の理由を付けて使います。旅動画・SNSでは定番です。"],["例","なし"]]},{"g":"つなぎとしての寄り","n":"物の中へ入るズーム（目・画面・鍵穴）","b":[["見え方","目の黒い所、画面、鍵穴などへ寄り切り、その中が次の場面になります。"],["作り方","暗い所・単色の所へ向かって寄り、画面がその色で埋まった瞬間に次の絵へ切り替えます（次の絵は同じ色から引いて始める）。寄りは最後に加速、倍率は10倍以上になるので、途中でより大きな絵（アップの写真）に差し替えます。"],["使いどころ","思い出へ入る、心の中へ入る、別の世界へ移る。"],["例","『ファイト・クラブ』（1999）冒頭、頭の中から顔の外へ出てくる（逆向き）[知識]"]]},{"g":"つなぎとしての寄り","n":"無限ズーム（Infinite zoom）","b":[["見え方","寄っても寄っても次の絵が出てきて終わりません。"],["作り方","絵Aの中心に絵Bを小さく入れ、Bの中心にCを…と入れ子にします。倍率は等比で（毎秒2倍など：s = 2t）。Aが画面からはみ出たら捨て、次を足します。つなぎ目は絵の中の額・窓・穴に置きます。最後を最初につなげば輪になります。"],["使いどころ","ループ動画、不思議さ、作品紹介。"],["例","ウェブ作品「Zoomquilt」（2004）[知識]。映画の例はなし"]]},{"g":"つなぎとしての寄り","n":"地球から街へ（宇宙ズーム／Cosmic zoom）","b":[["見え方","宇宙から地球→国→街→1人へ（またはその逆）ひと続きで寄ります。"],["作り方","縮尺の違う絵（衛星写真、空撮、地上）を無限ズームと同じ方法で重ね、つなぎ目は雲で隠します。倍率は等比で、1段（10倍）を1〜2秒。"],["使いどころ","場所の紹介、「この広い世界のたった1人」。"],["例","『コンタクト』（1997）冒頭、地球から宇宙の果てまで引いて少女の目につながる [知識]。『メン・イン・ブラック』（1997）最後の引き [知識]"]]},{"g":"つなぎとしての寄り","n":"顕微鏡ズーム（Powers of Ten型）","b":[["見え方","手→皮ふ→細胞→分子と、小さい世界へ段々入っていきます。"],["作り方","宇宙ズームと同じ。10倍ごとに絵を差し替え、画面に倍率の数字を出すと分かりやすいです。"],["使いどころ","科学の説明、体の中、材料の仕組み。"],["例","短編『パワーズ・オブ・テン』（1977）、公園の人から宇宙へ、次に手の中の原子まで [知識]。先行作に短編『Cosmic Zoom』（1968）[知識]"]]},{"g":"つなぎとしての寄り","n":"画面の中の画面へ（Screen in screen）","b":[["見え方","映っているテレビやスマホの画面へ寄り、画面の中の映像がそのまま本編になります。"],["作り方","画面の四隅の位置に次の映像をはめ込み（四隅合わせ）、枠が見えなくなるまで寄ります。逆に引けば「実は画面の中でした」になります。寄り切る直前に走査線やドットを一瞬見せると本物らしくなります。"],["使いどころ","ニュースや配信から現場へ、回想へ、オチ。"],["例","『search／サーチ』（2018）、パソコンの画面の中だけで寄りと移動をして物語を進める [知識]"]]},{"g":"立体の寄り","n":"2.5次元の視差ズーム（写真を層に分ける／Parallax zoom）","b":[["見え方","1枚の写真なのに、寄ると手前の人と背景がずれて動き、立体に見えます。"],["作り方","写真を人物・中景・背景に切り分け、切り抜いた跡を塗って埋めます。層を奥行き順に並べ、手前ほど大きく拡大します（例：背景1.05倍、中景1.12倍、人物1.2倍）。Blenderなら板を奥行きに並べてカメラを前へ。"],["使いどころ","古い写真、ポスター、記録もの。動かしすぎると切り抜きの跡が見えるので拡大は2割まで。"],["例","『くたばれ!ハリウッド』（2002）、この効果の名前の元になった記録映画 [確認]"]]},{"g":"立体の寄り","n":"3Dカメラのズーム（3D camera zoom）","b":[["見え方","3Dの場面で、ズーム（平ら）とドリー（奥行き）を自由に選べます。"],["作り方","Blenderで焦点距離 camera.data.lens を動かすとズーム、camera.location を動かすとドリー。画角は 2*atan(36/(2*焦点距離))（36はセンサー幅mm）。18mmは広くゆがみ、85mm以上は平たく落ち着きます。"],["使いどころ","迷ったら「気持ちの寄り＝ドリー、指さし＝ズーム」。"],["例","見本 ZM01（自作）"]]},{"g":"立体の寄り","n":"カメラマップ（カメラプロジェクション／Camera projection）","b":[["見え方","1枚の絵や写真なのに、カメラが中へ入っていけるように見えます。視差ズームより本格的な立体です。"],["作り方","絵の形に合わせた簡単な立体（箱や板）を作り、絵を撮った位置から立体へ映写機のように絵を貼ります。その後、別のカメラを少し動かします。絵に写っていない側面は見えないので、動きは小さく（角度で10〜15度まで）。"],["使いどころ","背景画の中へ寄る、建物の間を進む。"],["例","なし（背景画の定番の技法ですが、具体的な作品の場面は確かめられませんでした）[不明]"]]},{"g":"アニメの寄り","n":"T.U（トラックアップ）","b":[["見え方","絵が大きくなります。アニメでは「画を拡大して撮ること」をまとめてT.Uと呼びます [確認]。"],["作り方","昔は撮影台のカメラを絵に近づけました。今は撮影ソフトで絵を拡大します。絵コンテには始まりと終わりの枠（フレーム）を描きます。拡大で線が太く荒れるので、大きく寄る時は大きな紙に描いておきます。"],["使いどころ","実写のズームイン・ドリーインと同じ。動かす枚数を増やさずに動きを足せます。"],["例","なし（ほぼ全ての作品で使われます）"]]},{"g":"アニメの寄り","n":"T.B（トラックバック）","b":[["見え方","絵が小さくなり、周りが見えてきます [確認]。"],["作り方","T.Uの逆。終わりの枠が一番広いので、その広さの絵を用意します。"],["使いどころ","状況の説明、場面の終わり、孤独。"],["例","なし"]]},{"g":"アニメの寄り","n":"Q.T.U（急な寄り／クイックT.U）","b":[["見え方","一瞬で寄るT.U。実写の急ズームにあたります。"],["作り方","2〜6コマで拡大。途中のコマにぶれ（放射ブラー）や集中線を足します。"],["使いどころ","驚き、ギャグ、決め台詞の前。"],["例","なし。名前の意味（Qはクイック）は検索では確かめられませんでした [知識]"]]},{"g":"アニメの寄り","n":"密着マルチの寄り","b":[["見え方","手前・人物・背景が別々の速さで動いて、奥行きが出ます。密着マルチは、層の間を離さず重ねたまま、動かす速さの差だけで奥行きを出すやり方です [確認]。"],["作り方","寄りの時は層ごとに拡大率を変えます（手前の草1.3倍、人物1.15倍、背景1.05倍）。横の動きなら手前ほど速くずらします。"],["使いどころ","歩く場面の背景、広い景色への寄り。"],["例","なし。寄りでの数字の目安は一般の考え方からの見立てです [推測]"]]},{"g":"寄りの気持ち","n":"気づき・決意の寄り","b":[["見え方","考えている顔へゆっくり近づき、止まった所で表情が変わります。"],["作り方","ドリーインを1〜4秒、胸から上→顔。音を少し絞ると内面へ入った感じが強まります。"],["使いどころ","場面の転換点に1回。全員に使うと効かなくなります。"],["例","『ジュラシック・パーク』（1993）[知識]"]]},{"g":"寄りの気持ち","n":"驚きの顔への寄り（スピルバーグ・フェイス）（追加）","b":[["見え方","何かを見上げて口を開けた顔へ寄ります。見ている物は後で見せます。"],["作り方","顔へのドリーインを先に、見ている物のカットを後に置きます。目に光を入れます。"],["使いどころ","すごい物の登場前。「何を見ているのか」を待たせます。"],["例","『未知との遭遇』（1977）、『ジュラシック・パーク』（1993）[知識]"]]},{"g":"寄りの気持ち","n":"恐怖の寄り","b":[["見え方","とても遅い寄り、または逆にドリーズーム。"],["作り方","ゆっくりズームを20秒以上、音は低い持続音。または衝撃の瞬間にドリーズームを1〜2秒。"],["使いどころ","何も起きていないのに怖い場面。寄る先に何もない（空の廊下、扉）とさらに怖くなります。"],["例","『シャイニング』（1980）[知識]、『ジョーズ』（1975）[確認]"]]},{"g":"寄りの気持ち","n":"笑いの寄り（急ズーム）","b":[["見え方","変な発言や顔へ、一瞬で寄ります。"],["作り方","急ズーム3〜6コマ、効果音つき。寄った後に1秒ほど黙って止めるのがコツです。"],["使いどころ","ツッコミ、気まずさ。続けて2回やると2回目がさらに笑えます。3回以上はくどいです。"],["例","『ザ・オフィス』（米国版）[知識]、『ショーン・オブ・ザ・デッド』（2004）[知識]"]]},{"g":"寄りの気持ち","n":"孤独の引き","b":[["見え方","人物から離れていき、広い場所に小さく残されます。"],["作り方","ドリーアウトかズームアウトを5〜15秒。終わりの構図で人物を画面の高さの1/5以下に。終わってから2〜3秒そのまま見せます。"],["使いどころ","別れの後、負けた後、物語の終わり。"],["例","『バリー・リンドン』（1975）の人物から風景への引き [知識]"]]},{"g":"寄りの気持ち","n":"秘密を明かす引き","b":[["見え方","寄りの絵から引くと、見えていなかった物（大勢の人、こわれた街、実は画面の中）が現れます。"],["作り方","始まりの枠は「何も問題なく見える」範囲に切ります。見せたい物が入る直前まで遅く、そこから少し速く引きます。"],["使いどころ","種明かし、規模を見せる、オチ。"],["例","『風と共に去りぬ』（1939）駅前で引いていくと負傷兵が一面に広がる [知識]。『メン・イン・ブラック』（1997）の最後 [知識]"]]},{"g":"足した項目：寄りの計算","n":"寄りの速さの曲線と倍率の計算（追加）","b":[["見え方","同じ寄りでも曲線で印象が変わります。等速＝機械的・不安、なめらか＝自然、出だしが速い＝衝撃。"],["作り方","進み具合 t（0〜1）に対して、なめらか t*t*(3-2*t)、出だしが速い 1-(1-t)3、行きすぎて戻る 1+2.7*(t-1)3+1.7*(t-1)2（途中で約1.1まで行きすぎて1に戻る）。大きく寄る時（3倍以上）は倍率を等比で動かします（s = s0*(s1/s0)t）。足し算で動かすと後半が遅く見えます。"],["使いどころ","ゆっくりズームは等速、気づきの寄りはなめらか、急ズームは出だしが速い曲線。"],["例","なし（計算の手引き）"]]}],"02":[{"g":"首を振る","n":"パン（Pan）","b":[["見え方","カメラが左右へ首を振り、景色が横へ流れます。"],["作り方","三脚の上で水平に回します。Blenderはカメラを縦軸まわりに回転（rotation_euler の上下軸）。90度を3〜6秒が見やすい速さ。始めと終わりをなめらかに。平面で真似るなら横長の絵を横へずらします（本物は端が少しゆがみますが、ほぼ同じに見えます）。"],["使いどころ","場所の紹介、視線の移動、2人の間の行き来。速すぎるとカクカク見えます（物が画面を横切るのに7秒以上かけるのが昔からの目安）[知識]。"],["例","『グランド・ブダペスト・ホテル』（2014）の真横へ直角に振るパン [知識]"]]},{"g":"首を振る","n":"ティルト（Tilt）","b":[["見え方","カメラが上下へ首を振ります。足元から顔へ、空から地面へ。"],["作り方","三脚で上下に回します。Blenderはカメラ自身の横軸まわりに回転。平面なら縦長の絵を縦へずらします。"],["使いどころ","高い物の大きさを見せる（下から上へ）、人物の登場（靴から顔へ）、場面の始まり（空から下りる）。"],["例","『スター・ウォーズ』（1977）冒頭、星空から下へ振ると惑星と宇宙船が現れる [知識]"]]},{"g":"首を振る","n":"ロール（ダッチロール／Roll）","b":[["見え方","画面が時計のように回り、水平線が傾きます。"],["作り方","レンズの向いている軸まわりにカメラを回します。Blenderはカメラ自身の前後軸の回転。平面なら絵を回転（角が切れるので1.2〜1.5倍に拡大してから）。10〜20度の傾きで不安、180度で「世界が逆さ」。3〜8秒かけてゆっくり。"],["使いどころ","混乱、力関係がひっくり返る、酔い。傾けたまま止めると「ダッチアングル」になります。"],["例","『ブラックパンサー』（2018）で敵役が玉座の間へ入る時、逆さの絵から回って正しい向きになる [確認]"]]},{"g":"首を振る","n":"ウィップパン","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","会話や演奏で2人の間を一瞬で行き来して熱を上げる、または流れの中でカットして場所を飛ばす（つなぎ）のに使います。"],["例","『セッション』（2014）最後の演奏で指揮者とドラムの間を速く振る [知識]"]]},{"g":"首を振る","n":"つけパン（人を追う／Follow pan）","b":[["見え方","動く人を画面の同じ所に置いたまま、カメラが首を振って追います。背景が流れます。"],["作り方","人の進む先を少し広く空けます（進む側に画面の1/3）。Blenderではカメラに「対象へ向く」制約（Track To）を付け、少し遅れて追うと人間らしくなります。望遠で追うと背景が速く流れて速さが出ます。"],["使いどころ","走る、歩く、車。位置を動かさずに速さを見せられる、一番安い追い方です。"],["例","『七人の侍』（1954）で走る侍や馬を望遠で追う [知識]"]]},{"g":"体ごと動く","n":"ドリー（Dolly）","b":[["見え方","台車に乗ったカメラが、すべるように前後へ動きます。"],["作り方","レールや平らな床に台車。Blenderは camera.location を直線に動かします。人の歩く速さは秒速1〜1.4m。前後の使い分けは 技法01_ズームと寄り のドリーイン・ドリーアウト。"],["使いどころ","気持ちを強める寄り、人と一緒に進む移動。"],["例","『突撃』（1957）、塹壕の中を進む将校の前をカメラが下がっていく [知識]"]]},{"g":"体ごと動く","n":"トラック（横移動／Tracking shot, Truck）","b":[["見え方","カメラが真横へすべり、手前の柱は速く、奥の山はゆっくり流れます。"],["作り方","レールを被写体の動きと平行に。平面で真似るなら層を分け、「ずらす量＝カメラの移動量×焦点距離÷その層までの距離」で動かします（手前ほど大きく）。"],["使いどころ","長い列や並びを見せる、横に進む戦い、絵巻物のような語り。"],["例","『オールド・ボーイ』（2003）、廊下での戦いを真横から追い続ける [知識]"]]},{"g":"体ごと動く","n":"ペデスタル（上下／Pedestal, Boom up/down）","b":[["見え方","カメラが向きを変えずに、まっすぐ上や下へ動きます。ティルトと違い、見上げ・見下ろしになりません。"],["作り方","昇降する柱や小さなクレーン。Blenderは高さ（Z）だけ動かします。座る人に合わせて下がる、立つ人に合わせて上がる時は、人の頭の動きと同じ速さで。"],["使いどころ","立つ・座るに付き添う、机の上から顔へ、塀の向こうを見せる。"],["例","なし"]]},{"g":"体ごと動く","n":"クレーン・ジブ（Crane, Jib）","b":[["見え方","カメラが大きく弧を描いて上がり下がりします。地面から屋根の上へ、空から人へ。"],["作り方","長い腕の先にカメラ（小さい物がジブ、腕が伸び縮みする物もあります）。Blenderでは高さと前後を同時に動かし、向きは人へ向け続けます。5〜15秒、等速に近く。"],["使いどころ","場面の始まり（下りてくる）と終わり（上がって引く）、広さの中の1人。"],["例","『黒い罠』（1958）冒頭、車を追って街の上を動く長いクレーン撮影 [知識]。『真昼の決闘』（1952）、上がっていくと人のいない通りに保安官が1人 [知識]"]]},{"g":"体ごと動く","n":"アーク（回り込み／Arc shot）","b":[["見え方","人を中心に、カメラが弧を描いて横から回り込みます。背景が人の後ろを流れます。"],["作り方","円形のレール、またはステディカム。Blenderは人の位置に空の目印を置き、カメラをその子にして目印を回すか、円の道に沿わせて人へ向けます。位置は x=r*cos(a), y=r*sin(a)。90度を3〜5秒。"],["使いどころ","決意、見つめ合う、力がみなぎる。背景に光や物があると流れが見えて効きます。"],["例","なし（次の360度の例を参照）"]]},{"g":"体ごと動く","n":"360度まわり込み（360 arc, Hero shot）","b":[["見え方","人のまわりを1周以上します。世界がその人を中心に回ります。"],["作り方","アークを360度まで。1周6〜12秒。照明や機材が映るので、実写は難しく、コードは簡単です。人が逆向きに回ると速さが倍に見えます。"],["使いどころ","踊り、口づけ、仲間がそろう、追いつめられて囲まれる。長いと目が回ります。"],["例","『キャリー』（1976）、舞踏会で踊る2人のまわりをぐるぐる回る [知識]。『バッドボーイズ』（1995）、立ち上がる2人を低い位置から回り込む [知識]"]]},{"g":"体ごと動く","n":"フォロー（後ろから／Follow shot）","b":[["見え方","歩く人の背中や後頭部を、後ろから付いていきます。"],["作り方","ステディカムやジンバルで1〜2m後ろ、肩〜頭の高さ。Blenderは人の位置から後ろへ一定の距離を保ち、少し遅れて追います（位置をなめらかにならす）。"],["使いどころ","その人と一緒に場所へ入る、行き先が分からない不安。顔が見えないので、気持ちは場所と背中で語ります。"],["例","『エレファント』（2003）、学校の廊下を歩く生徒の後ろを長く付いていく [知識]"]]},{"g":"体ごと動く","n":"リード（前から引く／Leading shot）","b":[["見え方","歩いてくる人の前を、カメラが後ろ向きに下がりながら顔を映します。"],["作り方","カメラ係が後ろ歩き（補助の人が支えます）。距離を一定に。Blenderは人の進む向きの前方に置きます。"],["使いどころ","歩きながらの会話、決意して進む顔。"],["例","テレビ『ザ・ホワイトハウス』（1999〜2006）の歩きながらの会話 [知識]。『突撃』（1957）の塹壕 [知識]"]]},{"g":"体ごと動く","n":"横並走（Side tracking）","b":[["見え方","走る人・車の真横を同じ速さで進みます。人は画面の同じ所、背景だけが流れます。"],["作り方","車、レール、ジンバル。カメラの速さ＝人の速さ。手前に木や柵を通すと速さが出ます。"],["使いどころ","走り続ける、逃げる、旅。"],["例","『大人は判ってくれない』（1959）最後、海へ向かって走る少年に並んで進む [知識]"]]},{"g":"支え方","n":"三脚の固定（Tripod, Locked-off）","b":[["見え方","画面がまったく動きません。"],["作り方","三脚に固定。コードではカメラを動かさないだけ。"],["使いどころ","落ち着き、観察、絵のような構図。合成（同じ人を2人映す等）にも必要です。"],["例","『東京物語』（1953）、低い位置に据えたほぼ動かないカメラ [知識]"]]},{"g":"支え方","n":"手持ち（Handheld）","b":[["見え方","小さく不規則に揺れ、息づかいを感じます。"],["作り方","手で持ちます。コードではなめらかな乱数（ノイズ）で、位置を画面の0.5〜1.5%、回転を0.3〜1度、1秒に1〜3回ゆらします。規則的な波（サイン波）は不自然なので使いません。"],["使いどころ","記録映像の本物らしさ、緊張、混乱。大きく揺らしすぎると酔います。"],["例","『ブレア・ウィッチ・プロジェクト』（1999）[知識]、『ボーン・スプレマシー』（2004）の格闘 [知識]"]]},{"g":"支え方","n":"ステディカム（Steadicam）","b":[["見え方","歩いて移動しているのに揺れず、浮いてすべるように進みます。"],["作り方","体に着ける腕とばねで揺れを消す道具。コードでは道すじをなめらかな曲線にし、上下に小さなゆるい浮き沈み（1秒に1回以下、ごく小さく）だけ残します。"],["使いどころ","廊下や階段を通る長い移動、人を追う長回し。"],["例","『シャイニング』（1980）、三輪車の子を低い位置で追う [知識]。『ロッキー』（1976）の階段 [知識]。『グッドフェローズ』（1990）、裏口から店の中へ続く長回し [知識]"]]},{"g":"支え方","n":"ジンバル（Gimbal）","b":[["見え方","ステディカムに近いなめらかさ。回転の揺れはモーターで消えますが、歩く上下動が少し残ります。"],["作り方","モーターで水平を保つ持ち手。コードでは回転の揺れを0にし、歩みに合わせた上下動（1秒に2回、ごく小さく）だけ足します。"],["使いどころ","少人数での移動撮影、旅動画、低い位置や狭い所。"],["例","なし"]]},{"g":"支え方","n":"スライダー（Slider）","b":[["見え方","数十cm〜1mだけ、ゆっくり正確に横や前へすべります。"],["作り方","短いレール。コードでは短い直線の動きを5〜10秒かけて等速で。手前に物を置くと、短い動きでも視差が出ます。"],["使いどころ","商品、料理、インタビューの導入。小さな動きで高級感を出します。"],["例","なし"]]},{"g":"支え方","n":"ショルダー（Shoulder rig）","b":[["見え方","肩に載せた、手持ちより重く落ち着いた揺れ。"],["作り方","肩のせの台。コードでは手持ちの揺れを半分の速さ・半分の大きさにし、呼吸のゆっくりした上下を足します。"],["使いどころ","報道、記録、長時間の密着。"],["例","なし"]]},{"g":"支え方","n":"車載（Car mount）","b":[["見え方","車の中や外に付けたカメラ。車は止まって見え、外の景色だけが流れます。"],["作り方","吸盤や枠で車に固定、または別の車から腕で伸ばします。コードではカメラを車の子にして、道のでこぼこの細かい揺れ（速く小さい）を足します。"],["使いどころ","追跡、車内の会話、旅。"],["例","『ブリット』（1968）の坂の街の追跡 [知識]。『トゥモロー・ワールド』（2006）、車内でカメラが動き回る長回し [知識]"]]},{"g":"支え方","n":"ケーブルカム（Cable cam）","b":[["見え方","張った綱に沿って、空中をまっすぐ速くすべります。"],["作り方","2点（または4点）の間に綱を張ってカメラを走らせます。コードでは高い位置の直線の道を一定の速さで。"],["使いどころ","競技場、ビルの谷間、森の上。ドローンより速く正確で、人の近くでも安全です。"],["例","『スパイダーマン』（2002）、ビルの間を飛ぶ絵に綱のカメラ（Spydercam）が使われた [確認]"]]},{"g":"支え方","n":"ドローン（Drone）","b":[["見え方","空からの広い絵、ゆっくり上がる・進む・回る動き。"],["作り方","無人機にジンバル付きのカメラ。コードでは高い位置のなめらかな道、広角（焦点距離24mm前後）、ゆっくり等速。"],["使いどころ","場所の紹介、追跡の俯瞰、終わりの余韻。"],["例","『007 スカイフォール』（2012）冒頭、屋根の上のバイクの追跡の一部 [確認]"]]},{"g":"支え方","n":"FPVドローン（FPV drone）","b":[["見え方","鳥や弾丸のように、すき間を抜け、急降下し、体ごと傾いて曲がります。"],["作り方","操縦者がゴーグルで見ながら飛ばす小型機。コードでは道すじを曲線にし、曲がる時に内側へ傾け（ロール）、超広角（焦点距離12〜16mm）で速さを出します。"],["使いどころ","建物の中を通り抜ける紹介、アクション、スポーツ。"],["例","『アンビュランス』（2022）、ビルの壁を急降下する絵 [知識]"]]},{"g":"支え方","n":"モーションコントロール（Motion control）","b":[["見え方","機械がまったく同じ動きを何度でもくり返します。その結果、同じ人を2人映す、模型と実写を重ねる、といった合成ができます。"],["作り方","コンピュータで動く台やロボットの腕。コードのカメラは元から毎回同じ動きなので、同じ動きで層を別々に描いて重ねれば同じことができます。"],["使いどころ","1人2役、模型の宇宙船、人だけ消える、季節が変わる。"],["例","『スター・ウォーズ』（1977）の宇宙船の模型撮影 [知識]"]]},{"g":"支え方","n":"スノーリカム（体に固定／SnorriCam）","b":[["見え方","顔は画面の真ん中で止まったまま、背景だけがぐらぐら動きます。"],["作り方","役者の体に枠を着け、カメラを顔へ向けて固定します。コードではカメラを人物の胸の子にして、顔へ向けます。"],["使いどころ","酔い、動揺、追いつめられた感じ。数秒で十分です。"],["例","『レクイエム・フォー・ドリーム』（2000）[知識]。『ミーン・ストリート』（1973）の酔った場面 [知識]"]]},{"g":"支え方","n":"ボディマウント（Body mount）","b":[["見え方","体や道具に付けたカメラの絵。頭や胸に付ければ主観、腕や武器、扉に付ければその物と一緒に動きます。"],["作り方","頭・胸・手首・道具に小型カメラ。コードではカメラを動く物の子にします。スノーリカムは「顔へ向けた」ボディマウントの一種です。"],["使いどころ","スポーツ、アクション、物の目線。"],["例","『ハードコア』（2015）、頭に付けたカメラで全編を主観で進める [知識]"]]},{"g":"特別な動き","n":"長回し（ワンカット／Long take, Oner）","b":[["見え方","カットせずに長く続き、その場に居続ける感じがします。"],["作り方","人の動きとカメラの道すじを振り付けのように決め、何度も練習します。コードでは1本の道すじの上に見せ場（止まる所・寄る所）を順に並べます。"],["使いどころ","緊張を切らさない、場所の全体を分からせる。技の見せびらかしになりやすいので、理由がある場面に。"],["例","『エルミタージュ幻想』（2002）、全編が本当に1カット [知識]。『トゥモロー・ワールド』（2006）の市街戦 [知識]"]]},{"g":"特別な動き","n":"見せかけのワンカット（Hidden cut oner）","b":[["見え方","1カットに見えますが、実はいくつかのカットをつないでいます。"],["作り方","つなぎ目を「暗がり・人の背中・柱が画面をふさぐ瞬間・速いパンの流れ」に隠します。前後のカットで動く向きと速さをそろえます。"],["使いどころ","長回しをしたいが一度に撮れない時。"],["例","『1917 命をかけた伝令』（2019）[知識]、『バードマン』（2014）[知識]、『ロープ』（1948）で背中の暗がりに隠す [知識]"]]},{"g":"特別な動き","n":"POV（主観／Point of view）","b":[["見え方","登場人物の目で見た絵。"],["作り方","目の高さ（立って約1.5〜1.6m）、広めのレンズ、歩みの揺れ、画面の下に手。まばたき（黒を2〜3コマ）や息の音を足すと強まります。"],["使いどころ","見る人を本人にする、犯人の正体を隠す、ゲームのような体験。"],["例","『湖中の女』（1947）、ほぼ全編が主人公の目線 [知識]。『ハロウィン』（1978）冒頭 [知識]"]]},{"g":"特別な動き","n":"バレットタイム（Bullet time）","b":[["見え方","時間がほぼ止まり、カメラだけが人のまわりを回ります。"],["作り方","実写は多数のカメラを弧に並べて順に撮り、間のコマを作って補います。コードでは人や物の動きを止め（または1/20の速さに）、カメラだけアークさせます。"],["使いどころ","一撃の瞬間、弾をよける、決めの形。"],["例","『マトリックス』（1999）、屋上で弾をよける [知識]"]]},{"g":"特別な動き","n":"カメラが物を通り抜ける（Impossible camera move）","b":[["見え方","カメラが鍵穴、窓ガラス、壁、床を抜けて進みます。"],["作り方","実写は壁を外せる作りにするか、CGでつなぎます。コードではカメラを抜けさせ、その瞬間だけ手前の面を消す（近くを描かない距離＝クリップを使う）か、穴を通します。"],["使いどころ","家の全体を見せる、のぞき見る、人には行けない所へ。"],["例","『パニック・ルーム』（2002）、家の中を階を越え、取っ手の輪や鍵穴を抜けて進む [知識]。『市民ケーン』（1941）、看板と天窓を抜けて店へ入る [知識]"]]},{"g":"特別な動き","n":"リビール（隠して見せる／Reveal）","b":[["見え方","カメラが動くと、隠れていた物や人が現れます。"],["作り方","手前の壁・人・物でかくしておき、横移動・パン・上昇・引きで見せます。見せる瞬間に音や動きを合わせます。"],["使いどころ","登場、驚き、笑いのオチ、規模を見せる。"],["例","『風と共に去りぬ』（1939）の駅前の引き [知識]（技法01「秘密を明かす引き」と同じ）"]]},{"g":"特別な動き","n":"カメラの揺れ（地震・衝撃）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","爆発や巨大な物の足音で、音と同じコマに揺らします。戦場では手持ちの揺れと組み合わせます。"],["例","『プライベート・ライアン』（1998）冒頭の上陸の場面 [知識]"]]},{"g":"特別な動き","n":"ダブルドリー（人も台車に乗せる／Double dolly）","b":[["見え方","人が歩いていないのに、すべるように前へ進みます。背景だけが流れます。"],["作り方","カメラと役者を同じ台車（または2台）に乗せて一緒に動かします。コードでは人とカメラの距離を固定し、足を動かさずに両方を進めます。"],["使いどころ","何かに引かれる、夢の中、覚悟を決めた歩み。"],["例","スパイク・リー監督の作品の定番。『マルコムX』（1992）[知識]、『25時』（2002）[知識]"]]},{"g":"特別な動き","n":"回転する部屋（Rotating set）","b":[["見え方","人が壁や天井を歩いたり、重力の向きが変わって転がったりします。"],["作り方","部屋の作り物ごと回し、カメラを部屋に固定します（カメラからは部屋が止まって見え、人だけが壁へ移る）。コードでは部屋とカメラを同じ親にして回すか、重力の向きを変えます。"],["使いどころ","無重力、夢、踊り。"],["例","『恋愛準決勝戦』（1951）、壁と天井で踊る [知識]。『インセプション』（2010）の廊下の戦い [知識]。『2001年宇宙の旅』（1968）の輪の形の船内 [知識]"]]},{"g":"動かさない選択","n":"フィックスの長回し（Static long take）","b":[["見え方","動かないカメラで、長い時間そのまま見せます。"],["作り方","構図を1つ決め、手前・中・奥に人や動きを配置します。30秒〜数分。コードではカメラ固定、中の物だけ動かします。"],["使いどころ","日常の重さ、気まずい間、冷めた笑い。見る人が自分で見る所を探します。"],["例","『ジャンヌ・ディエルマン』（1975）、家事を動かないカメラで長く見せる [知識]"]]},{"g":"動かさない選択","n":"人の出入りだけで語る（Staging in a fixed frame）","b":[["見え方","カメラは動かず、人が画面に入る・出る・奥から手前へ来ることで話が進みます。"],["作り方","扉や廊下を画面の奥に置き、出入り口を2つ以上作ります。誰もいない画面を1〜2秒残してから切ると余韻が出ます。"],["使いどころ","家族の場面、すれ違い、広い画面のあちこちで起きる笑い。"],["例","『東京物語』（1953）[知識]、『プレイタイム』（1967）、広い画面の中で小さな出来事が同時に起きる [知識]"]]},{"g":"足した項目","n":"動機のある動き／ない動き（追加／Motivated camera movement）","b":[["見え方","人が立つ→カメラも上がる、のように何かに合わせた動きは気づかれません。理由なく動くと「誰かが見ている」ように感じます。"],["作り方","動き始めを人の動き・音・視線の0〜3コマ後に合わせます。わざと不気味にしたい時だけ、誰も動いていない時に動かします。"],["使いどころ","ふつうは動機あり。怖い場面や語り手の存在を出す時は動機なし。"],["例","なし（考え方）"]]},{"g":"足した項目","n":"微速の漂い（ドリフト）（追加／Drift）","b":[["見え方","止まって見えるほど小さく、ゆっくり横や前へ流れます。"],["作り方","10秒で数cm、または画面の1〜2%だけ等速で動かします。固定の絵が「写真」に見えてしまう時に足します。"],["使いどころ","会話、風景、写真やイラストの絵。コードで作る動画の基本の味つけです。"],["例","なし"]]},{"g":"足した項目","n":"ハイパーラプス（追加／Hyperlapse）","b":[["見え方","早回しのまま、カメラが長い距離を進みます。"],["作り方","数歩ずつ動いては1枚撮るのをくり返し、後で揺れを消します。コードでは長い道すじを短い時間で進め、雲や人だけ速く動かします。"],["使いどころ","街の紹介、旅、時間の経過。コマ数の話は R4（コマ数・シャッター）で扱います。"],["例","なし"]]},{"g":"足した項目","n":"視差の計算（追加／Parallax）","b":[["見え方","カメラが横へ動くと、近い物は大きく、遠い物は小さく動きます。これが奥行きの正体です。"],["作り方","画面上のずれ＝カメラの移動量×焦点距離÷距離（に比例）。層が3つなら、距離2m・5m・20mで動きは10：4：1。首振り（パン・ティルト）ではこの差は出ません。"],["使いどころ","平面の絵で体ごと動く動き（トラック、アーク、ドリー）を真似る時の基本です。"],["例","なし（計算の手引き）"]]}],"03":[{"g":"大きさ","n":"超ロングショット（Extreme Long Shot / ELS、遠景）","b":[["見え方","人が豆つぶほどで、景色が主役です。"],["作り方","広角（14〜24mm）で遠くから、または望遠で数百m先から撮ります。コードでは人の高さが画面の1/10以下になる距離までカメラを下げます（50mmなら49m以上）。"],["使いどころ","世界の広さ、旅、孤独。長すぎると話が止まります。"],["例","アラビアのロレンス（1962）砂漠の地平線の点が、少しずつ人の姿になる場面 [知識]"]]},{"g":"大きさ","n":"ロングショット（Long Shot / LS）","b":[["見え方","人の全身と、その周りの場所がたっぷり見えます。人は画面の高さの1/3〜1/2ほどです。"],["作り方","50mmなら10〜12m。人の動きと場所の関係が分かる位置に置きます。"],["使いどころ","動き（走る・戦う・踊る）を見せるとき。表情は読めないので感情の山場には向きません。"],["例","なし"]]},{"g":"大きさ","n":"フルショット（Full Shot / FS）","b":[["見え方","頭の上から足の先まで、ちょうど全身が入ります。"],["作り方","50mmで約4.9m。頭の上と足の下に少しだけ空きを残します。足首で切ると不自然に見えます。"],["使いどころ","服装、体つき、ダンスや殺陣（たて）。体全体の演技を見せたいとき。"],["例","雨に唄えば（1952）雨の中で歌い踊る場面を全身で見せる [知識]"]]},{"g":"大きさ","n":"カウボーイショット（Cowboy Shot、ひざ上）【足した技法】","b":[["見え方","ひざ（太もも）から上が入ります。"],["作り方","50mmで約3.2m。腰の銃や手に持った物が切れない高さにします。"],["使いどころ","立ち姿のかっこよさと表情を両方見せたいとき。西部劇の決闘から名前が付きました。"],["例","続・夕陽のガンマン（1966）墓地での三つ巴の決闘 [知識]"]]},{"g":"大きさ","n":"ミディアムショット（Medium Shot / MS）","b":[["見え方","腰のあたりから上。人と話すときに見える自然な範囲です。"],["作り方","50mmで約2.5m。手の動きが入るようにします。"],["使いどころ","会話、説明。一番「ふつう」の大きさで、ここを基準に寄り引きを決めます。"],["例","なし"]]},{"g":"大きさ","n":"ウエストショット（Waist Shot）","b":[["見え方","腰（ベルトの位置）から上。日本の現場での呼び方で、ミディアムショットとほぼ同じです。"],["作り方","ミディアムと同じ。ベルトの少し下で切るときれいです。関節（ひじ・手首・腰骨）ちょうどで切らないのがコツです。"],["使いどころ","身ぶりを交えた会話、テレビの立ちレポート。"],["例","なし"]]},{"g":"大きさ","n":"バストショット（Bust Shot / Medium Close-Up）","b":[["見え方","胸から上。表情がよく見え、少しだけ体も見えます。"],["作り方","50mmで約1.5m。顔がゆがまないよう50〜85mmを使います。目の高さを画面の上から1/3に置きます。"],["使いどころ","インタビュー、会話の切り返し。もっとも出番が多い大きさです。"],["例","なし"]]},{"g":"大きさ","n":"クローズアップ（Close-Up / CU）","b":[["見え方","顔が画面いっぱい。日本の現場では「アップ」とも言います。"],["作り方","85mm前後で1.5mほど（50mmなら0.9m）。広角で寄ると鼻が大きくゆがむので、望遠寄りで撮ります。ピントは手前の目に合わせます。"],["使いどころ","気持ちが動く瞬間。ずっとアップだと効き目がなくなるので、山場まで取っておきます。"],["例","裁かるるジャンヌ（1928）ほぼ全編が顔のアップの連続 [知識]"]]},{"g":"大きさ","n":"超クローズアップ（Extreme Close-Up / ECU）","b":[["見え方","目だけ、口だけ、指先だけ。"],["作り方","マクロレンズか望遠で寄ります。コードでは写る高さ10cmほど。被写界深度（ピントが合う奥行き）がとても浅くなるので、絞りをF8以上にするか距離を固定します。"],["使いどころ","緊張の頂点、細部の合図。短く使います。"],["例","続・夕陽のガンマン（1966）決闘で3人の目だけを交互に映す [知識]"]]},{"g":"大きさ","n":"インサート（Insert、物のアップ）","b":[["見え方","手紙、時計、スマホの画面など、物だけのアップです。"],["作り方","その場面の光と向きを合わせて物だけを撮ります。1〜2秒で足ります。コードでは同じ場面のカメラを物の前に飛ばすだけです。"],["使いどころ","「これを見て」と情報を渡すとき。テンポよく重ねるとリズムも作れます。"],["例","レクイエム・フォー・ドリーム（2000）薬を使う手順を、物のアップの速い連続で見せる [知識]"]]},{"g":"大きさ","n":"エスタブリッシングショット（Establishing Shot、場所の紹介）","b":[["見え方","建物の外観や街の全景。場面の最初に置かれます。"],["作り方","超ロング〜ロングで2〜4秒。時刻（朝・夜）と天気も一緒に伝えます。空撮やゆっくりした移動を付けると豪華に見えます。"],["使いどころ","場所や時間が変わったとき。毎回入れると遅くなるので、2回目以降は省くか短くします。"],["例","ブレードランナー（1982）冒頭、炎を上げる未来のロサンゼルスの夜景 [知識]"]]},{"g":"大きさ","n":"マスターショット（Master Shot）","b":[["見え方","その場面の全員と場所が入った、通しの引きの画です。"],["作り方","場面を最初から最後まで1台で通して撮ります。あとで寄りの画を挟むための「土台」になります。コードでは引きのカメラを1台置いて全尺を出し、寄りは別カメラで同じ動きを撮ります。"],["使いどころ","誰がどこにいるかを見失わせないため。編集で迷ったら戻る場所です。"],["例","なし"]]},{"g":"人数と向き","n":"シングル（Single）","b":[["見え方","1人だけが映ります。"],["作り方","他の人を画面に入れない（クリーンシングル）。大きさはバスト〜アップが多いです。"],["使いどころ","その人の考えに集中させたいとき。会話で相手を入れないと、2人の心の距離が遠く見えます。"],["例","なし"]]},{"g":"人数と向き","n":"ダーティシングル（Dirty Single）【足した技法】","b":[["見え方","1人が主役ですが、手前に相手の肩や髪が少しだけぼけて入ります。"],["作り方","相手の体を画面の端に5〜15%だけ入れます。肩ごしより入る量が少ないものです。"],["使いどころ","相手の存在を感じさせながら、主役の顔に集中させたいとき。"],["例","なし"]]},{"g":"人数と向き","n":"ツーショット（Two Shot）","b":[["見え方","2人が同じ画面に入ります。"],["作り方","横並び、向かい合い、前後（1人手前・1人奥）の3つの置き方があります。2人のすき間の広さがそのまま関係の近さに見えます。"],["使いどころ","関係そのものを見せたいとき。切らずに長く回すと、気まずさや親しさが育ちます。"],["例","ビフォア・サンライズ（1995）レコード店の試聴室で、2人が目を合わせられない様子を切らずに映す [知識]"]]},{"g":"人数と向き","n":"スリーショット（Three Shot）","b":[["見え方","3人が入ります。"],["作り方","三角形に置く（1人を手前や高い位置に）とまとまります。横一列は平等、三角は頂点の人が中心に見えます。"],["使いどころ","2対1の対立、仲間。誰が仲間はずれかを置き方で示せます。"],["例","なし"]]},{"g":"人数と向き","n":"肩ごし（Over The Shoulder / OTS）","b":[["見え方","手前に聞き手の肩と後頭部、その向こうに話し手の顔。"],["作り方","聞き手の斜め後ろにカメラを置き、肩を画面の1/4〜1/3入れます。50〜85mm。コードでは聞き手の頭の後ろ30〜50cm、横に20cmずらして話し手に向けます。"],["使いどころ","会話の基本。2人がつながっている感じが出ます。"],["例","ゴッドファーザー（1972）冒頭、頼みごとをする男からゆっくり引いていくと、聞いているドンの肩と手が現れる [知識]"]]},{"g":"人数と向き","n":"切り返し（Shot / Reverse Shot）","b":[["見え方","話す人Aの画 → 聞く人Bの画 → Aの画、と交互に切り替わります。"],["作り方","2人を結ぶ線（イマジナリーライン）の片側だけにカメラを置きます。Aが右を向いていればBは左を向くようにします。大きさと高さは2人でそろえます。"],["使いどころ","会話。片方だけ大きさや角度を変えると、力関係の変化を表せます。"],["例","ヒート（1995）食堂で刑事と強盗が向かい合って話す場面 [知識]"]]},{"g":"人数と向き","n":"主観ショット（Point of View / POV）","b":[["見え方","登場人物の目に映っているものが、そのまま画面になります。"],["作り方","カメラを目の位置（立って約1.5〜1.6m）に置き、歩きの上下ゆれ（1歩で2〜4cm）や、まばたきの暗転を足します。「見ている顔 → 主観 → 顔」の順にはさむと誰の目かが分かります。"],["使いどころ","その人になりきらせたいとき、のぞき見、怖さ。長いと酔います。"],["例","ハロウィン（1978）冒頭、仮面の穴ごしに家の中を進む長い主観 [知識]／湖中の女（1947）ほぼ全編が主人公の主観 [知識]"]]},{"g":"人数と向き","n":"リアクションショット（Reaction Shot）","b":[["見え方","出来事そのものではなく、それを見ている人の顔。"],["作り方","出来事の直前か直後に、見ている人のバスト〜アップを1〜3秒入れます。出来事より先に顔を見せると期待が高まります。"],["使いどころ","驚き、笑い、恐怖。お笑いの「間」もこれです。出来事を映さず顔だけで済ませる手もあります。"],["例","ジュラシック・パーク（1993）恐竜を見せる前に、見上げて固まる博士たちの顔を先に映す [知識]"]]},{"g":"角度","n":"目の高さ（Eye Level）","b":[["見え方","相手と同じ高さで向き合った、いちばん自然な見え方です。"],["作り方","カメラの高さを相手の目に合わせます（立ち1.5〜1.6m、座り1.1〜1.2m）。上下の傾きは0度。"],["使いどころ","ふつうの会話。色が付かないので、ここを基準に上下させて意味を出します。"],["例","なし"]]},{"g":"角度","n":"ローアングル（Low Angle）","b":[["見え方","下から見上げます。人が大きく、強く見えます。"],["作り方","カメラを腰より下（0.3〜1.0m）に置き、10〜45度上を向けます。広角にすると脚が長く、天井や空が入ります。"],["使いどころ","英雄、権力者、こわい相手。子どもの目線にもなります。"],["例","市民ケーン（1941）選挙に負けた後の場面を、床に穴を掘って置いた低いカメラから撮る [知識]"]]},{"g":"角度","n":"ハイアングル（High Angle）","b":[["見え方","上から見下ろします。人が小さく、弱く見えます。"],["作り方","カメラを頭より上（2〜5m）に置き、20〜60度下を向けます。"],["使いどころ","負け、孤立、追いつめられた感じ。地図のように位置関係を見せる役目もあります。"],["例","北北西に進路を取れ（1959）国連ビルから逃げる主人公を、はるか上から点のように映す [知識]"]]},{"g":"角度","n":"俯瞰（真上）（Overhead / Bird's-Eye View / God's Eye）","b":[["見え方","真上からの見下ろし。人は頭と肩だけになります。"],["作り方","カメラを真上に置き90度下へ向けます。コードでは回転を(0, 0, 0)にして高さだけ上げれば真下を向きます（Blenderの場合）。料理や机の上の動画（トップショット）も同じです。"],["使いどころ","神の目、運命、事件のあと。模様のような美しさも出ます。"],["例","タクシードライバー（1976）銃撃のあと、天井からの真上の目で部屋をゆっくり移動する [知識]"]]},{"g":"角度","n":"あおり（真下から）（Worm's-Eye View）","b":[["見え方","地面から真上近くを見上げます。日本では下から見上げる画を広く「あおり」と呼びますが、ここでは真下に近いものを指します。"],["作り方","カメラを地面に置き60〜90度上へ。広角（14〜24mm）で、建物や木が中心へ倒れこむように見えます。"],["使いどころ","圧倒される大きさ、倒れた人の目線、のぞきこまれる怖さ。"],["例","レザボア・ドッグス（1992）車のトランクの中から、のぞきこむ男たちを見上げる [知識]"]]},{"g":"角度","n":"ダッチアングル（Dutch Angle / Canted Angle、斜め）","b":[["見え方","水平線が傾いています。"],["作り方","カメラをレンズの軸まわりに5〜45度回します（ロール）。コードではカメラの奥行き軸の回転だけ足します。後から編集で回すと四隅が欠けるので、5〜10%拡大します。"],["使いどころ","不安、狂気、世界がおかしい感じ。ずっと使うと慣れて効かなくなります。"],["例","第三の男（1949）戦後のウィーンの場面の多くが傾いている [知識]"]]},{"g":"角度","n":"腰の高さ（Hip Level）","b":[["見え方","腰のあたりから水平に見た画。"],["作り方","カメラ高さ0.9〜1.0m、傾き0度。"],["使いどころ","腰の銃、手に持った物、座った人と立った人の間。西部劇の決闘でよく使います。"],["例","なし"]]},{"g":"角度","n":"地面すれすれ（Ground Level）","b":[["見え方","地面に置いたような低さ。足や車輪が大きく映ります。"],["作り方","高さ0.05〜0.2m、傾きは水平か少し上。移動させるとスピード感が大きく出ます（低いほど地面が速く流れます）。"],["使いどころ","足どり、追跡、子どもや動物の目線。"],["例","シャイニング（1980）ホテルの廊下を三輪車で走る子を、床すれすれで追いかける [知識]"]]},{"g":"角度","n":"畳の高さ（小津のローポジション / Tatami Shot）","b":[["見え方","畳に座った人の目より少し低い位置から、水平に近く見た画。"],["作り方","カメラを床から数十cm（40〜90cmほど。数字は資料により違います）に固定し、ほぼ水平、50mmの標準レンズで動かさずに撮ります。ローアングル（見上げ）ではなくローポジション（位置が低い）なのが要点です。"],["使いどころ","座って暮らす部屋の落ち着き、静かな家族の会話。"],["例","東京物語（1953）室内で座って話す場面のほぼすべて [知識]"]]},{"g":"構図","n":"三分割（Rule of Thirds）","b":[["見え方","主役が真ん中から少しずれた、落ち着いた画。"],["作り方","画面を縦横3等分する線（1/3と2/3の位置）を引き、交点の4つのどこかに目や主役を置きます。地平線は上か下の線に合わせます。コードでは1920×1080なら x=640か1280、y=360か720。"],["使いどころ","迷ったらこれ。安定しますが、ありきたりにもなります。"],["例","なし"]]},{"g":"構図","n":"中心構図・シンメトリー（Center Framing / Symmetry）","b":[["見え方","主役がど真ん中、左右が鏡のように対称。"],["作り方","カメラを対象の真正面に置き、左右の物をそろえます。少しでもずれると気持ち悪いので正確に合わせます。"],["使いどころ","絵本のような整い方、儀式、人工的な世界。速いカットが続くとき、目の置き場所を真ん中にそろえると見やすくなります。"],["例","グランド・ブダペスト・ホテル（2014）ほぼ全編が正面・対称 [知識]／マッドマックス 怒りのデス・ロード（2015）見せたい物を常に画面の中心に置く [知識]"]]},{"g":"構図","n":"一点透視（One-Point Perspective）","b":[["見え方","廊下や道の線が、画面の真ん中の1点へ集まっていきます。"],["作り方","廊下・トンネル・並木の中央に、壁と平行にカメラを置きます。広角（18〜24mm）ほど吸いこまれる感じが強くなります。消える点に主役を置きます。"],["使いどころ","吸いこまれる怖さ、逃げ場のなさ、整然とした美しさ。"],["例","シャイニング（1980）廊下の奥に双子の少女が立っている場面 [知識]"]]},{"g":"構図","n":"対角線構図（Diagonal Composition）","b":[["見え方","主な線が画面の角から角へ斜めに走ります。"],["作り方","道・階段・手すり・腕などを斜めに置きます。カメラを対象に対して30〜45度ふると線が斜めになります。"],["使いどころ","動き、勢い、不安定。水平・垂直だけの画より元気に見えます。"],["例","なし"]]},{"g":"構図","n":"導線（Leading Lines）","b":[["見え方","道、柵、影、視線などの線が、目を主役へ連れて行きます。"],["作り方","線の先（または交わる所）に主役を置きます。線は画面の手前の角から入ると強く効きます。光の筋や人の視線も線として使えます。"],["使いどころ","ごちゃごちゃした場所で主役を見つけてもらうとき。"],["例","なし"]]},{"g":"構図","n":"額縁（Frame within a Frame）","b":[["見え方","戸口、窓、鏡、車の窓などで、主役がもう一つの枠に囲まれます。"],["作り方","手前に枠になる物を置き、その中に主役を入れます。枠は暗く、中は明るくすると目が集まります。"],["使いどころ","のぞき見、閉じこめられた感じ、内と外の区別。"],["例","捜索者（1956）最後、暗い戸口の枠の向こうへ主人公が去っていく [知識]"]]},{"g":"構図","n":"前景・中景・背景の層（Foreground / Middleground / Background）","b":[["見え方","手前・真ん中・奥の3つの層があり、平らな画面に奥行きが出ます。"],["作り方","手前にぼけた物（葉、肩、窓枠）を1つ置き、主役を真ん中、奥に景色。コードでは3つの距離（たとえば0.5m・3m・20m）に物を置き、カメラを横に動かすと層ごとに違う速さでずれて立体感が出ます（視差）。"],["使いどころ","ほぼ常に効きます。層が1つだけの画は紙のように見えます。"],["例","市民ケーン（1941）手前で大人が話し、奥の窓の外で少年が雪遊びをしている場面 [知識]"]]},{"g":"構図","n":"ネガティブスペース（Negative Space、余白）","b":[["見え方","何もない空・壁・闇が画面の大部分をしめ、主役は小さく端にいます。"],["作り方","主役を画面の1/10〜1/4にし、残りは単純な面（空、壁、黒）にします。"],["使いどころ","孤独、静けさ、広さ。空いた所に「何か来そう」と思わせる怖さにも使えます。"],["例","ゼロ・グラビティ（2013）真っ黒な宇宙に小さく浮かぶ人 [知識]"]]},{"g":"構図","n":"ヘッドルームとリードルーム（Headroom / Lead Room）","b":[["見え方","頭の上の空き（ヘッドルーム）と、顔が向いている側の空き（リードルーム、ルッキングルームとも言います）。"],["作り方","目を画面の上から1/3に置くと頭の上は自然に決まります。向いている側を広く（全体の60〜65%）空けます。動く物は進む先を空けます。"],["使いどころ","ふつうは守ります。わざと破ると次の「ショートサイディング」になります。"],["例","なし"]]},{"g":"構図","n":"ショートサイディング（Short-Siding）【足した技法】","b":[["見え方","顔が向いている側が狭く、背中側が広く空いています。"],["作り方","リードルームを逆にして、人を画面の端へ寄せ、端の方を向かせます。"],["使いどころ","息苦しさ、孤立、話が通じていない感じ。"],["例","英国王のスピーチ（2010）主人公を画面の端に寄せ、壁を大きく映す [知識]／MR. ROBOT（2015〜）会話の多くで人物を画面の隅に置く [知識]"]]},{"g":"構図","n":"黄金比（Golden Ratio）","b":[["見え方","三分割より少し中央寄りに主役が来る構図。うず巻き（黄金らせん）の中心に主役を置く形もあります。"],["作り方","画面を1：1.618に分けます。線の位置は端から38.2%と61.8%。1920×1080なら x=733か1187、y=413か667。"],["使いどころ","三分割とほぼ同じ働きです。絵画的に整えたいとき。効果の差は小さく、こだわりすぎなくてよいです。"],["例","なし"]]},{"g":"構図","n":"奥行きの演出（ディープステージング / Deep Staging）","b":[["見え方","手前と奥の両方で同時に芝居が起き、1つの画面の中で目が行き来します。"],["作り方","人を前後に離して置き（たとえば1mと8m）、広角＋絞ったレンズ（F8以上）で両方にピントを合わせます。カットを割らずに、人の出入りで見せ場を変えます。"],["使いどころ","切らずに関係を見せたいとき。見る人が自分で見る所を選べます。"],["例","プレイタイム（1967）広い画面のあちこちで別々の出来事が同時に起きる [知識]"]]},{"g":"構図","n":"シルエット（Silhouette）","b":[["見え方","人や物が真っ黒な形だけになります。"],["作り方","後ろを明るく（夕空、窓、霧＋ライト）、人には光を当てず、明るい方に露出を合わせます。コードでは人の素材を黒一色にするか、ライトを人の後ろだけに置きます。横顔や手足が重ならない姿勢にすると形が読めます。"],["使いどころ","謎、正体隠し、絵のような美しさ、別れ。"],["例","E.T.（1982）月の前を自転車が横切る [知識]"]]},{"g":"構図","n":"鏡・反射（Mirror / Reflection）","b":[["見え方","鏡、窓ガラス、水面に映った姿が画面に入ります。"],["作り方","カメラ自身が映らない角度（鏡に対して斜め）に置きます。コードでは反射する面（金属度1・粗さ0）を置くだけです。1つの画面に「本人と映った姿」の2つの顔を入れられます。"],["使いどころ","二面性、自分との対話、隠れた物を見せる。"],["例","タクシードライバー（1976）鏡の中の自分に向かって話しかける [知識]／燃えよドラゴン（1973）鏡だらけの部屋での決闘 [知識]"]]},{"g":"構図","n":"ブロッキング（Blocking、人の配置と動き）","b":[["見え方","人がどこに立ち、いつどこへ動くか。カメラが止まっていても、人の動きで画が変わっていきます。"],["作り方","立つ・座る・近づく・背を向けるの4つを、話の変わり目に合わせます。強い人を高く・手前に・中央に置きます。コードでは人の位置と向きを台本の変わり目ごとに変えます。"],["使いどころ","長回し、会話。カットに頼らず関係の変化を見せられます。"],["例","天国と地獄（1963）前半の部屋の場面で、大人数の立ち位置が力関係とともに変わっていく [知識]"]]},{"g":"構図","n":"四分割の使い分け（クアドラント / Quadrant Framing）【足した技法】","b":[["見え方","画面を田の字に4つに分け、人物ごとに別のマスを使います。"],["作り方","2人を同じ画面に入れつつ、1人は左上、もう1人は右下のように分けます。切り返しでも同じマスを守ります。"],["使いどころ","同じ場所にいるのに心が離れている感じ。"],["例","ドライヴ（2011）会話の場面で人物を画面の別々の区画に置く [知識]"]]},{"g":"意味づけ","n":"力関係（上下）","b":[["見え方","画面の中で高い位置にいる人、見上げて撮られた人が強く見えます。"],["作り方","強い側をローアングル・立ち姿・手前・大きく、弱い側をハイアングル・座り・奥・小さく。途中で入れかえると逆転が伝わります。"],["使いどころ","対立、説教、交渉。台詞で言わなくても伝わります。"],["例","市民ケーン（1941）主人公を見上げる画を多用し、大きな人物に見せる [知識]"]]},{"g":"意味づけ","n":"孤立（余白）","b":[["見え方","広い画面にぽつんと1人。"],["作り方","ロング＋ネガティブスペース。周りの人をぼかす、枠で区切る、1人だけ別の色・別の向きにする方法もあります。"],["使いどころ","さびしさ、よそ者、心が離れた感じ。"],["例","ロスト・イン・トランスレーション（2003）ホテルの大きな窓辺に小さく座り、東京の街を見下ろす [知識]"]]},{"g":"意味づけ","n":"緊張（傾き・狭さ）","b":[["見え方","画面が傾く、枠が狭い、顔が近すぎる、空きがない。"],["作り方","ダッチアングル、ショートサイディング、額縁、長いレンズで背景を詰める、狭い画面比率。ヘッドルームを削るのも効きます。"],["使いどころ","追いつめられた場面。ゆるめる場面（広い・水平）と交互にすると効きます。"],["例","サウルの息子（2015）狭い画面と浅いピントで主人公の顔と背中に張りつき続ける [知識]"]]},{"g":"意味づけ","n":"伏線（画面の隅）","b":[["見え方","主役とは別に、隅や奥で大事なことが小さく起きています。初めて見たときは気づかず、後で分かります。"],["作り方","主役を手前で動かして目を引き、隅・奥・ぼけの中に手がかりを置きます。ピントは合わせすぎず、でも読める程度に。"],["使いどころ","ミステリー、コメディ（気づかない主人公）、二度見たくなる作り。"],["例","ショーン・オブ・ザ・デッド（2004）主人公が買い物へ歩く後ろで、街の異変が進んでいるのに気づかない [知識]"]]}],"04":[{"g":"焦点距離","n":"広角レンズ（Wide-Angle、ゆがみ・広さ）","b":[["見え方","広い範囲が写ります。近い物は大きく、遠い物はぐっと小さくなり、奥行きが強調されます。顔に寄ると鼻が大きくゆがみます。"],["作り方","35mm判で14〜35mm。物に近づいて（0.3〜1m）撮ると効きます。コードでは cam.data.lens = 18 などにし、カメラを物に近づけます。動きは実際より速く見えます。"],["使いどころ","広さ、迫力、勢い、不安。人の顔を美しく撮りたいときは避けます。"],["例","レヴェナント：蘇えりし者（2015）広角レンズを顔のすぐ近くまで寄せ、息でレンズが曇る [知識]"]]},{"g":"焦点距離","n":"標準レンズ（Normal Lens）","b":[["見え方","人の目で見た感じに近い、ゆがみも圧縮もない画。"],["作り方","35mm判で40〜50mm（横の画角40度前後）。コードでは lens = 50。"],["使いどころ","自然に見せたいとき。色が付かないので、演技と構図で勝負する作品に向きます。"],["例","東京物語（1953）ほぼ全編を50mm1本で撮ったと言われる [知識]"]]},{"g":"焦点距離","n":"望遠レンズ（Telephoto、圧縮）","b":[["見え方","遠くの物が大きく写り、手前と奥がくっついて見えます（圧縮効果）。背景は大きくぼけます。"],["作り方","85〜400mm以上で、遠くから撮ります。コードでは lens = 200 にしてカメラを10〜50m下げます。カメラへ向かってくる動きは、なかなか近づかないように見えます。"],["使いどころ","人ごみの圧、追いつめられた感じ、のぞき見、夕日を大きく。"],["例","卒業（1967）主人公がこちらへ必死に走るのに、望遠のせいで少しも進まないように見える [知識]"]]},{"g":"焦点距離","n":"魚眼レンズ（Fisheye）","b":[["見え方","180度近くが写り、まっすぐな線が丸く曲がります。"],["作り方","6〜15mmの魚眼レンズ。Blender（Cycles）ではカメラの種類を「パノラマ」にして魚眼を選び、画角を180度にします。編集では「レンズゆがみ」を樽型（外へふくらむ向き）に強くかけると近い画になります。"],["使いどころ","のぞき穴、監視カメラ、スケートボードやMVの勢い、ゆがんだ世界。"],["例","女王陛下のお気に入り（2018）6mmの魚眼と10mmで宮殿の広間を丸くゆがめて映す [確認]"]]},{"g":"焦点距離","n":"マクロレンズ（Macro）","b":[["見え方","虫、目、水滴などの小さな物が画面いっぱいになります。"],["作り方","等倍（1:1）まで寄れるマクロレンズで、物から数cm〜30cm。ピントの合う奥行きが1mm単位になるので、F8〜16まで絞り、光をたくさん当てます。コードでは物を大きく作るか、カメラを数cmまで寄せて clip_start を0.001に下げます。"],["使いどころ","細部の合図、質感、別世界に入った感じ。"],["例","レクイエム・フォー・ドリーム（2000）瞳孔が開く目の超アップ [知識]"]]},{"g":"焦点距離","n":"プローブレンズ（Probe Lens）","b":[["見え方","細長い筒の先にレンズがあり、すき間や物の間をすり抜けながら、虫の目のように広く大きく写します。"],["作り方","Laowa 24mm F14 などの筒型マクロ広角レンズ。暗い（F14）ので強い光が要ります。コードでは広角（24mm前後）のカメラを物のすき間に通し、絞りを絞って手前から奥までピントを合わせます。カメラに「大きさ」が無いのでCGでは簡単です。"],["使いどころ","料理・飲み物のCM、模型の町の中を進む、びんの口へ入っていく画。"],["例","グリーンマイル（1999）などで、先駆けのフレイジャーレンズ（1993年に特許）が使われたとされる。どの場面かは不明 [確認・出典はメーカー系の解説のみ]"]]},{"g":"特殊レンズ","n":"アナモルフィックレンズ（Anamorphic）","b":[["見え方","横長の画面、青い横一本の光の筋（フレア）、縦長の楕円のぼけ、ピントを送ると背景が縦に伸び縮みします。"],["作り方","横だけ2倍に縮めて撮り、上映で戻すレンズ。コードでは cam.data.dof.aperture_ratio = 2.0（ぼけを楕円に）、合成の「グレア」で横の筋を足し、画面を2.39:1にします。"],["使いどころ","映画らしさ、SF、夜の街。フレアは入れすぎると画が見えません。"],["例","スター・トレック（2009）船の中の場面で、横に走る光の筋が何度も画面を横切る [知識]"]]},{"g":"特殊レンズ","n":"ティルトシフトレンズ（Tilt-Shift、ミニチュア風）","b":[["見え方","画面の帯のような一部だけピントが合い、上下が大きくぼけます。本物の町がおもちゃに見えます。"],["作り方","レンズを傾けてピントの面を斜めにします。編集では、画面の上1/3と下1/3に、端へ行くほど強くなるぼかしをかけ、彩度を20〜40%上げ、高い所から見下ろした画を2〜4倍の早回しにします。"],["使いどころ","町や人ごみの紹介、かわいさ。逆に建物をまっすぐ撮る「シフト」は建築写真の技です。"],["例","ソーシャル・ネットワーク（2010）ボートレースの場面で上下を大きくぼかし、模型のように見せる [知識]"]]},{"g":"特殊レンズ","n":"スプリットディオプター（Split Diopter）","b":[["見え方","手前の顔と遠くの人物の 両方 にピントが合い、境目だけがぼんやりしています。"],["作り方","半分に切った虫めがね（近く用のレンズ）をレンズの前の片側に付けます。コードでは、ピントを手前に合わせた画と奥に合わせた画を2回作り、左右でつなぎます。つなぎ目は幅5〜10%のぼかしにして、柱や壁の線に重ねて隠します。"],["使いどころ","離れた2つを同時に見せ、切り返さずに緊張を出したいとき。不自然さが味です。"],["例","ミッドナイトクロス（1981）手前のフクロウと、奥で録音する主人公の両方にピントが合う [知識]"]]},{"g":"特殊レンズ","n":"レンズベビー（Lensbaby）","b":[["見え方","真ん中あたりの一点だけがはっきりし、周りは放射状に流れてぼけます。はっきりした点は自由に動かせます。"],["作り方","蛇腹や球の関節でレンズを自由に曲げられる交換レンズ。編集では、決めた1点からの距離に応じて強くなる放射状ぼかし（ズームぼかし）をかけ、その点を少しずつ動かします。"],["使いどころ","目覚め、酔い、夢、記憶。"],["例","潜水服は蝶の夢を見る（2007）倒れた主人公が病室で目を覚ますときの、ゆれてにじむ主観 [確認]"]]},{"g":"特殊レンズ","n":"フリーレンズ（Freelensing / Lens Whacking、外して振る）","b":[["見え方","ピントの面がふらふら傾き、すき間から入った光が画面を白やオレンジにさっと染めます（光漏れ）。"],["作り方","レンズをカメラから外し、手で少し浮かせて傾けながら撮ります。編集では、ゆっくり動く傾いたぼかし＋ときどき画面の端から入るオレンジ色の光（加算合成、0.2〜0.5秒）を足します。"],["使いどころ","思い出、結婚式の映像、MVの夢っぽい場面。"],["例","なし（短編やMVの例は多いが、有名な長編で確かなものは見つからず [確認]）"]]},{"g":"特殊レンズ","n":"オールドレンズ・改造レンズ（ぐるぐるボケ / Swirly Bokeh）【足した技法】","b":[["見え方","中心ははっきり、周辺は流れてにじみ、ぼけがうずを巻きます。"],["作り方","古い設計のレンズ（Helios 44-2、ペッツバール型）や、レンズの一部を抜いた改造レンズ。編集では周辺だけに回転方向のぼかしと色のにじみを足します。"],["使いどころ","古い写真のような記憶、時代もの、人物だけを浮かせたいとき。"],["例","ジェシー・ジェームズの暗殺（2007）場面の変わり目で、周辺がにじむ改造レンズの画が入る [知識]／THE BATMAN－ザ・バットマン－（2022）画面の端がぼけて流れる [知識]"]]},{"g":"特殊レンズ","n":"歪曲収差（Lens Distortion、樽型・糸巻き型）【足した技法】","b":[["見え方","まっすぐな線が外へふくらむ（樽型、広角に多い）か、内へへこむ（糸巻き型、望遠に多い）。"],["作り方","レンズの性質。Blenderの合成では「レンズゆがみ」の数値の正負で樽型と糸巻き型が切り替わります（大きさ0.02〜0.1で自然、それ以上は効果として。どちらの符号が樽型かは試して確かめます）。"],["使いどころ","CGに少し足すと本物のカメラらしく見えます。強くかければ魚眼風。"],["例","なし"]]},{"g":"ピント","n":"浅い被写界深度（Shallow Depth of Field）","b":[["見え方","ピントが合う奥行き（被写界深度）が薄く、主役だけがはっきりして前後は大きくぼけます。"],["作り方","F1.2〜2.8、長めのレンズ（50〜135mm）、物に近づき、背景を遠ざけます。コードでは aperture_fstop = 1.4〜2.8、focus_distance を主役までの距離に。"],["使いどころ","人物を背景から切り離す、見せたくない物を隠す、親密さ。何でもぼかすと場所が分からなくなります。"],["例","バリー・リンドン（1975）F0.7の特別なレンズで、ろうそくの光だけの部屋を撮る [知識]"]]},{"g":"ピント","n":"パンフォーカス（Deep Focus）","b":[["見え方","手前から奥まで全部にピントが合います。"],["作り方","広角（18〜28mm）＋絞る（F8〜16）＋強い光。「過焦点距離」にピントを置くと、その半分の距離から無限遠まで合います（例：24mm・F8なら約2.4mに合わせると1.2m〜無限遠）。コードでは被写界深度の設定を切るだけで全部に合います。"],["使いどころ","奥行きの演出、手前と奥で同時に芝居をさせるとき。"],["例","市民ケーン（1941）手前の大人と奥の窓の外の少年の両方がはっきり見える [知識]"]]},{"g":"ピント","n":"ラックフォーカス（Rack Focus / Pull Focus、ピント送り）","b":[["見え方","ピントが手前の物から奥の物へ（または逆へ）移り、見る所が切り替わります。"],["作り方","2つの物を前後に離し、浅い被写界深度で撮りながらピントの輪を回します。コードでは focus_distance を0.5〜1.5秒かけてA距離→B距離へ動かします（ゆっくり始めゆっくり終える）。"],["使いどころ","気づき、秘密の発覚、視線の移動。カットせずに「次はこれ」と伝えます。"],["例","卒業（1967）真実に気づいた娘の顔へ、ピントがゆっくり時間をかけて合っていく [知識]"]]},{"g":"ピント","n":"ソフトフォーカス（Soft Focus）","b":[["見え方","ピントは合っているのに、全体にふんわり光がにじみます。ピンぼけとは別物です。"],["作り方","専用レンズ、拡散フィルター、レンズ前のストッキング。編集では元の画に、ぼかした複製（半径は画面幅の1〜3%）を「スクリーン」か「比較（明）」で20〜40%重ねます。"],["使いどころ","ロマンス、回想、肌をきれいに。かけすぎると眠い画になります。"],["例","カサブランカ（1942）ヒロインの顔のアップが柔らかくにじんで光る [知識]"]]},{"g":"ピント","n":"わざとピンぼけ（Intentional Defocus）","b":[["見え方","画面全体、または主役がぼけたまま。"],["作り方","ピントをわざと外します。コードでは focus_distance を極端に近く（0.1m）か遠くにする、または全体にぼかし（半径は画面幅の1〜5%）。ぼけ→合う、の変化は目覚めや場面の入りに使えます。"],["使いどころ","意識がもうろう、涙、見せたくない物（暴力や裸）を隠す、タイトルの背景。"],["例","地球は女で回ってる（1997）ある登場人物だけが、本人ごと「ピンぼけ」になってしまう [知識]"]]},{"g":"ピント","n":"ボケの形（Bokeh Shape）","b":[["見え方","ぼけた光の点が、丸・多角形・楕円・ドーナツ・ハートなどの形になります。"],["作り方","絞りの羽根の枚数で多角形に（5枚なら五角形）、アナモルフィックで楕円、反射望遠レンズでドーナツ、レンズ前に形を切り抜いた黒紙でハートや星。Blenderでは aperture_blades（羽根の数）、aperture_ratio（楕円）で変えます。"],["使いどころ","夜景、イルミネーション、恋愛の場面の背景。"],["例","なし"]]},{"g":"ピント","n":"フォーカスブリージング（Focus Breathing）【足した技法】","b":[["見え方","ピントを送ると、画面の広さがわずかに変わります（少しズームしたように見える）。"],["作り方","レンズの性質。コードではラックフォーカスに合わせて焦点距離を1〜3%だけ変えると、本物のレンズらしくなります。"],["使いどころ","CGのピント送りが「きれいすぎる」とき、少し足します。"],["例","なし"]]},{"g":"光の癖","n":"レンズフレア（Lens Flare）","b":[["見え方","強い光がレンズに入り、光の筋・輪・白っぽいかすみが画面に出ます。"],["作り方","太陽やライトを画面の中か端ぎりぎりに入れます。コードでは合成の「グレア」（筋・にじみ）や専用の素材を光源の位置に加算合成します。光源が物に隠れたら消えるようにします。"],["使いどころ","暑さ、まぶしさ、希望、SFのかっこよさ。顔にかかると表情が読めません。"],["例","イージー・ライダー（1969）バイクで走る場面で、太陽の光の輪をそのまま残した [知識]"]]},{"g":"光の癖","n":"ゴースト（Ghosting）","b":[["見え方","フレアの一種で、光源と画面の中心を結んだ線の上に、丸や多角形の光の玉が並びます。"],["作り方","レンズの中のガラス面で光が跳ね返ってできます。コードでは「光源の位置を画面中心で点対称にした先」へ向かう線上に、半透明の丸（絞りの形）を3〜8個、大きさと色を変えて置きます。光源が動けば反対へ動きます。"],["使いどころ","逆光の場面を本物らしく。CGやアニメの撮影処理でよく足します。"],["例","なし"]]},{"g":"光の癖","n":"周辺減光","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","四隅を少し暗くして目を中央へ集めます。明るいレンズを開けて撮ると自然に出ます。古い映画や回想の印にもなります。強さは四隅で0.3〜1段暗い程度が自然です。"]]},{"g":"光の癖","n":"色収差","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","画面の端で色がずれる、レンズの欠点です。CGに少し足して本物のカメラらしくしたり、衝撃・故障・酔いの瞬間だけ強くしたりします。常に強くかけると安っぽく見えます。"]]},{"g":"光の癖","n":"ハレーション（Halation）","b":[["見え方","強い光のまわりに、赤〜オレンジのにじんだ輪が出ます。"],["作り方","フィルムの中で光が裏から跳ね返ってできる、フィルム特有の現象です。編集では、明るい所だけを取り出し（しきい値80〜90%以上）、ぼかして（半径は画面幅の0.5〜1.5%）赤〜オレンジに着色し、加算で10〜30%重ねます。"],["使いどころ","フィルムらしさ、夜のネオンや街灯、車のライト。"],["例","なし"]]},{"g":"光の癖","n":"ブルーミング（Blooming）","b":[["見え方","とても明るい所の光が、まわりへ白くあふれ出します。窓や空の縁がとけます。"],["作り方","強い逆光や拡散フィルターで出ます。編集やゲームの「ブルーム」と同じで、明るい所を取り出して大きくぼかし、元の色のまま加算します（ハレーションは赤い、ブルーミングは光の色のまま、が違い）。Blenderでは合成の「グレア」のブルーム／フォググロー。"],["使いどころ","天国、夢、まぶしい朝、SFの白い部屋。"],["例","マイノリティ・リポート（2002）窓の光が白くあふれて人の輪郭をとかす [知識]"]]},{"g":"フィルター","n":"NDフィルター（Neutral Density）","b":[["見え方","色は変えずに、光の量だけを減らす「サングラス」です。画そのものは変わりませんが、明るい昼でも絞りを開けたり、シャッターを遅くしたりできます。"],["作り方","ND8（3段分）、ND64（6段分）など。動画では「シャッターは1/50秒のまま、ぼけも欲しい」ときに必ず要ります。コードではカメラの明るさを自由に決められるので不要です（＝CGでは昼でもF1.4が使えます）。"],["使いどころ","昼の浅い被写界深度、滝や雲を流す長時間露光。"],["例","なし"]]},{"g":"フィルター","n":"偏光フィルター（Polarizer / PL）","b":[["見え方","水面やガラスの反射が消え、空の青と葉の緑が濃くなります。"],["作り方","フィルターを回して効き具合を選びます。太陽に対して90度の方向で一番効きます。コードでは、反射の強さ（スペキュラー）を下げ、空の彩度を上げ明るさを少し下げます。"],["使いどころ","車の窓ごしに顔を撮る、水の中を見せる、風景。"],["例","なし"]]},{"g":"フィルター","n":"拡散フィルター（Diffusion / ミスト）","b":[["見え方","光がふわっとにじみ、肌がなめらかに、コントラスト（明暗の差）が少し下がります。"],["作り方","ブラックプロミスト、グリマーグラスなど（強さ1/8〜1）。編集では、明るい所を取り出してぼかしたものを「スクリーン」で10〜30%重ね、黒を少し持ち上げます。"],["使いどころ","デジタルの画の硬さを取る、夜景、人物。今のドラマやMVでとてもよく使われます。"],["例","なし"]]},{"g":"フィルター","n":"スターフィルター（Star / Cross Filter、十字の光）","b":[["見え方","点の光から十字（4本）や6本・8本の光の筋が伸びます。"],["作り方","細かい溝を刻んだフィルター。溝の向きで筋の向き、本数が決まります。レンズを強く絞っても（F16〜22）似た筋が出ます。Blenderでは合成「グレア」の「ストリーク」で本数と角度を指定します。"],["使いどころ","宝石、イルミネーション、80年代の歌番組やアイドルの雰囲気。"],["例","なし"]]},{"g":"フィルター","n":"色フィルター（Color Filter）","b":[["見え方","画面全体が1つの色に寄ります。白黒映画では、空を暗くする（赤フィルター）など明暗を変える道具でした。"],["作り方","レンズの前に色ガラス。半分だけ色が付いたもの（グラデーションフィルター）は空だけを染めます。編集では色を乗算で重ねるか、色調整で寄せます。"],["使いどころ","場所や時代の区別、暑さ寒さ、夢。"],["例","トラフィック（2000）話の舞台ごとに色を変え、メキシコの場面は黄色く焼けた色にする [知識]／南太平洋（1958）歌の場面で画面全体を色で染める [知識]"]]},{"g":"フィルター","n":"ワセリン塗り（Vaseline on Lens）","b":[["見え方","塗った所だけが流れるようににじみ、塗らなかった所ははっきり残ります。"],["作り方","レンズそのものではなく、前に付けた透明フィルターの周辺にワセリンを指で塗ります。塗る向きに光が流れます。編集では、中心を残した楕円のマスクの外側に、方向つきのぼかしをかけます。"],["使いどころ","夢、幻、記憶、のぞき見。手作りの不ぞろいさが味です。"],["例","なし"]]}],"05":[{"g":"コマ数","n":"24・30・60コマの違い（Frame Rate / fps）","b":[["見え方","24コマは少しカクつきとぶれがあり「映画」らしく、30コマはテレビやニュース、60コマはスポーツ・ゲーム・生放送のようになめらかで現実的に見えます。"],["作り方","カメラや編集ソフトの設定で決めます（正確には23.976／29.97／59.94が多い）。コードでは scene.render.fps = 24 など。途中で変えると動きがおかしくなるので、最初に決めます。"],["使いどころ","物語は24、YouTubeや日本のテレビは30、ゲーム実況や動きの速いものは60。スローにする予定があれば高いコマ数で撮ります。"],["例","なし"]]},{"g":"コマ数","n":"ハイスピード撮影（High Speed / Slow Motion、スローモーション）","b":[["見え方","動きがゆっくり、なめらかになります。水しぶき、髪、爆発の細部が見えます。"],["作り方","ふつうより多いコマ数（48〜1000以上）で撮り、24コマで再生します。120コマで5倍、240コマで10倍。コードでは動きを遅くして同じコマ数で描き出します（上の式の時間のばし）。後から伸ばすだけだとカクつくので、最初から多く作ります。"],["使いどころ","決定的な一瞬、美しさ、痛み、感動。多用すると話が進みません。"],["例","七人の侍（1954）斬られた男がゆっくり倒れる [知識]／インセプション（2010）橋から落ちていく車がずっとスローで映る [知識]"]]},{"g":"コマ数","n":"コマ落とし（早回し）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","少ないコマ数（12〜22）で撮って24で見せると速くなります。昔の喜劇のせかせかした動きがこれです。アクションで20〜22コマにして、気づかれない程度に速く・鋭く見せる使い方もあります。"],["例","マッドマックス 怒りのデス・ロード（2015）場面ごとにコマ数を上げ下げして、速さと見やすさを調整した [知識]"]]},{"g":"コマ数","n":"タイムラプス（Time-Lapse）","b":[["見え方","雲が流れ、花が開き、街の光が川のように動きます。長い時間が数秒になります。"],["作り方","三脚で固定し、一定の間隔（1〜60秒に1枚）で写真を撮って並べます。間隔 ＝ 実際の時間 ÷（欲しい秒数 × コマ数）。例：1時間を10秒に＝3600÷240＝15秒に1枚。コードでは時間を数百倍に速めて描き出し、ぶれを長め（シャッター1.0）にするとなめらかです。"],["使いどころ","時間の経過、自然の変化、都市の脈動。"],["例","コヤニスカッツィ（1982）都市の人と車の流れを早回しで見せる [知識]"]]},{"g":"コマ数","n":"ハイパーラプス（Hyperlapse）","b":[["見え方","タイムラプスなのに、カメラが街の中を長い距離すーっと進みます。"],["作り方","1枚撮るごとに決まった距離（0.3〜1m）だけ移動し、毎回同じ1点（建物の角など）を画面の同じ位置に合わせます。後で手ぶれ補正をかけます。コードではカメラを道にそって速く動かし、常に1点を向かせ（Blenderの「トラック」）、時間も一緒に速めます。"],["使いどころ","街の紹介、旅、場所から場所への移動。"],["例","なし"]]},{"g":"コマ数","n":"HFR（High Frame Rate、高コマ数上映）","b":[["見え方","48・60・120コマで撮り、そのままのコマ数で見せます。ぶれとカクつきが消え、窓から現実を見ているようになります。「テレビっぽい」「セットが作り物に見える」と言う人もいます。"],["作り方","撮影も上映も高コマ数にします。コードでは fps = 48〜60 で描き出すだけですが、作る枚数が2倍以上に増えます。"],["使いどころ","3D映画、水中や速いアクション、ゲーム映像。物語の「夢っぽさ」は薄れます。"],["例","ホビット 思いがけない冒険（2012）48コマで上映 [知識]／ジェミニマン（2019）120コマで撮影 [知識]"]]},{"g":"コマ数","n":"コマ打ち（2コマ打ち・3コマ打ち / On Twos, On Threes）【足した技法】","b":[["見え方","24コマの映像の中で、絵が2コマ（または3コマ）に1回しか変わらず、パキパキした動きになります。"],["作り方","同じ絵を2〜3コマ続けて見せます（1秒に12枚か8枚）。コードでは動きのキーを2コマおきに打って間を補間しない（階段状）、ぶれは切ります。カメラの動きだけは1コマごとに動かすと、アニメらしく見えます。"],["使いどころ","アニメの手描き感、3DCGをアニメ風に、コマ撮り風。"],["例","スパイダーマン：スパイダーバース（2018）3DCGの人物を2コマ打ちで動かす [知識]"]]},{"g":"シャッター","n":"シャッター角度（Shutter Angle、180度が普通）","b":[["見え方","1コマの中の「動きのぶれ」の長さが変わります。180度が、目にいちばん自然なぶれです。"],["作り方","フィルムカメラの回る半円の板の開き具合から来た言い方です。露光時間 ＝ 角度÷360÷コマ数。24コマなら180度＝1/48秒（デジタルでは1/50秒）、30コマなら1/60秒。コードでは motion_blur_shutter = 0.5。"],["使いどころ","基本は180度。ここから狭める・開けるで味を付けます。"],["例","なし"]]},{"g":"シャッター","n":"狭いシャッター（Narrow Shutter、パラパラした戦場）","b":[["見え方","ぶれが無くなり、1コマ1コマがくっきり。動きがパラパラ・カクカクし、飛び散る土や水の粒が止まって見えます。"],["作り方","45〜90度（24コマで1/192〜1/96秒）。コードでは motion_blur_shutter = 0.125〜0.25、またはぶれを切ります。手持ちのゆれと組み合わせると強く効きます。"],["使いどころ","戦闘、パニック、あせり。長く続くと目が疲れます。"],["例","プライベート・ライアン（1998）上陸の場面を90度や45度のシャッターで撮り、ニュース映画のような荒さを出した [確認]"]]},{"g":"シャッター","n":"開けたシャッター（Open Shutter、流れる）","b":[["見え方","ぶれが長くなり、動きが流れてにじみます。"],["作り方","270〜360度（24コマで1/32〜1/24秒）。コードでは motion_blur_shutter = 0.75〜1.0。1.0を超えると前後のコマにまたがる、より長い尾になります。暗い場所で明るく撮れる利点もあります。"],["使いどころ","夢、酔い、夜の街、疾走感。細部は見えなくなります。"],["例","なし"]]},{"g":"シャッター","n":"ステッププリント（Step Printing、残像の流し）","b":[["見え方","動きはカクカクしているのに、1枚1枚は長くぶれて流れています。にじんだ残像が飛び飛びに進みます。"],["作り方","低いコマ数（6〜12）＋長いシャッター（1/8〜1/15秒）で撮り、同じコマを2〜4回くり返して24コマにします。編集では「4コマを平均して1枚にする → その1枚を4コマ見せる」をくり返します（ffmpegなら tmix で平均、fps=6 で間引き）。"],["使いどころ","追跡、夜の人ごみ、時間の感覚がずれる瞬間。"],["例","恋する惑星（1994）冒頭、人ごみの中の追いかけが、流れる残像のコマ送りになる [知識]"]]},{"g":"シャッター","n":"長時間露光（Long Exposure）","b":[["見え方","車のライトが光の線に、滝が白い布に、星が円になります。動かない物だけがはっきり残ります。"],["作り方","三脚で1秒〜数分シャッターを開けます（昼はNDフィルターが要ります）。動画では、連続したコマを重ねます。平均（ffmpeg tmix=frames=30）で水や雲が流れ、「明るい方だけ残す」（比較明）で光の線が残ります。"],["使いどころ","夜景、タイムラプスをなめらかにする、時間の流れを1枚に閉じこめる。"],["例","なし"]]},{"g":"シャッター","n":"ローリングシャッターのゆがみ（Rolling Shutter）【足した技法】","b":[["見え方","カメラを速く振ると建物が斜めに倒れ、ゆれるとこんにゃくのようにぐにゃぐにゃします。プロペラは曲がって写ります。"],["作り方","多くのデジタルカメラは画面を上から順に読むため、上と下で写る時刻がずれます。Blender（Cycles）にはローリングシャッターの設定があります。編集では、画面の上と下で時刻を少しずらして合成します。"],["使いどころ","ふつうは欠点として避けます。スマホで撮った感じ、記録映像らしさをCGに足したいときに少しだけ。"],["例","なし"]]},{"g":"シャッター","n":"ワゴンホイール効果（Wagon-Wheel Effect）【足した技法】","b":[["見え方","回る車輪やプロペラが、止まって見えたり逆に回って見えたりします。"],["作り方","回る速さとコマ数の関係で起きます。1コマの間に「羽根1枚ぶん」ちょうど回ると止まって見え、少し足りないと逆回りに見えます。コードでは回転の速さを「コマ数 ÷ 羽根の数」の前後に合わせます。"],["使いどころ","ふつうは偶然の産物ですが、ヘリの羽根を止めて見せるなどの遊びができます。照明や画面のちらつき（フリッカー）も同じ仕組みです。"],["例","なし（西部劇の馬車の車輪で昔から知られる現象 [知識]）"]]},{"g":"時間の編集","n":"スピードランプ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","1つのカットの中で、速い→遅い→速いと速さを変えます。打撃の瞬間だけスローにして、前後は速く流します。高コマ数で撮っておくのが前提です。"],["例","300〈スリーハンドレッド〉（2006）戦いの最中、斬る瞬間だけスローになり、また速く戻る [知識]"]]},{"g":"時間の編集","n":"止め絵（フリーズ）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","最後の一瞬を止めて、結末を言わずに終える。人物紹介で止めて名前を出す。語りを入れる間を作る。"],["例","大人は判ってくれない（1959）最後、海辺でこちらを向いた少年の顔で止まる [知識]／明日に向って撃て！（1969）飛び出した2人の姿で止まって終わる [知識]"]]},{"g":"時間の編集","n":"逆再生","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","割れた物が元に戻る、水が上へ昇るなどの魔法。「逆に演じて逆再生する」と、動きは正しいのに少しだけ不気味になります。危ない動き（顔すれすれで物が止まる）を安全に撮る手にもなります。"],["例","オルフェ（1950）手袋が手に吸いつくようにはまる [知識]／TENET テネット（2020）時間を逆に進む人と順に進む人が同じ画面で戦う [知識]"]]},{"g":"時間の編集","n":"残像（エコー）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","動きの軌跡を見せる、酔いや超人的な速さを表す。踊りや格闘の型を美しく見せます。"],["例","パ・ド・ドゥ（1968、ノーマン・マクラレン）バレエの踊り手の動きが、いくつもの残像になって重なる [知識]"]]},{"g":"時間の編集","n":"スタッター","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","映像の故障、記憶の乱れ、通信の不調、ループにとらわれた感じ。音も一緒に刻むと効きます。物語の中では短く、合図として使います。"]]},{"g":"時間の編集","n":"バレットタイム（Bullet Time）","b":[["見え方","時間がほぼ止まった（ごくゆっくり動く）中を、カメラだけがぐるりと回りこみます。"],["作り方","人のまわりにたくさんのカメラ（スチルカメラ約120台＋映画カメラ）を並べ、少しずつずらして順にシャッターを切り、間のコマをコンピューターで補います。コードでは簡単で、物の動きを1/50〜1/200に遅くしたまま、カメラを中心のまわりに1〜3秒で90〜360度回します。"],["使いどころ","超人的な一瞬、見せ場の決めポーズ。有名すぎるので、パロディに見えやすいです。"],["例","マトリックス（1999）屋上でのけぞって弾をよける [知識]"]]},{"g":"時間の編集","n":"タイムスライス（Time Slice / Frozen Moment）","b":[["見え方","時間が完全に止まり、止まった世界の中をカメラが動きます。水しぶきも空中で固まっています。"],["作り方","並べたカメラの 全部を同時に 切ります（バレットタイムは少しずつずらす、が違い）。1980年代にティム・マクミランが作り始めた方法です [確認]。コードでは動きを1コマで止め（そのコマのまま）、カメラだけ動かします。"],["使いどころ","決定的な瞬間、CM、スポーツ中継の再生。"],["例","バッファロー'66（1998）で使われたとされる。どの場面かは未確認 [確認・出典はWikipediaの一覧のみ]"]]},{"g":"時間の編集","n":"オプティカルフローの補間（Optical Flow Interpolation）","b":[["見え方","元にないコマをコンピューターが作り、ふつうに撮った映像がなめらかなスローになります。失敗すると、手足や細い物がぐにゃりととけます。"],["作り方","前後のコマで「どの点がどこへ動いたか」を計算し、中間の絵を作ります。DaVinci Resolveの「オプティカルフロー」、ffmpegの minterpolate=fps=96:mi_mode=mci、AIのRIFEなど（どれも無料で使えます）。"],["使いどころ","スローで撮り忘れた素材、24コマを60コマにする、コマ撮りをなめらかにする。背景が単純で動きがゆっくりな所に向きます。"],["例","なし"]]},{"g":"コマ撮り","n":"ストップモーション（Stop Motion）","b":[["見え方","人形や粘土が自分で動いているように見えます。少しカクカクし、表面の指のあとや布の毛がちらちらします。"],["作り方","少し動かして1枚撮る、をくり返します。1秒に12枚（2コマ打ち）か24枚。コードでは、動きのキーを2コマおきに階段状に打ち、ぶれを切り、位置にごく小さな乱れ（0.5〜2mm相当）を足すと手作りらしくなります。"],["使いどころ","手作りのぬくもり、少し不気味なおとぎ話、物が生きているCM。"],["例","キング・コング（1933）人形のコングを1コマずつ動かした [知識]／コララインとボタンの魔女（2009）[知識]"]]},{"g":"コマ撮り","n":"ピクシレーション（Pixilation、人のコマ撮り）","b":[["見え方","生きた人間が人形のようにカクカク動き、歩かずにすべって進んだり、宙に浮いたままになったりします。"],["作り方","人が少し動いて止まる → 1枚撮る、をくり返します。毎回ジャンプした頂点で撮れば、浮いたまま進むように見えます。編集では、ふつうの動画から数コマおきに1枚だけ抜き出しても近い感じになります。"],["使いどころ","MV、短いCM、SNS。体を使ったおかしな手品。"],["例","隣人（1952、ノーマン・マクラレン）隣どうしの2人がコマ撮りで宙をすべり、争う [知識]"]]},{"g":"コマ撮り","n":"ゴーモーション（Go Motion）","b":[["見え方","コマ撮りなのに、動きにぶれがあり、本物の生き物のようになめらかです。"],["作り方","シャッターが開いている間に、機械で人形を少しだけ動かします。コードでは、コマ撮り風の動きのまま、ぶれ（シャッター0.5）を入れるだけです。"],["使いどころ","コマ撮りのカクカクを消して実写になじませたいとき。今はCGに置きかわりました。"],["例","ドラゴンスレイヤー（1981）竜の動き [知識]／スター・ウォーズ 帝国の逆襲（1980）雪原を走る二本足の動物 [知識]"]]},{"g":"コマ撮り","n":"置き換え（Substitution Splice / Stop Trick、消える手品）","b":[["見え方","人や物がぱっと消える、現れる、別の物に変わる。"],["作り方","カメラを固定して撮影を止め、物を入れかえ（または取りのぞき）、まったく同じ位置から撮影を再開します。つなぎ目の前後で背景と他の人が動いていないことが肝心です。煙や光をつなぎ目に重ねるとごまかせます。"],["使いどころ","魔法、変身、瞬間移動。映画でいちばん古い特撮です。"],["例","ロベール＝ウーダン劇場における婦人の雲隠れ（1896、ジョルジュ・メリエス）椅子の女性が消えて骸骨に変わる [知識]"]]}],"06":[{"g":"基本の型","n":"三点照明（Three-point lighting）","b":[["見え方","顔が立体的に見え、背景からもくっきり離れます。インタビューや古い映画のアップの基本形です。"],["作り方","キー（主役の光）をカメラから横30〜45度・上30〜45度に。フィル（影を起こす弱い光）を反対側のカメラ近くに、キーの1/2〜1/4の明るさで。バック（後ろの光）を人物の真後ろ〜斜め後ろの上から、キーと同じ〜やや強く。Blenderならエリアライト3つで、強さを例えば1000W・300W・800Wにします。"],["使いどころ","迷ったらここから始めて、ライトを1つずつ消して好みを探します。3つ全部つけたままだと「スタジオっぽい」平凡な絵になります。"],["例","『カサブランカ』（1942）のヒロインのアップ [知識]"]]},{"g":"基本の型","n":"ハイキー（High-key）","b":[["見え方","画面全体が明るく、影がうすい絵です。"],["作り方","キーとフィルの比を2:1以下にします。大きくやわらかい光を正面近くから当て、背景にも別の光を当てて暗い所をなくします。コードなら、暗い所を持ち上げ、コントラスト（明暗の差）を下げます。"],["使いどころ","コメディ、ミュージカル、広告、楽しい回想。やりすぎると平らで安っぽく見えます。"],["例","『雨に唄えば』（1952）の歌と踊りの場面 [知識]"]]},{"g":"基本の型","n":"ローキー（Low-key）","b":[["見え方","画面の大部分が暗く、一部だけが明るい絵です。"],["作り方","キー1つだけ、または比を8:1以上に。光を横か後ろ寄りに回し、背景には光を当てません。Blenderならワールド（環境の光）の強さを0に近づけ、ライト1つにします。"],["使いどころ","犯罪もの、ホラー、秘密の話。暗すぎて何も見えないのは失敗なので、目か輪郭のどちらかは必ず見せます。"],["例","『ゴッドファーザー』（1972）冒頭の書斎 [知識]"]]},{"g":"基本の型","n":"ハードライトとソフトライト（Hard / Soft light）","b":[["見え方","ハードは影のふちがくっきり、肌のでこぼこも強く出ます。ソフトは影のふちがぼけて、肌がなめらかに見えます。"],["作り方","光源の「見かけの大きさ」で決まります。小さいライトを遠くから＝ハード。大きい面（布ごし・壁に反射）を近くから＝ソフト。Blenderではエリアライトのサイズ（例：0.1mでハード、2mでソフト）、太陽ライトなら「角度」（0.5度でハード、10度以上でソフト）を変えます。"],["使いどころ","ハードは緊張・暑さ・強さ。ソフトはやさしさ・美しさ・曇りの日。1つの場面で混ぜる時は役割を分けます（顔はソフト、背景の影はハード、など）。"],["例","ハード＝『第三の男』（1949）の夜の街 [知識]"]]},{"g":"基本の型","n":"バウンス（Bounce）","b":[["見え方","どこから来たか分からない、やわらかく自然な光になります。"],["作り方","ライトを人物に向けず、白い板・壁・天井に当てて、はね返った光を使います。Blenderなら白い大きな板（平面）を人物の近くに置き、そこへスポットライトを当てます。板の色がそのまま光の色になります（木の床なら暖かい色）。"],["使いどころ","窓ぎわの室内、自然な会話。光が弱くなるので、暗くなりすぎたらライトを強くします。"],["例","なし"]]},{"g":"基本の型","n":"ネガティブフィル（Negative fill）","b":[["見え方","影の側がより黒くなり、顔に深みが出ます。「光を引く」やり方です。"],["作り方","影の側に黒い板や布を置き、まわりからのはね返りを吸わせます。Blenderなら影の側に黒い平面（反射しない材質）を置くか、ワールドの明るさを下げます。"],["使いどころ","屋外や白い部屋で顔が平らに見える時。明るい場所でもローキーに近い立体感が出せます。"],["例","なし"]]},{"g":"基本の型","n":"光の比（Lighting ratio）※追加","b":[["見え方","同じ配置でも、比が小さいとやさしく、大きいと劇的に見えます。"],["作り方","キー側とフィル側の明るさを比べます。2:1→4:1→8:1と、1段ずつ変えて並べると違いが分かります。Blenderではフィルの強さだけを半分ずつ下げます。"],["使いどころ","作品全体で比をそろえると、絵に統一感が出ます。場面の気持ちが変わる所だけ比を変えます。"],["例","なし"]]},{"g":"顔の光","n":"レンブラント（Rembrandt lighting）","b":[["見え方","影の側のほおに、小さな光の三角形ができます。"],["作り方","キーを横およそ45度・上およそ45度に置きます。三角は「目の幅より狭く、鼻の長さより短く」が目安。フィルは弱め（4:1〜8:1）。"],["使いどころ","まじめ、内面のある人物、絵画のような品。三角が大きすぎると、ただの斜めの光になります。"],["例","名前は1915年にセシル・B・デミル監督がこの光を画家の名で呼んだ話に由来します [知識]"]]},{"g":"顔の光","n":"バタフライ（Butterfly / Paramount lighting）","b":[["見え方","鼻の真下に蝶の形の小さな影ができ、ほお骨が強調されます。"],["作り方","キーをカメラの真上（顔の正面、上25〜45度）に置きます。あごの下に白い板を置くと首の影がやわらぎます。"],["使いどころ","美しさを見せたいアップ、スターの登場。丸顔だとより丸く見えることがあります。"],["例","『上海特急』（1932）の主演女優のアップ [知識]"]]},{"g":"顔の光","n":"ループ（Loop lighting）","b":[["見え方","鼻の影が斜め下に小さく輪のように落ち、ほおの影とはつながりません。"],["作り方","キーを横30〜45度、目より少し高い位置に。レンブラントとバタフライの中間です。"],["使いどころ","一番無難で、ほとんどの顔に合います。迷ったらこれです。"],["例","なし"]]},{"g":"顔の光","n":"スプリット（Split lighting）","b":[["見え方","顔のちょうど半分が明るく、半分が影になります。"],["作り方","キーを真横90度に置き、フィルは入れません。"],["使いどころ","二面性、迷い、敵か味方か分からない人物。ふつうの会話に使うと大げさです。"],["例","『地獄の黙示録』（1979）終盤、闇から顔の一部だけ現れる大佐 [知識]"]]},{"g":"顔の光","n":"ブロードとショート（Broad / Short lighting）","b":[["見え方","顔が斜めを向いている時、カメラに近い側のほおが明るいのがブロード、遠い側が明るいのがショートです。"],["作り方","人物の顔を30〜45度横に向け、キーをカメラ側から当てる（ブロード）か、向こう側から当てる（ショート）。"],["使いどころ","ショートは顔が細く立体的に見え、映画ではこちらが多いです。ブロードは顔が広く平らに見え、明るく開いた印象になります。"],["例","なし"]]},{"g":"顔の光","n":"アイライト（Eye light / Catchlight）","b":[["見え方","目の中に小さな白い点（光の映りこみ）が入り、生きている感じが出ます。"],["作り方","カメラのすぐ近くに小さく弱いライトを置きます。点は瞳の10時か2時の位置がきれいです。3Dやアニメでは、瞳に白い点を直接描きこむ（ハイライト）のと同じことです。"],["使いどころ","感情のあるアップ。わざと消すと、死・冷たさ・何を考えているか分からない感じになります。"],["例","『ブレードランナー』（1982）で人造人間の瞳が光る表現 [知識]"]]},{"g":"顔の光","n":"トップライト（Top light）","b":[["見え方","真上から当たり、目のくぼみが黒く落ちます。"],["作り方","ライトを頭の真上に置きます。少し前に出すと目が見え、真上〜後ろ寄りだと目が完全に影になります。"],["使いどころ","権力者、取り調べ、孤独。目が見えないと感情が読めなくなるので、ねらいがある時だけ使います。"],["例","『ゴッドファーザー』（1972）で、主人公の目をわざと影にした真上からの光 [知識]"]]},{"g":"顔の光","n":"下からの光（Underlighting）","b":[["見え方","ふだん見ない向きの影ができ、不気味に見えます。"],["作り方","ライトをあごより下、カメラの近くから上向きに当てます。"],["使いどころ","怪談、怪物、たき火や手元の画面を見ている人。理由のない場面で使うと笑いになります。"],["例","なし（懐中電灯をあごの下から当てる怪談の型）"]]},{"g":"演出の光","n":"リムライト（ふちどり）（Rim light）","b":[["見え方","髪や肩の輪郭が細く光り、人物が背景から浮きます。"],["作り方","人物の後ろ斜め上（真後ろから左右30〜45度）に置き、キーと同じ〜1段強く。カメラにライト自体が写らないようにします。3Dのトゥーン表現なら、輪郭の近く（面の向きがカメラに対して横を向いた所）だけ明るくする「フレネル」という計算で同じ絵が出ます。"],["使いどころ","暗い背景に暗い髪の人物、夜、かっこいい登場。全員に付けるとゲームのように見えます。"],["例","『ブレードランナー』（1982）煙の中の逆光の人物 [知識]"]]},{"g":"演出の光","n":"シルエット（Silhouette）","b":[["見え方","人物が真っ黒な形だけになります。"],["作り方","背景（空・窓・光る壁）だけを明るくし、人物には光を当てません。明るさを背景に合わせます。コードなら人物の層を黒でぬりつぶすだけでも作れます。"],["使いどころ","謎の人物、決めの絵、暴力を直接見せたくない時。形で誰か分かるポーズにします（腕と体を離す）。"],["例","『E.T.』（1982）月の前を横切る自転車 [知識]"]]},{"g":"演出の光","n":"キアロスクーロ（明暗）（Chiaroscuro）","b":[["見え方","強い光と深い影の対比で、絵画のように見えます。"],["作り方","硬めの光を1つ、横から当て、フィルは入れません。画面の半分以上を黒にします。"],["使いどころ","善悪、秘密、追いつめられた場面。ローキーの中でも「明暗の形そのもの」を見せたい時の言葉です。"],["例","『第三の男』（1949）暗い戸口の人物に窓の光が当たる場面 [知識]"]]},{"g":"演出の光","n":"動機のある光（Motivated lighting）","b":[["見え方","光に「理由」があるので、照明していることに気づきません。"],["作り方","画面の中や外に光源（窓、電灯、テレビ）があることにして、その方向と色に合わせて、もっと強い撮影用のライトを当てます。3Dでも、窓の外に大きなエリアライトを置く、という考え方です。"],["使いどころ","現実的な話すべて。光の向きが場面の途中で変わると、うそがばれます。"],["例","なし"]]},{"g":"演出の光","n":"プラクティカル（画面内の照明）（Practical light）","b":[["見え方","画面に写っているスタンド・ろうそく・電飾が、そのまま光源になっています。"],["作り方","写る照明を置き、明るさを落として白くとばないようにします。3Dなら、電球の物体に発光（エミッション）を付け、同じ場所に点ライトを重ねます。"],["使いどころ","室内の夜、あたたかい雰囲気。背景に光の点があると奥行きも出ます。"],["例","『アイズ ワイド シャット』（1999）クリスマスの電飾が部屋を照らす [知識]"]]},{"g":"演出の光","n":"自然光だけ（Natural light only）","b":[["見え方","作りものでない、その場の空気がそのまま写ります。"],["作り方","太陽と空の光だけで撮り、時間と向きを選びます。足りない所は白い板で返すだけ。3Dなら空の画像（HDRI＝まわり全部の光を写した写真）1枚だけで照らします。"],["使いどころ","ドキュメンタリー風、荒野、素朴な話。時間が限られ、天気に左右されます。"],["例","『レヴェナント：蘇えりし者』（2015）ほぼ全編を自然の光で撮影 [知識]"]]},{"g":"演出の光","n":"マジックアワー（Magic hour / Golden hour）","b":[["見え方","橙色のやわらかい光と長い影。肌がきれいに見えます。"],["作り方","日の出の直後・日の入りの直前の20〜30分に撮ります。3Dなら太陽の高さを0〜6度、色を2500〜3500Kにし、空の光を青く弱く足します。色の調整で作るなら、明るい所を橙へ、影を青紫へ寄せます。"],["使いどころ","恋、旅の終わり、なつかしさ。使いすぎると全部が広告に見えます。"],["例","『天国の日々』（1978）日没前後の短い時間だけで撮られた麦畑 [知識]"]]},{"g":"演出の光","n":"ブルーアワー（Blue hour）","b":[["見え方","太陽がしずんだ後の、影のない青い世界。街の明かりの橙色が映えます。"],["作り方","日没後およそ10〜30分。3Dなら太陽を消し、空の光だけ（9000K以上の青）にして、窓や街灯に橙色（3000K）の光を置きます。"],["使いどころ","静けさ、終わりと始まりの間、さびしさ。時間が短いので、撮影では数日に分けます。"],["例","なし"]]},{"g":"演出の光","n":"月明かり（Moonlight）","b":[["見え方","青白い硬めの光と、濃い影。"],["作り方","本物の月の光は青くありませんが、映画では「夜＝青」が約束です。高い位置から硬いライトを1つ、色はうすい青（赤0.6・緑0.75・青1.0くらい）。影はほぼ真っ黒、彩度（色の濃さ）は低めにします。"],["使いどころ","夜の屋外すべて。部屋の中の橙色と対比させると、内と外が分かれます。"],["例","『ムーンライト』（2016）夜の浜辺で肌に青い光が乗る場面 [知識]"]]},{"g":"演出の光","n":"火のゆらぎ（Firelight flicker）","b":[["見え方","橙色の光が不規則に明るくなったり暗くなったりし、影もゆれます。"],["作り方","色は1800〜2000K、低い位置から。明るさを不規則に±20〜40%、1秒に数回〜10回ほど変えます。Blenderならライトの強さにノイズ（Fカーブのノイズ修飾）を付け、位置も数cmゆらします。規則正しい波にすると作りものに見えます。"],["使いどころ","たき火、ろうそく、暖炉、火事。昔の時代の夜。"],["例","『バリー・リンドン』（1975）ろうそくの光だけで撮った室内（特別に明るいレンズを使用）[知識]"]]},{"g":"演出の光","n":"雷（Lightning）","b":[["見え方","一瞬だけ画面が青白く明るくなり、すぐ暗くもどります。"],["作り方","1〜3コマの強い光を、不規則な間をあけて2〜3回（例：2コマ光る→3コマ暗い→1コマ光る→6コマ暗い→3コマ光る）。色は青みの白、硬い光で窓の方向から。音はわざと遅らせます（1秒遅れ＝およそ340m先）。"],["使いどころ","嵐、怪物の正体を一瞬だけ見せる、不吉な知らせ。点滅が多いと見る人の体に悪いので、1秒に3回までにします。"],["例","『フランケンシュタイン』（1931）実験室の嵐 [知識]"]]},{"g":"演出の光","n":"ネオン（Neon）","b":[["見え方","桃・水色・緑などの濃い色の光が、顔やぬれた地面に映ります。"],["作り方","光る管や看板を画面に入れ、その色で人物を照らします。3Dでは発光する物体＋同じ色のエリアライト。地面をぬらす（反射を強く、ざらつきを小さく）と色が2倍に増えます。空気にうすい煙を足すと光がにじみます。"],["使いどころ","夜の都会、近未来、孤独、あやしい店。2色までにしぼると決まります。"],["例","『ブレードランナー』（1982）雨の街／『恋する惑星』（1994）夜の香港 [知識]"]]},{"g":"演出の光","n":"色つきの光（ジェル）（Colored gels）","b":[["見え方","赤・青・緑など、現実にはない色の光で人物や壁が染まります。"],["作り方","ライトの前に色のフィルム（ジェル）を付けます。3Dではライトの色を変えるだけです。左右から反対の色（赤と青、桃と緑）を当てると、顔が2色に分かれます。"],["使いどころ","悪夢、狂気、音楽の場面、気持ちの急変。肌色が消えるので、普通の場面に戻る所を作ると効きます。"],["例","『サスペリア』（1977）赤と青に染まる館 [知識]"]]},{"g":"演出の光","n":"光の筋（ヘイズ・ボリューム）（Haze / Volumetric light）","b":[["見え方","窓や木の間から差す光が、筋になって見えます。"],["作り方","空気にうすい煙を満たし、硬い光を逆光ぎみに通します。背景が暗いほど筋が見えます。Blenderではワールドか大きな箱に「ボリュームの散乱」を付け、濃さを0.01〜0.05ほどに。平面の編集なら、明るい所だけを取り出して放射状にぼかして重ねます。"],["使いどころ","教会、森、ほこりっぽい倉庫、神々しい登場。煙が濃いと全体が白くねむい絵になります。"],["例","『市民ケーン』（1941）試写室の映写機の光の筋 [知識]"]]},{"g":"演出の光","n":"影絵（ゴボ・クッキー）（Gobo / Cookie）","b":[["見え方","木の葉や窓わくの形の影が、壁や顔にまだらに落ちます。"],["作り方","ライトと人物の間に、穴のあいた板や枝を置きます。板を人物に近づけると影がくっきり、ライトに近づけるとぼけます。3Dでは、ライトの前に穴あきの平面を置くか、ライトに模様の画像を付けます。"],["使いどころ","何もない壁を面白くする、画面の外に木や窓があると感じさせる。模様が細かすぎると顔が汚れて見えます。"],["例","なし"]]},{"g":"演出の光","n":"ブラインドの影（Venetian blind shadows）","b":[["見え方","横じまの光と影が、顔や部屋にかかります。"],["作り方","ゴボの一種です。硬い光を窓の方向から、30〜45度の角度で当てます。3Dでは細長い板を等間隔に並べるだけ。しまの幅は顔に3〜5本かかるくらいが見やすいです。"],["使いどころ","探偵もの、疑い、閉じこめられた感じ。古い犯罪映画の記号なので、パロディにも使えます。"],["例","『深夜の告白』（1944）ブラインドごしの光の部屋 [知識]"]]},{"g":"演出の光","n":"色温度の混ぜ（暖かい光と冷たい光）（Mixed color temperature）※追加","b":[["見え方","橙色の光と青い光が1つの画面にあり、奥行きと気持ちの対比が出ます。"],["作り方","室内は3200K（橙）、窓の外や影は5600K以上（青）にします。3Dではライトごとに色温度の数字を変えるだけ。人物を橙、背景を青にすると、人が前に出て見えます。"],["使いどころ","夜の室内、安全な場所と危ない外、機械と人間。色の節の「ティール＆オレンジ」を光で作る方法です。"],["例","『ターミネーター2』（1991）青い夜と、終盤の工場の橙色 [知識]"]]},{"g":"演出の光","n":"動く光（懐中電灯・ヘッドライト・回転灯）（Moving light sources）※追加","b":[["見え方","光が動くことで、暗い場面に動きと緊張が生まれます。"],["作り方","細いスポットライトを人物の手やカメラ外の車に持たせ、動かします。煙があると光の棒が見えます。3Dではスポットライトの向きを動かし、回転灯は赤と青を0.5秒ごとに入れかえます。"],["使いどころ","捜索、追跡、警察の到着、車が通る夜の部屋。"],["例","『E.T.』（1982）森の中の懐中電灯の光 [知識]"]]},{"g":"演出の光","n":"画面の光（テレビ・スマホ・パソコン）（Screen glow）※追加","b":[["見え方","暗い部屋で、顔だけが下〜正面から青白く照らされます。"],["作り方","顔の前の低い位置に小さな面のライトを置き、色を青白くします。テレビなら明るさと色を0.5〜2秒ごとに不規則に変えます（番組の場面が変わるため）。"],["使いどころ","夜ふかし、孤独、知らせを受け取る瞬間。現代の「下からの光」です。"],["例","なし"]]},{"g":"昼夜のごまかし","n":"デイ・フォー・ナイト（昼に夜を撮る）（Day for night）","b":[["見え方","昼に撮った絵を暗く青くして、月夜に見せます。"],["作り方","晴れた昼に、太陽を人物の後ろか横に置いて撮ります（太陽が月の役）。明るさを1.5〜2段下げ、青〜青緑へ寄せ、彩度を30〜50%下げます。空は写さないか、別に暗くします。窓や車のライトは後から光らせます。コードなら「明るさ×0.3、赤×0.6・緑×0.8・青×1.0、彩度×0.6」あたりから始めます。"],["使いどころ","広い荒野や海の夜（本当の夜は暗すぎて写らない）。影がくっきり長いのに空が明るい、という矛盾が出やすいです。"],["例","『マッドマックス 怒りのデス・ロード』（2015）夜の沼地の場面 [知識]／この技法のフランスでの呼び名が題名になった『アメリカの夜』（1973）[知識]"]]},{"g":"昼夜のごまかし","n":"プアマンズ・プロセス（止まった車）（Poor man's process）","b":[["見え方","止まっている車の中なのに、夜道を走っているように見えます。"],["作り方","車を暗い場所に止め、背景は黒にします。人が車を小さくゆらし、外でライトを前から後ろへ動かして「通りすぎる街灯」を作り、扇風機で風を当てます。コードなら、車と人物は固定し、①顔を横切る光を2〜4秒おきに不規則に通す ②カメラを1〜2ピクセルゆらす ③窓に流れる光の点を足す、の3つです。"],["使いどころ","夜の車内の会話。昼や、窓の外がはっきり見える場面では使えません。人物に当たる光が動かないとばれます。"],["例","『ゴッドファーザー』（1972）夜の車内の場面、『ザ・ロック』（1996）車内のアップ [確認]"]]}],"07":[{"g":"整える","n":"色補正（Color correction）","b":[["見え方","白が白く、肌が自然で、カットごとの色のずれがない状態になります。目立たないのが成功です。"],["作り方","順番は ①明るさ（一番暗い所を0〜5%、一番明るい所を90〜100%に）②白の色（白い物の赤・緑・青が同じ値になるように）③明暗の差 ④彩度。目ではなく、波形（明るさの分布を見るグラフ）で合わせます。コードなら、白い物の画素の値を測り、赤・緑・青それぞれに「目標値÷測った値」をかけます。"],["使いどころ","すべての素材の最初に。ここを飛ばして型をかけると、カットごとに色がばらつきます。"],["例","なし"]]},{"g":"整える","n":"グレーディング（Color grading）","b":[["見え方","作品全体に決まった雰囲気の色が付きます。"],["作り方","補正の後に行います。全体（一次）→一部だけ（二次。顔・空など範囲を選んで）→仕上げの型、の順。影・中間・明るい所の3つに別々の色を足すのが基本です。コードなら、明るさで重みを付けて色を足します（影の重み＝1−明るさ、明るい所の重み＝明るさ）。足す量は0.03〜0.08（0〜1の値で）と少しで十分です。"],["使いどころ","場所・時間・気持ちを色で伝えたい時。強くかけるほど素材の傷みと肌の不自然さが目立ちます。"],["例","『オー・ブラザー！』（2000）全編をコンピューターで色調整し、緑の夏を枯れた黄色に変えた初期の長編 [知識]"]]},{"g":"整える","n":"LUT（ラット。色の変換表）（Look-up table）","b":[["見え方","1つのファイルを当てるだけで、決まった色の雰囲気になります。"],["作り方","「この色が来たらこの色にする」という対応表です。.cube という文字のファイルで、33×33×33個の点が入っているものが一般的。Pythonなら表を読み、赤・緑・青の値で表を引いて、間は補間（間の値を計算でうめる）します。かける強さは50〜80%に弱めるのが目安です。"],["使いどころ","同じ雰囲気を何本もの動画にそろえたい時。補正していない素材にかけると破たんするので、必ず補正の後に。"],["例","なし"]]},{"g":"整える","n":"肌色を守る（Protecting skin tones）","b":[["見え方","全体に強い色を付けても、人の肌だけは健康に見えます。"],["作り方","色あいが15〜35度あたりで、彩度と明るさが中くらいの画素を「肌」として選び（少しぼかす）、その部分だけ型の効きを弱めます。色の分布を見る円のグラフ（ベクトルスコープ）では、肌は赤と黄の間の1本の線の上に乗るのが正解です。"],["使いどころ","ティール＆オレンジ、緑の世界、銀残しなど、強い型すべて。肌が緑や紫に転ぶと、見る人はすぐ「変だ」と感じます。"],["例","なし"]]},{"g":"整える","n":"Log・RAW（ログ・ロウ）","b":[["見え方","撮ったままだと、灰色っぽく眠い絵です。後で明暗と色を自由に決めるための「材料の状態」です。"],["作り方","Logは明るい所と暗い所を両方残すために、わざと平らに記録する方式。RAWはカメラの受け取った光をほぼそのまま残す方式です。どちらも、まず普通の見え方に変換（専用のLUTなど）してから色を付けます。3Dやコードでは「計算は光の量そのまま（リニア）で行い、最後に見た目用の変換をかける」という決まりに当たります。Blenderの「ビュー変換（AgXやFilmic）」がこの役です。"],["使いどころ","後で色を大きく動かす本番の撮影。変換を忘れると色がおかしくなります。合成やぼかしは、見た目用に変換する前の状態で計算すると自然です。"],["例","なし"]]},{"g":"整える","n":"色温度をずらす（暖かい・冷たい）（White balance shift）※追加","b":[["見え方","全体が橙色に寄ると暖かく、青に寄ると冷たく見えます。"],["作り方","赤と青を反対に動かします。暖かく＝赤×1.05〜1.15・青×0.85〜0.95。冷たく＝その逆。緑はほぼ動かしません。"],["使いどころ","一番安くて効く色の演出です。回想は暖かく、病院や孤独は冷たく。やりすぎると白い物が白に見えなくなります。"],["例","なし"]]},{"g":"整える","n":"S字カーブ（明暗の差をつける）（S-curve）※追加","b":[["見え方","暗い所はより暗く、明るい所はより明るくなり、絵が締まります。色も少し濃く見えます。"],["作り方","明るさの入出力のグラフを、まん中（0.5）は動かさず、0.25の所を0.20へ、0.75の所を0.80へ、とS字に曲げます。式なら、なめらかなS字の関数（例：x×x×(3−2x)）と元の値を混ぜます。"],["使いどころ","眠い絵を締める時。逆S字（差を弱める）はパステルや夢の場面に。"],["例","なし"]]},{"g":"整える","n":"スプリットトーン（影と明るい所に別の色）（Split toning）※追加","b":[["見え方","影に1色、明るい所に別の1色が乗ります。"],["作り方","影の重み（1−明るさ）で色Aを、明るい所の重み（明るさ）で色Bを足します。ティール＆オレンジはA＝青緑・B＝橙の場合です。白黒の絵にかけると2色（デュオトーン）になります。"],["使いどころ","ほとんどの「型」の正体がこれです。色の輪で反対どうしを選ぶと強く、近い色を選ぶとおだやかです。"],["例","なし"]]},{"g":"整える","n":"黒を浮かせる（マットな黒）（Lifted blacks）※追加","b":[["見え方","真っ黒が灰色がかり、色あせた写真や古いフィルムのように見えます。"],["作り方","一番暗い値を0から0.03〜0.08へ持ち上げます（出力＝入力×(1−a)＋a）。そこに青や緑を少し足すと「色のついた影」になります。"],["使いどころ","思い出、SNSのおしゃれな旅動画、やわらかい雰囲気。暗い場面では締まりがなくなります。"],["例","なし"]]},{"g":"型","n":"ティール＆オレンジ（Teal and orange）","b":[["見え方","影と背景が青緑、肌と明るい所が橙。人物が背景から浮いて見えます。"],["作り方","肌の橙（約30度）と、輪の反対側の青緑（約180〜200度）を使う補色の型です。影に青緑を足し（赤−0.05・緑＋0.02・青＋0.05ほど）、明るい所に橙を足し（赤＋0.05・青−0.05）、肌は守ります。撮影の時から、背景に青い物、人物に暖かい光を置くとよく決まります。"],["使いどころ","アクション、大作、夏、砂漠と空。どの映画も同じに見える原因でもあるので、弱めにかけます。"],["例","『トランスフォーマー』（2007）全編／『マッドマックス 怒りのデス・ロード』（2015）橙の砂と青い空 [知識]"]]},{"g":"型","n":"ブリーチバイパス（銀残し）（Bleach bypass）","b":[["見え方","色がうすく、明暗の差が強く、黒が重くざらついた絵になります。"],["作り方","フィルムの現像で、銀を洗い流す工程を飛ばす方法です。カラーの絵の上に白黒の絵が重なった状態になります。コードなら、白黒にした絵を元の絵に「オーバーレイ（明るい所はより明るく、暗い所はより暗くする重ね方）」で重ね、彩度を0.4〜0.6倍にします。粒も足します。"],["使いどころ","戦争、犯罪、荒れた世界、冷たい現実。明るい恋愛ものには合いません。"],["例","『プライベート・ライアン』（1998）上陸の場面／『セブン』（1995）[知識]。日本映画『おとうと』（1960）が元祖とされます [知識]"]]},{"g":"型","n":"クロスプロセス（Cross processing）","b":[["見え方","色が濃く、明暗の差が強く、色が変な方向にずれます（明るい所が黄緑、影が青や赤紫）。"],["作り方","フィルムを、本来とちがう種類の薬品で現像する方法です。コードなら色ごとにカーブを変えます。赤＝S字、緑＝明るい側を強めたS字、青＝差を弱める（暗い所を0.1〜0.15へ上げ、明るい所を0.85へ下げる）。彩度は1.2〜1.4倍。"],["使いどころ","音楽ビデオ、混乱、薬や熱で頭がおかしくなった感じ。長時間見ると疲れます。"],["例","『ドミノ』（2005）リバーサルフィルム（スライド用のフィルム）をクロスプロセスした荒れた色 [確認]"]]},{"g":"型","n":"白黒（Black and white / Monochrome）","b":[["見え方","色がなくなり、形・光・顔の表情に目が行きます。"],["作り方","明るさの式（赤×0.2126＋緑×0.7152＋青×0.0722）で1つの値にします。混ぜる割合を変えると印象が変わります（赤を多くすると青空が暗く、肌が明るくなる）。色がないぶん明暗の差を強めにし、光で形を分けます。"],["使いどころ","過去、記録、時代を感じさせない話、悲しみ。色で見分けていた物（赤い服と緑の壁）が同じ灰色になることに注意します。"],["例","『シンドラーのリスト』（1993）／『ROMA／ローマ』（2018）[知識]"]]},{"g":"型","n":"セピア","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","昔の写真の色なので、「遠い過去」「ふるさと」「まだ色のない退屈な日常」の印として使います。後で鮮やかな色の世界と対比させると効きます。"],["例","『オズの魔法使』（1939）冒頭の農場の場面 [知識]"]]},{"g":"型","n":"1色だけ残す","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","白黒の中に1色だけ残し、その物や人を物語の印にします。長く使うと仕掛けに見えるので、1作品で1〜2回、ここぞという所だけです。"],["例","『シンドラーのリスト』（1993）赤い服の子ども／『シン・シティ』（2005）白黒の中の赤や黄 [知識]"]]},{"g":"型","n":"2色","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","初期のカラー映画は赤と緑の2色しか記録できず、肌は出るが青空が出ない独特の色でした。今は「昔のカラー」「ポスターのような強さ」を出すために真似します。"],["例","『アビエイター』（2004）前半を昔の2色式カラー風の色で再現（青い豆が出てくる食事の場面など）[知識]"]]},{"g":"型","n":"パステル（Pastel）","b":[["見え方","桃・水色・うす黄など、白を混ぜたような明るくやさしい色ばかりになります。"],["作り方","色の調整だけでは作れません。まず衣装・壁・小物をパステルの色でそろえ、正面からやわらかい光を当てて影を浅くします。仕上げで、明るさを上げ、明暗の差を下げ、彩度は30〜50%ほどに。コードで絵を作るなら、色を「彩度0.3〜0.5、明るさ0.85〜0.95」の中から選びます。"],["使いどころ","絵本、おとぎ話、かわいい世界。その中に暗い出来事を置くと、落差が強く出ます。"],["例","『グランド・ブダペスト・ホテル』（2014）桃色のホテル [知識]"]]},{"g":"型","n":"緑がかった世界（Green tint）","b":[["見え方","全体がうっすら緑で、病気・機械・作りものの感じがします。"],["作り方","中間の明るさに緑を少し足します（緑＋0.03〜0.06、または赤と青を少し下げる）。影は暗い緑、明るい所はやや黄緑に。肌が緑になりすぎないよう守ります。"],["使いどころ","仮想の世界、病院、蛍光灯の事務所、毒。逆に黄緑と赤を組み合わせると、なつかしく温かい絵にもなります。"],["例","『マトリックス』（1999）仮想世界は緑、現実は青 [知識]／『アメリ』（2001）緑と赤と金色 [知識]"]]},{"g":"型","n":"テクニカラー風（Technicolor look）","b":[["見え方","赤・緑・青がにごらず、こってりと濃い色。1930〜50年代の夢のような色です。"],["作り方","当時は赤・緑・青を3本の白黒フィルムに別々に撮り、染料で刷りました。真似るには、彩度を1.3〜1.5倍にし、色どうしを離します（赤から緑と青を少し引く、を3色それぞれに行う）。強い光で影を少なくし、衣装に原色を使います。"],["使いどころ","ミュージカル、おとぎ話、昔のハリウッドへのあこがれ。現実的な話には派手すぎます。"],["例","『オズの魔法使』（1939）色の国／『赤い靴』（1948）[知識]"]]},{"g":"型","n":"フィルム風（粒・ハレーション）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","デジタルで撮った絵の「きれいすぎ」を消すために足します。粒は暗い所に多く、明るい所に少なく。ハレーション（強い光のまわりの赤いにじみ）は、明るい所だけ取り出してぼかし、赤橙にして重ねます。時代ものや思い出の場面で特に効きます。"],["例","なし"]]},{"g":"色の設計","n":"補色（Complementary colors）","b":[["見え方","色の輪で反対どうしの2色（赤と緑、青と橙、黄と紫）が並び、おたがいを強く見せます。"],["作り方","主役の色を決め、色あいに180度を足した色を背景か相手役に使います。面積は半々にせず、7:3か9:1に。"],["使いどころ","対立、人物を目立たせる、にぎやかさ。半々だと目がちかちかします。"],["例","『アメリ』（2001）赤い部屋と緑の小物 [知識]"]]},{"g":"色の設計","n":"類似色（Analogous colors）","b":[["見え方","色の輪で隣どうしの色（赤・橙・黄など）でまとまり、おだやかに見えます。"],["作り方","主役の色から左右30〜60度以内の色だけを使います。明るさと彩度で差を付けます。"],["使いどころ","調和、あたたかい部屋、自然の中。変化が足りない時は、反対の色を1点だけ置きます。"],["例","『her／世界でひとつの彼女』（2013）赤・桃・橙でまとめた部屋と衣装 [知識]"]]},{"g":"色の設計","n":"3色（トライアド）（Triadic colors）","b":[["見え方","色の輪を3等分した3色（赤・黄・青など）が並び、元気でにぎやかに見えます。"],["作り方","色あいを120度ずつ離します。1色を主役（6割）、1色をわき役（3割）、1色を差し色（1割）にします。"],["使いどころ","子ども向け、ヒーロー、ポップな世界。3色とも濃くすると、おもちゃ売り場になります。"],["例","『気狂いピエロ』（1965）赤・青・黄の原色 [知識]"]]},{"g":"色の設計","n":"単色（モノクロマティック）（Monochromatic）","b":[["見え方","1つの色あいだけで、明るさと濃さだけが変わります。"],["作り方","色あいを1つに固定し、明るさと彩度だけを動かします。撮った後なら、白黒にしてから1色を乗せるか、その色以外の彩度を下げます。"],["使いどころ","異世界、極端な気持ち、砂あらしや霧。場面単位で使い、次の場面で色を変えると切り替わりが強く出ます。"],["例","『ブレードランナー 2049』（2017）橙一色の廃墟の街 [知識]"]]},{"g":"色の設計","n":"カラースクリプト（場面ごとの色の台本）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","物語の最初から最後までを小さな色の絵で並べ、気持ちの上がり下がりと色が合っているかを撮る前に確かめます。長編アニメでは必ず作ります。実写でも、場面ごとの色の帯を作っておくと、衣装・美術・光の全員が同じ方を向けます。"],["例","ピクサーの長編アニメ（『カールじいさんの空飛ぶ家』（2009）など）[知識]"]]},{"g":"色の設計","n":"彩度で気持ちを語る（Saturation as emotion）","b":[["見え方","うれしい時は色が濃く、落ちこんだ時は色がうすくなります。"],["作り方","場面ごとに彩度の倍率を決めます（例：幸せ1.2、ふつう1.0、喪失0.5）。変える時は、場面の変わり目で切り替えるか、5〜10秒かけてゆっくり動かします。"],["使いどころ","主人公の心の変化、シリーズが進んで話が暗くなる時。見る人に気づかれないくらいの差が上品です。"],["例","『カールじいさんの空飛ぶ家』（2009）妻を亡くした後に色がうすくなる [知識]"]]},{"g":"色の設計","n":"色の意味づけ（Color symbolism / Color coding）","b":[["見え方","ある色が出るたびに、同じ意味（危険、ある人物、ある場所）を感じます。"],["作り方","作品の中で「この色＝この意味」を1つ決め、ほかの場面ではその色を画面から抜いておきます。場所や話ごとに全体の色を変える方法もあります。"],["使いどころ","複数の話が並ぶ作品、伏線、人物の変化（衣装の色が変わる）。「赤＝危険」のような世の中の約束より、作品の中で決めた約束のほうが強く効きます。"],["例","『トラフィック』（2000）3つの話を黄・青・ふつうの色で分ける／『シックス・センス』（1999）大事な場面にだけ赤い物／『HERO』（2002）語りごとに衣装の色が変わる [知識]"]]},{"g":"色の設計","n":"白黒から色へ切り替え（B&W to color transition）","b":[["見え方","白黒だった世界に色が付きます（または逆）。"],["作り方","彩度を0から1へ動かします。一気に切り替える／ドアを開けるなど動きに合わせる／物や人1つずつ色づく（範囲を選んで彩度をもどす）の3通りがあります。"],["使いどころ","別の世界に入る、生き返る、恋をする、視点が変わる。物語で一番大事な変化に1回だけ使います。"],["例","『オズの魔法使』（1939）ドアを開けると色の国／『カラー・オブ・ハート』（1998）心が動いた人から色づく／『ベルリン・天使の詩』（1987）天使の見る世界は白黒 [知識]"]]}],"08":[{"g":"カットの種類","n":"ストレートカット","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","映画のつなぎの9割以上はこれです。何も効果を足さないのが基本で、ほかの技法は「ここは特別」という印として使います。切る位置は、動きの始まり・終わり・視線が動いた瞬間のどれかにすると自然です。"],["例","なし（すべての映画）"]]},{"g":"カットの種類","n":"ジャンプカット（Jump cut）","b":[["見え方","同じ人を同じ角度で撮った絵の途中がとんで、位置や姿勢がぴょんと変わります。"],["作り方","1つのカットの中から間を抜きます。抜く量は最低でも10コマ以上（少なすぎると失敗に見える）。YouTubeの語りなら、息つぎと言いよどみを抜きます。コードなら、同じ素材の「0〜40コマ」と「70〜110コマ」をそのまま並べるだけです。"],["使いどころ","時間の省略、落ち着かない気持ち、テンポのよい語り、同じ作業のくり返し。普通の会話で使うとミスに見えるので、3回以上続けて「わざとだ」と分からせます。"],["例","『勝手にしやがれ』（1960）車の助手席の女性の絵がとびとびになる場面 [知識]"]]},{"g":"カットの種類","n":"マッチカット（形・動き・視線）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","離れた時間や場所を、似た形・同じ動きでつないで「この2つは関係がある」と伝えます。時間を一気にとばす時や、対比を見せる時に使います。前後で、形の位置と大きさを画面の同じ所にそろえるのがすべてです。"],["例","『2001年宇宙の旅』（1968）投げた骨から宇宙船へ／『アラビアのロレンス』（1962）マッチの火から砂漠の日の出へ [知識]"]]},{"g":"カットの種類","n":"アクションつなぎ（Cut on action / Match on action）","b":[["見え方","動きの途中でカメラの位置が変わるのに、切れ目に気づきません。"],["作り方","同じ動き（立ち上がる、ドアを開ける、なぐる）を2つの角度から撮り、動きの1/3〜半分の所で切って、次のカットで動きを終わらせます。動きを1〜3コマ重ねる（少しだけくり返す）とより自然で、アクションでは逆に2〜3コマ抜くと速く見えます。"],["使いどころ","ほぼすべての動きのある場面。目が動きを追っているので、切れ目が隠れます。動きの前や後の止まった所で切ると、切れ目が目立ちます。"],["例","なし（ほぼすべての映画）"]]},{"g":"カットの種類","n":"カットアウェイ（Cutaway）","b":[["見え方","主な出来事からいったん離れ、まわりの別の物（見物人、時計、空）を見せてからもどります。"],["作り方","1〜3秒の別の絵をはさみます。はさんだ間に主の絵の時間をとばせるので、長い作業を短くしたり、つながらない2つのカットをつないだりできます。"],["使いどころ","時間を縮める、まわりの反応を見せる、ミスを隠す。関係のない絵だと話が止まります。"],["例","なし"]]},{"g":"カットの種類","n":"インサート（Insert shot）","b":[["見え方","場面の中の小さな物（手元、手紙、スマホの画面、鍵）のアップが入ります。"],["作り方","広い絵の途中に、1〜2秒のアップをはさみます。文字を見せるなら読み終わる長さの1.5倍。手や物の位置と光を、広い絵とそろえます。"],["使いどころ","大事な物を見落とさせない、伏線、作業の手順。多すぎると説明くさくなります。"],["例","ウェス・アンダーソン監督の作品に多い、真上から見た手元や手紙のアップ [知識]"]]},{"g":"カットの種類","n":"クロスカット（並行）（Cross-cutting / Parallel editing）","b":[["見え方","2つ以上の場所の出来事を交互に見せ、同時に起きていると感じさせます。"],["作り方","A→B→A→B と交互に並べます。山場に向けて1回の長さを短くします（例：8秒→4秒→2秒→1秒）。最後に2つが出会う（助けが間に合う）と気持ちよく終わります。"],["使いどころ","追う側と逃げる側、助けが間に合うか、対比（静かな儀式と暴力）。3か所以上を回す時は、場所ごとに色や音を変えて迷わせません。"],["例","『ゴッドファーザー』（1972）教会の儀式と各地の襲撃／『羊たちの沈黙』（1991）2つの家の玄関 [知識]"]]},{"g":"カットの種類","n":"スマッシュカット（Smash cut）","b":[["見え方","静かな場面から、いきなり大きな音と激しい絵へ（または逆へ）とびます。"],["作り方","絵も音も同じコマでばっさり切ります。前のカットは、せりふや動きの途中で切るとより急に感じます。重ねやフェードは使いません。音の差が命で、前を静かに、後ろを最大に。"],["使いどころ","悪夢から飛び起きる、「絶対にやらない」と言った直後にやっている（笑い）、暴力の始まり。1作品に数回まで。"],["例","なし（悪夢から飛び起きる型はホラー全般）"]]},{"g":"カットの種類","n":"Jカット（J-cut）","b":[["見え方","次の場面の音が先に聞こえ、後から絵が切り替わります。"],["作り方","編集の画面で、音の切れ目を絵より左（前）へずらします（形がJの字）。ずらす量は12〜48コマ（0.5〜2秒）。会話では、相手が話し始めて数コマ〜半秒してから相手の顔へ切ります。"],["使いどころ","場面の変わり目をなめらかにする、「何の音？」と興味を引く。会話の基本でもあります。"],["例","なし（会話の場面全般）"]]},{"g":"カットの種類","n":"Lカット（L-cut）","b":[["見え方","絵は次へ切り替わったのに、前の場面の音や声が続きます。"],["作り方","音の切れ目を絵より右（後ろ）へずらします（形がLの字）。話している人の声を残したまま、聞いている人の顔を見せるのが代表です。"],["使いどころ","聞き手の反応を見せる、語りを次の場面にかぶせる、余韻。JとLを混ぜると、会話が卓球のような単調さから抜けます。"],["例","なし（会話の場面全般）"]]},{"g":"カットの種類","n":"見えないカット（Invisible cut / Hidden cut）","b":[["見え方","切っているのに、1つの長いカットに見えます。"],["作り方","切れ目を隠せる瞬間を作ります。①画面が真っ暗になる（背中、柱、暗い戸口）②速い横ぶれ ③物や人がカメラの前を横切る ④同じ構図で止まった絵。切れ目の前後で、明るさ・色・カメラの速さと向きをそろえます。コードなら、前後の数コマを重ねて混ぜるとより隠れます。"],["使いどころ","全編1カット風の作品、長回しの中の失敗を直す、場所を瞬間移動する。"],["例","『ロープ』（1948）人の背中で画面を暗くして切る／『1917 命をかけた伝令』（2019）／『バードマン』（2014）[知識]"]]},{"g":"カットの種類","n":"軸上のカット","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","カメラの向きを変えずに、まっすぐ寄る（または引く）方向へ2〜3段で切ります。ズームより強く、「はっ」と気づいた瞬間や、こわい物を見つけた瞬間に使います。段ごとに大きさを1.5〜2倍以上変えないと、ただのジャンプカットに見えます。"],["例","『鳥』（1963）倒れた人の顔へ3段で寄る場面 [知識]／黒澤明監督の作品に多い型 [知識]"]]},{"g":"カットの種類","n":"拍カット","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","音楽の拍に切れ目を合わせます。映画では、全部の拍で切ると音楽ビデオになるので、大事な拍（小節の頭、強い音）だけに合わせ、ほかは動きで切ります。銃声やドアの音を拍に合わせる方法もあります。"],["例","『ベイビー・ドライバー』（2017）動きと音がすべて曲に合った場面 [知識]"]]},{"g":"つながりの決まり","n":"180度の決まり（180-degree rule / イマジナリーライン）","b":[["見え方","会話する2人のうち、Aはいつも左から右を向き、Bはいつも右から左を向いています。"],["作り方","2人を結ぶ見えない線（軸）を引き、カメラはその線の片側（半円の中）だけに置きます。3Dなら、カメラを全部、軸の同じ側に置くだけです。軸をこえたい時は、①カットの中でカメラごと回りこむ ②軸の真上（真正面・真後ろ）の絵を1つはさむ ③人物が動いて軸が変わる、のどれかにします。"],["使いどころ","会話、追いかけ、試合など位置が大事な場面。わざと破ると、混乱・立場の逆転・不気味さが出ます。"],["例","『シャイニング』（1980）赤いトイレの会話で軸をこえる [知識]／小津安二郎監督はこの決まりを守らないことで知られます [知識]"]]},{"g":"つながりの決まり","n":"30度の決まり（30-degree rule）","b":[["見え方","同じ人を続けて見せる時、カメラの位置がはっきり変わるので、とんだように見えません。"],["作り方","同じ被写体を続けて切る時は、カメラの角度を30度以上変えます。大きさも同時に変えると確実です（全身→胸から上）。30度未満で大きさも近いと、ジャンプカットに見えます。"],["使いどころ","同じ人物を別の絵でつなぐ時すべて。軸上のカットは、この決まりをわざと破って強さを出す技法です。"],["例","なし"]]},{"g":"つながりの決まり","n":"切り返し（Shot / Reverse shot）","b":[["見え方","話す人と聞く人を、交互に見せます。"],["作り方","Aの肩ごしにB、Bの肩ごしにA、の2つの絵を対で作ります。レンズ、距離、目の高さをそろえ、視線は左右逆に。切る場所は「話し終わり」ではなく、相手の反応を見せたい瞬間にします。"],["使いどころ","会話のすべて。話が進むにつれて少しずつ寄る（肩ごし→顔だけ）と、盛り上がりを作れます。"],["例","『ヒート』（1995）食堂で向かい合う2人の会話 [知識]"]]},{"g":"つながりの決まり","n":"視線の一致（Eyeline match）","b":[["見え方","人物が画面の外を見る→次のカットで、その人が見ている物が映ります。"],["作り方","見る顔を0.5〜1秒見せてから、見ている物へ切ります。見上げていれば下から、見下ろしていれば上から撮った絵にします。会話では、右を見る人の相手は左を見ます。"],["使いどころ","興味を引く、のぞき見、人物の気持ちに乗せる。見た物の後にもう一度顔にもどると、その人の感情になります。"],["例","『裏窓』（1954）窓から向かいの部屋を見る主人公 [知識]"]]},{"g":"つながりの決まり","n":"エスタブリッシング（状況を見せる絵）（Establishing shot）","b":[["見え方","場面の最初に、建物の外や街の全体など、場所と時間が分かる広い絵が入ります。"],["作り方","2〜4秒の広い絵を場面の頭に置きます。昼か夜か、天気、季節も一緒に伝えます。逆に、アップから始めて後で広い絵を見せると、「ここはどこ？」という興味を引けます。"],["使いどころ","場所が変わった時、時間がとんだ時。毎回入れるとテレビの連続ドラマ風になります。"],["例","なし"]]},{"g":"つながりの決まり","n":"動きの方向（Screen direction）","b":[["見え方","右へ走る人は、次のカットでも右へ走っています。"],["作り方","1つの移動は、画面上の向きをそろえます。追う側と追われる側は同じ向き、ぶつかる2人は逆の向きに。向きを変えたい時は、カメラに向かってまっすぐ来る（または去る）絵を1つはさみます。"],["使いどころ","追いかけ、旅、戦い。「行き」と「帰り」を逆向きにすると、言葉なしで帰りだと分かります。"],["例","なし"]]},{"g":"モンタージュ","n":"クレショフ効果（Kuleshov effect）","b":[["見え方","同じ無表情の顔でも、前後に置く絵によって、空腹・悲しみ・愛情など別の気持ちに見えます。"],["作り方","顔（2秒）→物（2秒）→同じ顔（2秒）と並べます。物を、食べ物・ひつぎ・子どもなどに入れかえるだけで意味が変わります。"],["使いどころ","編集の一番の土台です。役者が表情を作らなくても、つなぎで気持ちは作れます。逆に、意図しない意味が生まれていないかの点検にも使います。"],["例","ソ連の映画作家クレショフが1910年代の終わりごろに行った実験 [知識]"]]},{"g":"モンタージュ","n":"エイゼンシュテインの5種（Eisenstein's methods of montage）","b":[["見え方","ソ連の監督エイゼンシュテインが分けた、カットの組み合わせ方の5つの型です。"],["作り方",""],["","- 長さ（メトリック）：中身に関係なく、決まったコマ数で切ります。だんだん短くすると緊張が上がります（例：48→24→12→6コマ）。"],["","- リズム：絵の中の動きに合わせて切ります（足音、行進、振り下ろす動き）。"],["","- 調子（トーナル）：明るさ・形・雰囲気の似た絵をつないで、気分を作ります（霧、夕暮れ、静かな水）。"],["","- 倍音（オーバートーナル）：上の3つを合わせて、場面全体の感じを作ります。"],["","- 知的：関係のない2つの絵を並べて、頭の中に考えを生ませます（人々と、ほふられる牛）。"],["使いどころ","音楽に合わせた動画は「長さ」と「リズム」の応用です。知的モンタージュは強いぶん押しつけがましくなりやすいです。"],["例","『戦艦ポチョムキン』（1925）大階段の場面／知的＝『ストライキ』（1925）終盤 [知識]"]]},{"g":"モンタージュ","n":"特訓モンタージュ（Training montage）","b":[["見え方","練習や準備の短い場面が音楽に乗って次々と流れ、主人公が上達していきます。"],["作り方","1〜3秒のカットを10〜20個、1〜3分の曲に乗せます。最初は失敗、途中で少しずつ良くなり、最後に成功の絵で終わる、という段階を作ります。同じ構図で「前」と「後」を見せると成長が伝わります。"],["使いどころ","長い時間の努力を短く見せる、準備、恋が深まる、店が繁盛する。定番すぎるので、笑いとして使われることもあります。"],["例","『ロッキー』（1976）走りこみから階段をかけ上がるまで [知識]"]]},{"g":"モンタージュ","n":"時間の省略（Ellipsis / Time compression）","b":[["見え方","途中がとばされ、数分・数年が一瞬で過ぎます。"],["作り方","動きの始まりと終わりだけ残して間を抜きます（家を出る→もう着いている）。とんだことを伝える手がかり（服、髪、季節、光、時計）を次のカットに入れます。同じ構図で、物や人だけが変わっていく方法もあります。"],["使いどころ","ほぼすべての編集。「見る人が自分でうめられる部分は見せない」が基本です。"],["例","『市民ケーン』（1941）朝食の食卓で夫婦の年月が過ぎていく場面 [知識]"]]},{"g":"モンタージュ","n":"回想（Flashback）","b":[["見え方","物語が過去へもどります。"],["作り方","入口に印を付けます（人物のアップ、音がこもる、白く光る、重ね）。過去の場面は色や画面の形を変えると迷いません（色をうすく、暖かく、粒を足すなど）。つらい記憶が一瞬よみがえる時は、2〜8コマの短い絵をさしこみます。"],["使いどころ","理由を明かす、秘密、後悔。多いと今の話が進まなくなります。"],["例","『羅生門』（1950）同じ出来事を何人もの回想で語る／『市民ケーン』（1941）[知識]"]]},{"g":"モンタージュ","n":"先取り（フラッシュフォワード）（Flash-forward）","b":[["見え方","これから起きることが、先に一瞬見えます。"],["作り方","未来の場面を、数コマ〜数秒だけ今の場面にさしこみます。説明はせず、後で同じ絵がもう一度出た時に意味が分かるようにします。冒頭に結末を置いて、そこへ向かって話を進める形もあります。"],["使いどころ","不吉な予感、運命、「どうしてこうなった？」という興味。"],["例","『イージー・ライダー』（1969）終盤の前に、結末の絵が一瞬だけ入る [知識]"]]},{"g":"モンタージュ","n":"重ね編集（同じ瞬間を繰り返す）（Overlapping editing）","b":[["見え方","爆発や落下など1つの瞬間が、角度を変えて2〜3回続けて映ります。"],["作り方","同じ動きを別の角度で撮り、それぞれ動きの頭から（または0.5〜1秒もどして）つなぎます。時間が引きのばされます。"],["使いどころ","大きな爆発、危ない技、決定的な一撃。本当にやったことの証明にもなります。普通の動きに使うと変です。"],["例","『プロジェクトA』（1983）時計台からの落下を、別の回の絵で2度続けて見せる [確認]／『戦艦ポチョムキン』（1925）皿を割る動きのくり返し [知識]"]]},{"g":"モンタージュ","n":"リプレイ（Replay）","b":[["見え方","さっき見た場面を、もう一度（遅く、別の角度で、別の人の目で）見せます。"],["作り方","同じ素材を、速度を25〜50%に落とす／別の角度の絵にする／巻きもどしの絵（逆再生を4〜8倍速）をはさむ、などして再び流します。"],["使いどころ","スポーツ、推理の種明かし（「実はこの時…」）、やり直しの物語。"],["例","『ラン・ローラ・ラン』（1998）同じ20分を3回やり直す [知識]"]]},{"g":"リズム","n":"テンポの緩急（Pacing）","b":[["見え方","速く切る所とゆっくり見せる所があり、見ていて疲れず、山場が強く感じられます。"],["作り方","場面ごとに1カットの平均の長さを決めます（静かな会話5〜8秒、追いかけ1〜2秒など）。速い場面の前後に、長いカットを置きます。速くても迷わせないために、見てほしい物を前後のカットで画面の同じ位置（特にまん中）に置きます。"],["使いどころ","全体の設計。ずっと速いと、速さを感じなくなります。"],["例","『マッドマックス 怒りのデス・ロード』（2015）約2700カット（1カット平均2.6秒ほど）でも、見る物を画面のまん中にそろえて迷わせない [確認]"]]},{"g":"リズム","n":"間（ま）（Pause / Beat）","b":[["見え方","何も起きない静かな時間があり、気持ちがしみてきます。"],["作り方","せりふや動きが終わっても切らず、1〜2秒（大きな場面では3〜5秒）そのまま見せます。音も減らします。その後に次の出来事を置きます。"],["使いどころ","告白の後、死の後、笑いのオチの直前（半秒の間）。間がないと、見る人が感じる時間がなくなります。"],["例","宮崎駿監督が、何もしない時間をわざと入れると語っています [知識]"]]},{"g":"リズム","n":"切り替えの密度","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","1分あたりのカット数で、場面の興奮の度合いを決めます。映画全体では「1カットの平均の長さ」で比べます。山場に向けて密度を上げ、山場の直後に長い1カットを置くと、落差で両方が効きます。"],["例","なし"]]},{"g":"リズム","n":"マーチの6つの優先順位（Walter Murch's Rule of Six）","b":[["見え方","よいカットかどうかを判断する、6つのものさしです。"],["作り方","切る時に、上から順に大事にします。①気持ち51%　②物語23%　③リズム10%　④視線（見る人の目が画面のどこにあるか）7%　⑤画面の平面でのつながり5%　⑥立体の空間のつながり4%。全部は満たせない時は、下から捨てます。つまり、位置が少しつながらなくても、気持ちが合っていればそのカットは正しいです。"],["使いどころ","迷った時の判断。マーチは、人がまばたきする瞬間（考えが一区切りした時）が切る場所だ、とも述べています [知識]。"],["例","編集者ウォルター・マーチの本『映画の瞬き』 [確認]"]]},{"g":"リズム","n":"Bロール（B-roll）","b":[["見え方","話している人の絵（Aロール）の上に、話の内容に合った別の絵が重なります。"],["作り方","声はそのまま流し、絵だけを2〜5秒の関連する絵に差しかえます。手元、風景、資料、作業のようす。語りの切れ目（ジャンプカット）を隠すのにも使います。"],["使いどころ","インタビュー、解説動画、Vlog。話と関係のうすい絵を入れると気が散ります。"],["例","なし（ドキュメンタリーと解説動画の基本）"]]},{"g":"リズム","n":"リアクションショット（Reaction shot）※追加","b":[["見え方","出来事そのものではなく、それを見た人の顔を見せます。"],["作り方","出来事の直後（または直前）に、見ている人の顔を1〜3秒入れます。見せたい物を後回しにして顔を先に見せると、期待が高まります。"],["使いどころ","驚き、笑い、恐怖。見る人は顔を手がかりに感じ方を決めるので、反応のない場面は弱くなります。"],["例","『ジュラシック・パーク』（1993）恐竜を見せる前に、見上げる人たちの顔を先に見せる [知識]"]]},{"g":"リズム","n":"フラッシュカット（Flash cut / Subliminal cut）※追加","b":[["見え方","1〜数コマだけ別の絵が入り、何かが見えた気がします。"],["作り方","1〜4コマの絵をさしこみます。1コマではほぼ読めず、3〜4コマで「何か分かる」くらいです。音を付けると気づかれやすくなります。"],["使いどころ","よみがえる記憶、予感、頭の混乱。強い光の点滅にならないよう、白い絵のくり返しは避けます。"],["例","『ファイト・クラブ』（1999）ある人物が1コマだけ画面に映りこむ [知識]"]]},{"g":"リズム","n":"切らない（長回し）（Long take）※追加","b":[["見え方","1つのカットが数十秒〜数分続き、その場にいるような緊張が生まれます。"],["作り方","切るかわりに、カメラと人物の動きで見せる物を変えていきます（寄る、ふり向く、別の人を追う）。編集の中では「切らない」ことも選択の1つです。"],["使いどころ","逃げ場のない緊張、時間の長さを感じさせたい時、技を見せたい時。意味なく長いと退屈です。"],["例","『トゥモロー・ワールド』（2006）車の中の襲撃／『黒い罠』（1958）冒頭 [知識]"]]},{"g":"画面を分ける","n":"分割画面","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","同時に起きている2つを並べる（電話の両側）、対比を見せる（理想と現実）、緊張を上げる（追う側と追われる側）時に使います。クロスカットを「同時に」見せる方法です。"],["例","『（500）日のサマー』（2009）期待と現実を左右に並べる／『キル・ビル Vol.1』（2003）病院の場面 [知識]"]]},{"g":"画面を分ける","n":"小窓（PinP）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","映画ではあまり使わず、ニュース、ゲーム実況、ビデオ通話の画面として出てきます。主の絵を止めずに、別の情報（反応する顔、手元、地図）を足したい時に使います。"],["例","なし"]]},{"g":"画面を分ける","n":"多画面（Multi-screen）","b":[["見え方","画面が3つ以上の窓に分かれ、それぞれ別の絵が動きます。"],["作り方","窓の大きさと並びを決め、同時に流します。見てほしい窓を大きく・明るくし、音もその窓のものを大きくします。窓を1つずつ増やす、同じ絵を全部の窓に広げる、などの動きも付けられます。"],["使いどころ","作戦の準備、たくさんの人の同時の動き、漫画のコマのような表現。情報が多すぎると何も伝わりません。"],["例","『華麗なる賭け』（1968）たくさんの窓で見せる場面／『タイムコード』（2000）4つの画面を最後まで同時に流す／『ハルク』（2003）漫画のコマ風の分割 [知識]"]]}],"09":[{"g":"昔からの型","n":"フェードイン・アウト（Fade in / Fade out）","b":[["見え方","絵がだんだん黒くなって消える（アウト）、黒からだんだん現れる（イン）。"],["作り方","出力＝A×(1−t)。長さは12〜48コマ（0.5〜2秒）。音も同じ長さで下げます。アウトとインの間に黒を数コマ〜1秒はさむと、区切りが強くなります。"],["使いどころ","始まりと終わり、章の区切り、長い時間の経過、眠りと目覚め。場面ごとに使うと話が止まって見えます。"],["例","なし（ほぼすべての映画の最初と最後）"]]},{"g":"昔からの型","n":"ディゾルブ（重ね）（Dissolve / Cross dissolve）","b":[["見え方","前の絵がうすれながら、次の絵が重なって現れます。"],["作り方","出力＝A×(1−t)＋B×t。ふつう12〜48コマ。3〜5秒かけると夢のよう、4〜8コマだと「やわらかいカット」になります。途中で両方の絵が見えるので、重なった時にきれいになる組み合わせ（暗い所に明るい物が来る）を選びます。"],["使いどころ","時間の経過、思い出、つながりのある2つの場面、モンタージュ。意味なく使うと古く・眠く見えます。"],["例","『地獄の黙示録』（1979）冒頭、密林と天井の扇風機と顔が重なる [知識]"]]},{"g":"昔からの型","n":"マッチディゾルブ（Match dissolve）","b":[["見え方","似た形の2つの絵が重なって入れかわり、片方がもう片方に変わったように見えます。"],["作り方","前後の絵で、形の位置・大きさ・向きを画面の同じ所にそろえてからディゾルブします（24〜48コマ）。コードなら、2つの絵の目印（円の中心、顔の目の位置）を合わせるように、片方を移動・拡大してから混ぜます。"],["使いどころ","昔と今（若い顔と老いた顔、新しい船と沈んだ船）、物と物の意味のつながり。"],["例","『サイコ』（1960）排水口から目へ／『タイタニック』（1997）海の底の船から出港前の船へ [知識]"]]},{"g":"昔からの型","n":"ワイプ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","1930年代の連続活劇や黒澤明監督の作品でよく使われ、「場面が次へ進む」ことを元気に伝えます。今使うと昔の冒険ものの味になります。人や乗り物の動きと同じ向きにふくと自然です。"],["例","『隠し砦の三悪人』（1958）と、その影響を受けた『スター・ウォーズ』（1977）[確認]"]]},{"g":"昔からの型","n":"アイリス（丸く閉じる）（Iris in / Iris out）","b":[["見え方","丸い窓がすぼまって絵が黒く閉じる（または黒から丸く開く）。"],["作り方","円のぬき型の半径を動かします（半径＝最大×(1−t)）。円の中心は画面のまん中ではなく、見せたい物（顔、手がかり）に置きます。閉じる途中で1秒ほど止めると、「ここを見て」の印になります。長さは12〜24コマ。"],["使いどころ","無声映画やアニメの味、笑いのオチ、最後の一言。古風でかわいい印象になります。"],["例","無声映画の時代によく使われた型／短編アニメ『ルーニー・テューンズ』の終わり方 [知識]"]]},{"g":"昔からの型","n":"時計ワイプ（Clock wipe）","b":[["見え方","時計の針が回るように、境目が中心のまわりを1周して次の絵に変わります。"],["作り方","画素ごとに中心からの角度（0〜360度）を計算し、「角度＜t×360」の所を次の絵にします。12時の位置から時計回りが基本。長さは12〜24コマ。"],["使いどころ","時間が過ぎたこと、待たされたこと。見た目がそのまま「時計」なので、時間の話以外では使いにくいです。"],["例","なし [不明]（『スター・ウォーズ』シリーズに時計型があると記憶していますが、どの場面かを確かめられませんでした）"]]},{"g":"昔からの型","n":"押し出し（Push）","b":[["見え方","次の絵が横や上から入ってきて、前の絵を画面の外へ押し出します。"],["作り方","Aを−t×画面幅、Bを(1−t)×画面幅だけずらして並べます。ワイプとちがい、両方の絵が動きます。8〜14コマで、始めと終わりをゆっくりに。"],["使いどころ","スライド、スマホの画面の切り替え風、隣の部屋へ移る感じ、一覧を順に見せる。"],["例","なし"]]},{"g":"昔からの型","n":"ページめくり（Page turn / Page peel）","b":[["見え方","本のページのように絵の角がめくれて、下から次の絵が現れます。"],["作り方","絵を板にはりつけ、筒に巻くように曲げながら回します。めくれた裏側は少し暗くし、下の絵に影を落とすと本物らしくなります。3Dなら平面を曲げる変形で作れます。12〜20コマ。"],["使いどころ","絵本、日記、アルバム、昔話の始まり。安い編集ソフトの印象もあるので、本や紙の話の時だけ使います。"],["例","なし"]]},{"g":"動きでつなぐ","n":"ウィップパン","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","カメラを速く横にふった「ぶれ」の中で切り、別の場所や時間へとびます。同じ場面の中で人から人へふる使い方もあります。前後でふる向きと速さをそろえるのがこつです。"],["例","『ラ・ラ・ランド』（2016）店の中で、演奏する人と踊る人の間を速くふる [知識]"]]},{"g":"動きでつなぐ","n":"ズーム","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","物（目、画面、看板、窓）に急に寄って、その中から次の場面が始まります。映画より、旅の動画やSNSの短い動画で多い型です。前を「寄る」で終えたら、後ろも「寄る」で始めます。"],["例","なし"]]},{"g":"動きでつなぐ","n":"スピン","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","画面を回しながら次へ移ります。昔のテレビ番組では、回る絵や回る新聞の見出しで場面を変えました。今は勢いや笑いを出したい時に使います。"],["例","1960年代のテレビ版『バットマン』の、回る印をはさむ場面転換 [知識]"]]},{"g":"動きでつなぐ","n":"物が横切るワイプ（Wipe-by cut / Natural wipe）","b":[["見え方","人・車・柱がカメラの前を横切り、通りすぎると場面や構図が変わっています。"],["作り方","前の絵で、横切る物が画面をほぼおおった1〜2コマで切り、次の絵も同じ向きに何かが横切り終わる所から始めます。コードなら、横切る物のふちを境目にしたワイプ（動くぬき型）を作ります。"],["使いどころ","人ごみ、街、電車。効果を足した感じがなく、自然に時間や場所をとばせます。"],["例","『ジョーズ』（1975）浜辺で、人が前を横切るたびに署長の顔へ寄っていく [確認]"]]},{"g":"動きでつなぐ","n":"体で隠す（Body wipe / Block the lens）","b":[["見え方","人物がカメラに向かって歩いてきて（または背中が近づいて）画面が真っ黒になり、次の場面は黒から離れていく絵で始まります。"],["作り方","前のカットを、体や手でレンズがふさがって黒くなった所で切り、次のカットを、別の物がレンズから離れる所から始めます。黒の長さは2〜4コマ。"],["使いどころ","見えないカット、場所の瞬間移動、服や時間が変わるしかけ。"],["例","『ロープ』（1948）背中で画面を暗くしてつなぐ [知識]"]]},{"g":"動きでつなぐ","n":"マスクでつなぐ（シームレス）（Masking transition）","b":[["見え方","画面の中を動く物（柱、人、ドアのふち）を境目にして、その後ろから次の場面が現れます。"],["作り方","物の輪郭を1コマずつ切りぬき（ぬき型を作り）、その物が通った所から順に次の絵に入れかえます。物が画面の端から端まで動く8〜20コマで行います。コードなら、コマごとの白黒のぬき型を用意し、白い所をB、黒い所をAにします。"],["使いどころ","旅の動画、商品の紹介、場所を次々に変える。手間がかかるので、1本に数回まで。"],["例","なし（旅の短い動画の定番）"]]},{"g":"動きでつなぐ","n":"ピンぼけでつなぐ（Focus pull transition / Blur transition）","b":[["見え方","絵がぼけていき、ぼけた色のかたまりから次の絵がはっきりしてきます。"],["作り方","Aのぼかしを0から30〜50ピクセルまで8〜12コマで上げ、一番ぼけた所で切り（または短く重ね）、Bを同じ強さのぼけから0へもどします。前後で色や明るさが近いと、より自然です。"],["使いどころ","目覚め、気を失う、夢、時間のやさしい経過。"],["例","なし"]]},{"g":"動きでつなぐ","n":"通り抜ける（ドア・窓・鍵穴・画面の中へ）（Pass-through transition）※追加","b":[["見え方","カメラが窓ガラスや壁、鍵穴、テレビの画面を通り抜けて、向こう側の場面に入ります。"],["作り方","カメラを物に向かって進め、一番近づいた（画面が物でうまった）所で、向こう側から始まる絵につなぎます。3Dなら、カメラを実際に壁の向こうへ通し、壁をカメラが近づいた時だけ消します。"],["使いどころ","のぞき見、家の中の位置関係を見せる、映像の中の世界へ入る。"],["例","『市民ケーン』（1941）看板と屋根の窓を抜けて店の中へ／『パニック・ルーム』（2002）取っ手や壁を抜けるカメラ [知識]"]]},{"g":"光と質感でつなぐ","n":"白とばし","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","画面が真っ白になってから次へ移ります。黒へのフェードが「終わり・眠り」なら、白は「光・夢・記憶・死後・目がくらむ」です。爆発や強い光をきっかけにすると理由が付きます。"],["例","なし"]]},{"g":"光と質感でつなぐ","n":"黒落ち（Cut to black）","b":[["見え方","フェードではなく、いきなり画面が真っ黒になります。"],["作り方","1コマで黒に切ります。音も同じコマで切る（完全な無音）と一番強く、音だけ残すと余韻になります。黒は1〜3秒そのまま置きます。"],["使いどころ","衝撃的な終わり、気を失う、撃たれた瞬間、答えを見せない結末。"],["例","テレビドラマ『ザ・ソプラノズ』最終回（2007）の突然の黒 [知識]"]]},{"g":"光と質感でつなぐ","n":"フラッシュ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","カメラのフラッシュ、雷、銃の火など、場面の中の光をきっかけに2〜4コマ白く光らせて切り替えます。記憶が一瞬よみがえる場面や、写真を撮る場面でよく使います。くり返しの点滅は1秒に3回までにします。"],["例","なし"]]},{"g":"光と質感でつなぐ","n":"光もれ（Light leak）","b":[["見え方","橙や赤のやわらかい光が画面の端から広がり、その間に絵が入れかわります。"],["作り方","橙〜赤〜黄のぼけた光の動画（またはぼかしたグラデーションを動かしたもの）を、「スクリーン（明るい所だけ足す重ね方）」で重ねます。光が一番強くなるコマに切れ目を置きます。全体で12〜24コマ。"],["使いどころ","思い出、夏、旅、結婚式の動画。フィルムのカメラに光が入った失敗が元なので、なつかしい味になります。"],["例","なし"]]},{"g":"光と質感でつなぐ","n":"フィルムバーン（Film burn）","b":[["見え方","フィルムが焼けたように、橙と白のむらが画面をおおい、次の絵に変わります。"],["作り方","光もれより強く、画面全体が白くとぶまで重ねます。むらは形が不規則に動くものを使い、ふちは赤く、中は白く。白くなりきった2〜3コマで切ります。全体で8〜16コマ。"],["使いどころ","古い映画の味、荒い音楽ビデオ、物語がこわれる瞬間。"],["例","『仮面／ペルソナ』（1966）映画の途中でフィルムが焼け切れる絵 [知識]"]]},{"g":"光と質感でつなぐ","n":"ルマワイプ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","絵の明るい所（または暗い所）から先に次の絵へ入れかわります。雲、煙、水、炎の形にそって変わるので、普通のディゾルブより「物の形を通って変わった」感じが出ます。タイトルや夢の入口に使います。"],["例","なし"]]},{"g":"光と質感でつなぐ","n":"インクにじみ（Ink bleed / Ink transition）","b":[["見え方","水に落としたインクが広がるように、にじむ形で次の絵が現れます。"],["作り方","インクが広がる白黒の動画（本物を撮るか、動くノイズ模様をしきい値で白黒に分けて広げる）をぬき型にして、白い所から次の絵を出します。ふちを少しぼかし、にじみが広がりきるまで24〜48コマ。"],["使いどころ","和風、水彩、手紙や書の話、やわらかい場面の始まり。"],["例","なし"]]},{"g":"光と質感でつなぐ","n":"筆のマスク（Brush stroke mask）","b":[["見え方","筆でぬったあとが画面を走り、ぬられた所から次の絵が見えてきます。"],["作り方","筆のあとの形の白黒の絵を用意し、左から右へ順に現れるように動かして、ぬき型にします。3〜5筆で画面をうめると手描きらしくなります。1筆6〜10コマ。"],["使いどころ","絵・美術・手作りの話、タイトル、写真を次々に見せる動画。"],["例","なし"]]},{"g":"デジタル","n":"グリッチ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","通信がみだれる、機械がこわれる、仮想の世界がゆらぐ、記憶が書きかわる、という場面の変わり目に使います。物語の中に理由（画面、通信、機械の目）があると自然です。4〜10コマと短く。"],["例","なし"]]},{"g":"デジタル","n":"モザイク","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","四角をだんだん大きくして絵を読めなくし、次の絵でだんだん細かくもどします。ゲームの画面、昔のテレビ、防犯カメラなど、デジタルの世界の話に合います。"],["例","なし"]]},{"g":"デジタル","n":"モーフ（Morph）","b":[["見え方","顔や物の形が、なめらかに別の顔や物へ変わっていきます。"],["作り方","2つの絵の対応する点（目と目、口と口、輪郭）を結び、①Aの形をBの形へ少しずつゆがめる ②同時に色をディゾルブで混ぜる、の2つを一緒に進めます。12〜48コマ。対応する点が多いほどきれいです。背景は同じか単純なほうが破たんしません。"],["使いどころ","変身、年を取る、人から人へ。マッチディゾルブをより本当らしくしたものです。"],["例","『ウィロー』（1988）動物が次々に変わる魔法（最初期の例）／『ターミネーター2』（1991）液体金属の変身 [知識]"]]},{"g":"デジタル","n":"データモッシュ（Datamosh）","b":[["見え方","前の絵の色のまま、次の絵の「動き」だけが伝わって、絵がどろどろに流れます。"],["作り方","動画の圧縮は「全部の絵を持つコマ」と「前のコマからの動きだけを持つコマ」でできています。切れ目にある「全部の絵を持つコマ」を取りのぞくと、次の場面の動きが前の絵の上にかかります。動きだけのコマをくり返すと、絵が同じ方向にのび続けます。専用の道具や、動画ファイルを直接いじるスクリプトで作ります。"],["使いどころ","音楽ビデオ、夢、こわれた記憶、ネットの美学。再現が安定しにくく、見づらいので短く使います。"],["例","カニエ・ウェスト「Welcome to Heartbreak」（2009）の音楽ビデオ [知識]"]]},{"g":"デジタル","n":"形ワイプ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","星・ハート・ロゴなどの形が広がって（すぼまって）次へ移ります。子ども向け番組、コメディ、スポーツ中継のロゴの転換でよく使います。まじめな場面には合いません。"],["例","1960年代のテレビ版『バットマン』の、印の形をはさむ転換 [知識]"]]},{"g":"音でつなぐ","n":"音の橋わたし（Sound bridge）","b":[["見え方","絵が変わる前に次の場面の音が聞こえ始める（または前の音が次の絵にまたがって続く）。"],["作り方","編集のJカット・Lカットを、場面と場面の間で行います。次の音を12〜48コマ（0.5〜2秒）早く入れ、音量は小さい所から上げていきます。前後の場面に共通する音（音楽、語り）を1本通す方法もあります。"],["使いどころ","ほぼすべての場面の変わり目。絵はただのカットでも、音がつながっていればなめらかに感じます。"],["例","『地獄の黙示録』（1979）冒頭、ヘリコプターの音と天井の扇風機が重なる [知識]"]]},{"g":"音でつなぐ","n":"音のマッチ（Match on sound / Sound match cut）","b":[["見え方","前の場面の音が、似た別の音に変わって次の場面が始まります。"],["作り方","高さ・長さ・リズムの似た音どうし（悲鳴と汽笛、拍手と雨、ドアを閉める音と銃声）を、切れ目のコマでつなぎます。短く重ねて（2〜6コマ）入れかえると自然です。"],["使いどころ","意外なつながり、笑い、こわい場面からの解放。絵のマッチカットと一緒に使うと一番強いです。"],["例","『三十九夜』（1935）悲鳴がそのまま汽車の汽笛に変わる [知識]"]]},{"g":"音でつなぐ","n":"フーッという風切り音（Whoosh）","b":[["見え方","速い転換や動きに「シュッ」「フーッ」という音が付き、勢いが出ます。"],["作り方","0.3〜0.6秒の風切り音を、音の山が切れ目のコマに来るように置きます。右へふる転換なら、音も左から右へ動かします。作るなら、雑音（ノイズ）の音量を山なりに上げ下げし、こもり具合を同時に動かします。"],["使いどころ","ウィップパン、ズーム、文字の登場、SNSの短い動画。全部の転換に付けるとうるさく、安く聞こえます。"],["例","なし"]]},{"g":"そのほか（追加）","n":"字幕カード（「3年後」など）（Title card / Intertitle）※追加","b":[["見え方","黒い画面や絵の上に、時間や場所を示す短い文字が出ます。"],["作り方","黒地に文字だけを2〜3秒、または次の場面の絵の上に文字を重ねます。文字は「読む時間×1.5」見せます。出し方はカットかフェード。"],["使いどころ","時間や場所が大きくとんだ時、章立て。一番確実で誤解のない場面転換です。"],["例","『シャイニング』（1980）曜日や時刻だけを出す黒い画面 [知識]"]]},{"g":"そのほか（追加）","n":"時間の経過を1つの絵で見せる（季節の移り・早回し）（Time-passage transition）※追加","b":[["見え方","同じ場所の絵のまま、光・天気・季節・人の流れだけが速く変わります。"],["作り方","カメラを固定して長時間を早回しにする（タイムラプス）か、同じ構図で別々の時に撮った絵をディゾルブでつなぎます。3Dなら太陽の位置や木の色を数秒で動かします。"],["使いどころ","待つ、月日が流れる、街の1日。人物が歩く間に季節だけ変える見せ方もあります。"],["例","『ノッティングヒルの恋人』（1999）市場を歩く間に季節が移っていく [知識]"]]}],"10":[{"g":"だまし絵","n":"強制遠近法（Forced perspective）","b":[["見え方","近くの人が巨人に、遠くの人が小人に見えます。合成なしで1枚に収まります。"],["作り方","現場では2人を前後に離して立たせ、目線と小道具（机など）を1本につながるように作ります。ピントが両方に合うよう絞りを絞ります（F値を大きく）。このMacでは、Blenderで同じ人形を2体置き、片方をカメラから3倍遠くへ。カメラの被写界深度を切り、床の線を隠す構図にすれば1/3の大きさに見えます。"],["使いどころ","大きさの差を笑い・おとぎ話に。カメラを横に動かすと視差（近い物ほど速く動くずれ）でばれます。"],["例","『ロード・オブ・ザ・リング 旅の仲間』（2001）袋小路屋敷でガンダルフとフロドが同じ机につく場面 [知識]"]]},{"g":"だまし絵","n":"ミニチュア（Miniature）","b":[["見え方","街・船・建物を本物の大きさに見せます。壊す・燃やす・沈めるができます。"],["作り方","現場では縮めた模型を作り、低い位置から広角で撮ります。このMacでは、Blenderで小さな箱の街を作り、カメラを地面すれすれに置き、遠くほど白くかすむ霧（ワールドの Mist パス）を足します。逆に実景を模型に見せたい時は、ffmpeg で上下をぼかし色を濃くすれば「ミニチュア風」になります。"],["使いどころ","壊れる物・二度と作れない景色。水・火・煙は粒の大きさが縮まらないので、小さすぎる模型はばれます。"],["例","『ゴジラ』（1954）銀座の街並みを壊す場面 [知識]／『ブレードランナー』（1982）冒頭の工業地帯 [知識]"]]},{"g":"だまし絵","n":"ビガチュア（Bigature）","b":[["見え方","「大きなミニチュア」。人の背より高い模型なので、寄っても細部がもちます。"],["作り方","現場では数メートル級の模型を作り、カメラを機械で正確に動かして撮ります。このMacでは、Blenderの模型に細かい凹凸（ベベル、汚れのテクスチャ）を足し、カメラを近づけても粗が出ないかを確かめる、という考え方を真似ます。"],["使いどころ","城・都市の全景をなめるように見せたい時。作る手間と場所が大きいのが限界です。"],["例","『ロード・オブ・ザ・リング 王の帰還』（2003）ミナス・ティリスの全景 [知識]"]]},{"g":"だまし絵","n":"ガラス絵（マットペインティング／Matte painting）","b":[["見え方","セットの上や奥に、絵で描いた城・空・山が続いて見えます。"],["作り方","昔はカメラの前にガラスを立て、写したい所だけ透明に残して残りを絵で描きました。このMacでは、Pillow で写真の上半分を透明にし、描いた絵（または別の写真）を下に敷いて Image.alpha_composite で重ねます。境目は建物の縁など線のある所に置きます。"],["使いどころ","広い世界を安く見せる引きの絵。絵は動かないので、長く映すと止まって見えます（煙や鳥を足します）。"],["例","『レイダース 失われたアーク《聖櫃》』（1981）最後の巨大な倉庫 [知識]"]]},{"g":"だまし絵","n":"シュフタン法（Schüfftan process）","b":[["見え方","模型の街の中に、本物の人が小さく歩いて見えます。"],["作り方","カメラの前に鏡を45度に置き、鏡の銀を一部だけ削って透明にします。透明な所から奥の役者、鏡の所に横の模型が映り、1回の撮影で合わさります。このMacでは、Blenderで平面に鏡のマテリアル（Glossy、粗さ0）を付け、一部を透明にするマスクを貼れば同じ仕組みを再現できます。"],["使いどころ","合成の道具が無い時代の方法。今は仕組みを知るための教材として。"],["例","『メトロポリス』（1927）巨大な競技場や街の場面 [知識]"]]},{"g":"だまし絵","n":"吊りミニチュア（Hanging miniature）","b":[["見え方","実物大のセットの上に、天井や高い階が続いて見えます。"],["作り方","カメラのすぐ前に小さな模型を吊り、奥の実物セットの上の端とぴったり重ねます。このMacでは、Blenderでカメラの前30cmに小さな屋根、奥10mに壁を置き、線が1本につながる位置を数字で合わせます（強制遠近法と同じ計算）。"],["使いどころ","セットは下半分だけ建てて予算を減らす時。カメラは固定が基本です。"],["例","『ベン・ハー』（1925）戦車競走の競技場の上段 [知識]"]]},{"g":"だまし絵","n":"ペッパーズ・ゴースト（Pepper's ghost）","b":[["見え方","半透明の幽霊が、その場に浮いて見えます。"],["作り方","客と舞台の間に斜めのガラスを置き、客から見えない所にいる役者を明るく照らすと、ガラスに映って重なります。このMacでは、ffmpeg で黒背景の人物動画を blend=all_mode=screen（明るい所だけ足す重ね方）で背景に重ねると同じ見え方になります。"],["使いどころ","幽霊、ホログラム風の演出。明かりを落とすと消える、という出し入れが得意です。"],["例","ディズニーランド「ホーンテッドマンション」（1969）の舞踏会の広間（映画ではなくアトラクション）[知識]"]]},{"g":"映写と背景","n":"リアプロジェクション（Rear projection／スクリーン・プロセス）","b":[["見え方","車の窓の外に景色が流れます。少し色が浅く、平たく見えるのが昔の映画の味です。"],["作り方","役者の後ろに半透明の幕を張り、裏から景色の映像を映して一緒に撮ります。このMacでは、Blenderで人物の後ろに平面を置き、動画テクスチャを Emission（自分で光る設定）で貼ります。ffmpeg だけなら、人物を切り抜いて流れる背景に overlay で重ねます。"],["使いどころ","車内の会話。背景と人物の光の向きが合わないと嘘っぽくなりますが、その嘘っぽさをわざと使う作品もあります。"],["例","『北北西に進路を取れ』（1959）酔わされて車を走らせる場面 [知識]"]]},{"g":"映写と背景","n":"フロントプロジェクション（Front projection）","b":[["見え方","リアより明るくくっきりした背景になります。"],["作り方","カメラの前に斜めの半透明鏡を置き、カメラと同じ向きから映像を投げます。背景は光を来た方向へ強く返す幕（道路標識と同じ材料）なので背景だけ明るく映り、役者の体に当たった分は弱くて見えません。このMacでは仕組みの再現より、上のリアプロジェクションと同じ「背景に動画を貼る」方法が一番近い代わりになります。"],["使いどころ","広い屋外をスタジオで。カメラと映写機の軸がずれると人物のふちに影が出ます。"],["例","『2001年宇宙の旅』（1968）冒頭の猿人たちの荒野 [知識]"]]},{"g":"映写と背景","n":"LEDの壁（バーチャルプロダクション／Virtual production）","b":[["見え方","背景が本当にそこにあるように、役者や金属に景色の光と映り込みが乗ります。"],["作り方","現場では巨大なLEDの壁にゲームエンジンの3D背景を映し、カメラの位置に合わせて背景の見え方を毎コマ変えます。このMacでは、Blenderで人物の周りに曲がった板を置いて景色を Emission で貼り、その光だけで人物を照らすと「壁の光で照らされる」感じを試せます。実物でやるなら、大きなテレビの前に小物を置いてスマホで撮るのが一番近い方法です。"],["使いどころ","夕方の光を一日中保ちたい時、映り込みの多い衣装。壁より広い引きの絵は苦手です。"],["例","『マンダロリアン』（2019）の多くの屋外場面 [知識]"]]},{"g":"カメラの中で","n":"多重露光（Multiple exposure）","b":[["見え方","2つの絵が半透明で重なります。幽霊、思い出、夢。"],["作り方","昔は同じフィルムを巻き戻して2回撮りました。このMacでは、ffmpeg blend=all_mode=screen（明るい所が勝つ）か all_mode=average（半分ずつ）で2本を重ねます。numpy なら np.maximum(a, b)。"],["使いどころ","心の中と現実を同時に見せたい時。両方が明るいと白く飛ぶので、片方は黒背景に。"],["例","『霊魂の不滅』（1921）半透明の馬車と死者 [知識]"]]},{"g":"カメラの中で","n":"置き換えトリック（Substitution splice／メリエスの止め撮り）","b":[["見え方","人や物が一瞬で消える・別の物に変わります。"],["作り方","カメラを固定して撮影を止め、物を入れ替えて、また回します。このMacでは、三脚で撮った2本を ffmpeg concat で直結するだけです。つなぎ目に煙や光を1〜2コマ足すとごまかせます。"],["使いどころ","変身、瞬間移動、手品。止めている間に背景が動くとばれます。"],["例","ジョルジュ・メリエス『ロベール＝ウーダン劇場における婦人の雲隠れ』（1896）[知識]"]]},{"g":"カメラの中で","n":"逆回し撮影（Reverse motion）","b":[["見え方","割れた物が元に戻る、物が手に飛び込む、といった不思議な動きになります。"],["作り方","終わりの形から逆に演じて撮り、逆に再生します。このMacでは ffmpeg -vf reverse（音は areverse）。長い動画は全部をメモリに読むので、短く切ってから使います。"],["使いどころ","魔法、危ない動作を安全に（当たる寸前から離れる動きを撮る）。煙・水・髪の動きが逆になるのでばれやすいです。"],["例","『オルフェ』（1950）手袋がひとりでに手にはまる場面 [知識]／『TENET テネット』（2020）[知識]"]]},{"g":"カメラの中で","n":"スリットスキャン（Slit-scan）","b":[["見え方","光の壁が奥から手前へ流れ続けるトンネル、または動く物がゴムのように伸びた絵になります。"],["作り方","昔は細いすき間越しに、シャッターを開けたままカメラと絵を動かして1コマずつ撮りました。このMacでは numpy で「出来上がりの x 列目は、元動画の (t + x×k) コマ目の x 列目」と並べ直します（k を大きくすると伸びが強い）。"],["使いどころ","別世界への移動、時間がゆがむ感じ。数秒で十分です。"],["例","『2001年宇宙の旅』（1968）終盤の光のトンネル [知識]"]]},{"g":"カメラの中で","n":"回転セット（Rotating set）","b":[["見え方","人が壁や天井を歩く、重力が回る廊下。"],["作り方","部屋ごと大きな輪の中で回し、カメラを部屋に固定します。役者は常に「下」にいるだけです。このMacでは、Blenderで部屋とカメラを同じ親（空のオブジェクト）に付けて回し、重力（剛体の世界設定）は動かさずに小物を転がします。"],["使いどころ","夢、無重力、酔い。回す速さは役者が歩ける程度に。"],["例","『恋愛準決勝戦』（1951）壁と天井で踊る場面 [知識]／『インセプション』（2010）回る廊下の格闘 [知識]"]]},{"g":"カメラの中で","n":"雲のタンク（Cloud tank）","b":[["見え方","もくもくと湧く、重くて立体的な雲。"],["作り方","水槽の下に塩水、上に真水を入れ、境目に白い絵の具を注ぐと、雲のように広がって止まります。高速度で撮ります。このMacでは、Blenderの煙（Mantaflow の Gas）を温度差を弱くしてゆっくり広げ、下から光を当てます。実物なら、コップの水に牛乳を垂らしてスマホのスローで撮り、ffmpeg で上下を返す（vflip）のが近い代わりです。"],["使いどころ","不穏な空、神や宇宙船が来る前ぶれ。"],["例","『未知との遭遇』（1977）宇宙船を隠す雲 [知識]"]]},{"g":"カメラの中で","n":"水の中に見せる（ドライ・フォー・ウェット／Dry for wet）","b":[["見え方","水に入っていないのに、水中に見えます。"],["作り方","スタジオに煙を満たし、青緑の光、スロー撮影、扇風機で髪と布をゆらし、役者を吊ります。泡と水面の光のゆらぎは後で足します。このMacでは、Blenderでワールドに青緑の霧（Volume Scatter）を入れ、動きを半分の速さにし、白い小さな粒を浮かせます。ffmpeg なら青緑寄りの色（colorbalance）＋ゆっくり（setpts=2*PTS）＋ゆらぎ（displace）。"],["使いどころ","長い水中の芝居、台詞のある水中。息の泡が無いとばれます。"],["例","『レッド・オクトーバーを追え！』（1990）潜水艦の場面 [知識]／『シェイプ・オブ・ウォーター』（2017）冒頭の水に沈んだ部屋 [知識]"]]},{"g":"物と体","n":"特殊メイク（Prosthetic makeup）","b":[["見え方","顔や体そのものが別の生き物・年齢・傷になります。"],["作り方","役者の顔の型を取り、やわらかい素材（シリコンなど）の部品を貼って色を塗ります。このMacでは、Blenderの顔の模型をスカルプト（粘土のように盛る機能）で変形し、シェイプキーで元の顔から変身後へ動かせます。実写の顔に貼るのは顔の追跡が要るので、技法11「顔の差し替え」の代わりの方法を使います。"],["使いどころ","変身を1カットで見せたい時、役者の芝居を残したい怪物。"],["例","『狼男アメリカン』（1981）明るい部屋での変身場面 [知識]"]]},{"g":"物と体","n":"アニマトロニクス（Animatronics）","b":[["見え方","機械仕掛けの生き物が、その場で息をし、濡れ、役者に触れます。"],["作り方","骨組みにモーターや油圧を入れ、皮をかぶせ、数人が遠隔で動かします。このMacでは、Blenderで骨（アーマチュア）を入れた模型を動かし、動きの山と谷に少しの遅れと揺れ戻しを足すと「重い機械の生き物」らしくなります。"],["使いどころ","寄りの絵、役者と触れ合う場面。走る・跳ぶなど大きな動きは苦手で、そこはCGと分けます。"],["例","『ジュラシック・パーク』（1993）雨の夜にT-レックスが柵を破る場面 [知識]"]]},{"g":"物と体","n":"操り人形（Puppetry）","b":[["見え方","手や棒や糸で動かす人形。目と首の小さな動きで生きて見えます。"],["作り方","人形の下や後ろに人が隠れ、手を入れる・棒で動かす・糸で吊るのいずれかで演じます。このMacでは、Blenderで骨を数本だけにした人形を作り、口の開閉と首のかしげだけをキーフレームで付けます（少ない関節のほうが人形らしい）。"],["使いどころ","小さな生き物、賢者、子ども向け。足元を映さない構図が基本です。"],["例","『スター・ウォーズ 帝国の逆襲』（1980）沼の星のヨーダ [知識]／『ダーククリスタル』（1982）[知識]"]]},{"g":"物と体","n":"着ぐるみ（Suit acting）","b":[["見え方","人が入った怪獣。重さと人間くささが出ます。"],["作り方","役者が着ぐるみを着て、ミニチュアの街で演じます。速く撮って遅く流すと巨大に見えます。このMacでは、Blenderで人の歩きに怪獣の模型をかぶせ、再生を半分の速さにして低い位置から見上げます。"],["使いどころ","怪獣、ヒーロー。足が人の形になるのが弱点で、足元を隠すか、煙を焚きます。"],["例","『ゴジラ』（1954）[知識]"]]},{"g":"物と体","n":"ワイヤーアクション（Wire work／Wire-fu）","b":[["見え方","人が飛ぶ、壁を走る、吹き飛ぶ。"],["作り方","役者に細い綱を付け、滑車と人力で引きます。綱は後で消します（技法11「ワイヤー消し」）。このMacでは、Blenderで人物の腰の高さのカーブ（Fカーブ）を、本物の放物線より頂点で長く止まる形にすると「吊られた浮き」になります。"],["使いどころ","武侠もの、超人。浮きすぎると重さが消えるので、着地でしっかり沈ませます。"],["例","『グリーン・デスティニー』（2000）竹林の上の戦い [知識]"]]},{"g":"物と体","n":"火薬（Pyrotechnics）","b":[["見え方","本物の爆発、火花、炎。周りの人と物を本当に照らします。"],["作り方","専門の資格を持つ人が火薬と燃料を仕掛けます（自分では絶対にやらない）。このMacでは、Blenderの Mantaflow で火と煙（Fire + Smoke）を作り、爆発の1〜2コマ目だけ周りを強く照らす点光源を足します。"],["使いどころ","見せ場。爆発そのものより、光に照らされた顔と、遅れて来る破片・煙が効きます。"],["例","『ダークナイト』（2008）病院の爆破 [知識]"]]},{"g":"物と体","n":"血のり（スクイブ／Squib）","b":[["見え方","撃たれた所から服が裂け、血が弾けます。"],["作り方","服の下に、血のりの袋と小さな火薬を板で体を守って仕込み、合図で破裂させます。今は空気圧式もあります。このMacでは、Blenderの粒子（Particle）で赤い粒を一瞬だけ前へ出し、ffmpeg で服の位置に overlay します。同じコマに煙の白と体のびくつきを合わせます。"],["使いどころ","撃たれた痛み。多すぎると漫画になります。"],["例","『俺たちに明日はない』（1967）最後の銃撃 [知識]"]]},{"g":"物と体","n":"割れるガラス（Breakaway glass）","b":[["見え方","人が窓を突き破り、瓶で頭を殴ります。"],["作り方","昔は砂糖を煮固めた板、今は割れても切れにくい樹脂で作ります。このMacでは、Blenderの Cell Fracture（物をかけらに割るアドオン）で板を割り、剛体（Rigid Body）で飛び散らせます。"],["使いどころ","格闘、突入。音（高い砕ける音）が半分を担います。"],["例","なし（確かな場面を確かめていません）"]]},{"g":"物と体","n":"雨・風・煙の機械（Rain / Wind / Fog machines）","b":[["見え方","天気と空気が画面に写ります。光の筋、濡れた地面、なびく髪。"],["作り方","雨は高い所から水をまき、後ろから光を当てて粒を光らせます。風は大きな扇風機、煙はスモークマシン。このMacでは、Blenderで粒子の雨＋ワールドの霧（Volume）＋逆光、または numpy で白い短い斜線を毎コマ乱数で描いて screen で重ねます。"],["使いどころ","別れ、決闘、不安。雨は逆光でないとほぼ見えません。"],["例","『羅生門』（1950）門に降る強い雨（写るように水に墨を混ぜた話が有名）[知識]／『七人の侍』（1954）雨の中の決戦 [知識]"]]},{"g":"物と体","n":"操演（そうえん）","b":[["見え方","飛行機、怪獣の首やしっぽ、倒れる建物が、糸や仕掛けで動きます。日本の特撮の言葉です。"],["作り方","細いピアノ線で模型を吊り、上の足場から数人で動かします。火薬や倒す仕掛けの合図も操演の仕事です。このMacでは、Blenderで模型を空のオブジェクトにぶら下げ、進む動きに少しの揺れ（Noise モディファイア）を足すと「吊られた模型」らしくなります。"],["使いどころ","飛ぶ物、3本首など人が入れない部分。糸が光らないよう黒く塗り、照明を外します。"],["例","『三大怪獣 地球最大の決戦』（1964）キングギドラの首と翼 [知識]"]]},{"g":"コマ撮り","n":"ストップモーション（Stop motion）","b":[["見え方","人形や物が、少しカクカクしながら自分で動きます。"],["作り方","1コマ撮っては人形を少し動かす、をくり返します（1秒に12〜24枚）。このMacでは、スマホを固定して連写した写真を ffmpeg -framerate 12 -i %04d.jpg で動画にします。Blenderなら、補間を「一定（Constant）」にして2コマごとに動かすとコマ撮りの見え方になります。"],["使いどころ","手作りの温かさ、少し不気味な生き物。動きにぶれ（モーションブラー）が無いのがカクカクの原因です。"],["例","『キング・コング』（1933）[知識]／『アルゴ探検隊の大冒険』（1963）骸骨の剣士との戦い [知識]"]]},{"g":"コマ撮り","n":"クレイ（Claymation／粘土アニメ）","b":[["見え方","粘土の人形が、形そのものを変えながら動きます。指のあとが残ります。"],["作り方","針金の骨に粘土を付け、1コマごとに形を直します。口は取り替え式の部品も使います。このMacでは、Blenderのシェイプキーで形を変え、表面に指紋のような凹凸テクスチャを貼り、12コマ/秒で書き出します。"],["使いどころ","やわらかい笑い、変身。熱と手あかで粘土が汚れるので短い話向きです。"],["例","『ウォレスとグルミット ペンギンに気をつけろ！』（1993）模型列車の追いかけ [知識]"]]},{"g":"コマ撮り","n":"ゴーモーション（Go motion）","b":[["見え方","コマ撮りなのに、動きにぶれがあってなめらかです。"],["作り方","人形を棒と機械につなぎ、シャッターが開いている間に機械が少しだけ動かします。このMacでは、コマ撮りの写真を ffmpeg tmix=frames=3（前後のコマを混ぜる）で少しぶらすか、Blenderでモーションブラーを入れて書き出します。"],["使いどころ","コマ撮りの生き物を実写になじませたい時。味を消すので、手作り感を見せたい作品には使いません。"],["例","『ドラゴンスレイヤー』（1981）竜 [知識]"]]},{"g":"足した技法（地図に無かったもの）","n":"モーションコントロール（Motion control）","b":[["見え方","模型の宇宙船がなめらかに飛び、背景・光・煙が別々に撮ったのにぴったり重なります。"],["作り方","コンピューターで動かす台にカメラを載せ、同じ動きを何度でも正確にくり返して、素材を別々に撮ります。このMacでは、Blenderのカメラの動きは毎回同じなので、同じカメラで「模型だけ」「光だけ」「煙だけ」と分けて書き出せば同じことになります。"],["使いどころ","模型の合成、1人2役でカメラを動かしたい時。"],["例","『スター・ウォーズ』（1977）宇宙の戦闘 [知識]"]]},{"g":"足した技法（地図に無かったもの）","n":"ミニチュアの高速度撮影（Overcranking for scale）","b":[["見え方","小さな模型の爆発や波が、巨大でゆっくり重く見えます。"],["作り方","模型が実物の 1/N なら、およそ √N 倍のコマ数で撮って普通の速さで流します（1/16 なら4倍＝96コマ/秒）。このMacでは、Blenderの物理を作ってから、シーンの時間の伸び（Time Remapping）を √N 倍にします。"],["使いどころ","模型・着ぐるみすべて。これを忘れると、どんな精密な模型もおもちゃに見えます。"],["例","『インデペンデンス・デイ』（1996）ホワイトハウスの爆破（模型）[知識]"]]},{"g":"足した技法（地図に無かったもの）","n":"ピクシレーション（Pixilation）","b":[["見え方","本物の人間がコマ撮りの人形のように動き、座ったまま地面を滑ります。"],["作り方","人にポーズを取ってもらい、1コマずつ撮ります。このMacでは、スマホの連写を ffmpeg で 8〜12コマ/秒の動画にします。"],["使いどころ","ミュージックビデオ、ショート動画。少人数・無料でできる特撮の入口です。"],["例","ノーマン・マクラレン『隣人』（1952）[知識]"]]}],"11":[{"g":"合成の基本","n":"グリーンバック（キー抜き／Chroma key）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","緑の幕の前で撮り、緑だけ透明にして背景を入れます。髪の毛・煙・ガラスなど半透明の所と、肌に映る緑の色かぶり（スピル）を取る作業に時間の大半を使います。背景の光の向きを先に決めてから人物を照らすのがコツです。"]]},{"g":"合成の基本","n":"ロトスコープ（Rotoscoping／手で切り抜き）","b":[["見え方","緑の幕が無い映像でも、人物だけをきれいに切り出せます（結果は見えないのが成功）。"],["作り方","現場では1コマずつ人物の輪郭を曲線で囲み、数コマおきに形を直します。このMacでは、Blenderの Movie Clip Editor のマスク機能で輪郭を描いてキーフレームを打ちます。自動で近い結果がほしい時は、無料の rembg（Python の背景切り抜きAI）を1コマずつかけ、Pillow で境目を1〜2ピクセルぼかします。"],["使いどころ","緑の幕を使えなかった場面、物の後ろに文字やCGを入れたい時。髪と速い動きが難所です。"],["例","『スター・ウォーズ』（1977）光る剣の光を1コマずつ描き足した作業 [知識]"]]},{"g":"合成の基本","n":"マスク（Mask／Matte）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","「ここだけ見せる／ここだけ直す」範囲を白黒の絵で決めます。いらない所を大ざっぱに囲んで捨てる「ガベージマスク」と、細かく切る本番のマスクを分けると楽です。色直しを顔だけにかける時にも使います。"]]},{"g":"合成の基本","n":"合成モード（Blend mode）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","火・光・火花は「加算／スクリーン」（明るい所だけ足す）、影や汚れは「乗算」（暗くする）、普通の重ねは「通常（アルファ）」。光る物を通常で重ねると黒い縁が出るので、必ず足し算系にします。"]]},{"g":"合成の基本","n":"レンダーパス（Render passes／AOV）","b":[["見え方","見た目は1枚ですが、裏では「色」「つや」「影」「奥行き」などに分かれていて、撮り直さずに後で調整できます。"],["作り方","CGを書き出す時に成分ごとの絵を別々に保存し、合成で足し直します。このMacでは、Blenderの View Layer の設定で Diffuse・Glossy・Shadow・Z（奥行き）・Cryptomatte（物ごとの切り抜き）にチェックを入れ、OpenEXR マルチレイヤーで保存し、コンポジターで組み直します。"],["使いどころ","つやだけ弱めたい、影だけ濃くしたい、奥だけぼかしたい時。パスを増やすほどファイルが重くなります。"],["例","なし（裏方の技術で、特定の場面としては挙げにくい）"]]},{"g":"合成の基本","n":"ディープ合成（Deep compositing）","b":[["見え方","煙の中にキャラが半分埋まる、葉の間を通る、といった重なりが、切り抜きなしで正しく合います。"],["作り方","1つの点に「奥行きごとの色と濃さ」を何層も持たせた画像（ディープEXR）を使います。このMacでは、Blenderはこの形式を書き出せない [知識] ので、代わりに Z パス（奥行きの絵）で前後を決めるか、手前・中・奥に分けて書き出して順に重ねます。煙のような半透明は層分けのほうが安全です。"],["使いどころ","煙・霧・毛・群衆が入り組む大作。個人の動画では層分けで足ります。"],["例","『猿の惑星：創世記』（2011）など Weta の作品 [知識]"]]},{"g":"追いかける","n":"マッチムーブ（Matchmoving／カメラ追跡）","b":[["見え方","手持ちで揺れる映像の中に、CGが床に張り付いて見えます。"],["作り方","映像の中の動かない点を何個も追いかけ、そこからカメラの動きとレンズを計算で割り出します。このMacでは、Blenderの Movie Clip Editor で点を8個以上（手前と奥の両方）追跡し、「Solve Camera Motion」→「Setup Tracking Scene」。誤差（Solve error）が1ピクセル未満なら使えます。"],["使いどころ","実写にCGを置く作業すべての土台。ぶれたコマ、のっぺりした壁、動く物ばかりの画面は苦手です。"],["例","『ジュラシック・パーク』（1993）草原を走る恐竜の群れ（カメラが動く実写にCGを合わせた）[知識]"]]},{"g":"追いかける","n":"平面トラッキング（Planar tracking）","b":[["見え方","壁・看板・画面・服の面に、絵が貼り付いたまま動きます。"],["作り方","点ではなく「平らな面の模様全体」を追い、四隅の位置を出します。このMacでは、Blenderで面の四隅近くの4点を追って Plane Track を作り、コンポジターの Plane Track Deform で絵を貼ります。"],["使いどころ","看板の差し替え、タトゥーや傷を足す、ロトスコープの下準備。面が曲がる・隠れると外れます。"],["例","なし"]]},{"g":"追いかける","n":"手ブレ補正（Stabilization）","b":[["見え方","揺れが消え、台車で撮ったようになめらかになります。"],["作り方","コマごとのずれを測り、逆向きに動かして打ち消し、はみ出た分を少し拡大して隠します。このMacでは、ffmpeg の vidstabdetect → vidstabtransform（2回がけ）。入っていなければ1回で済む deshake。Blenderの 2D Stabilization でもできます。"],["使いどころ","歩き撮り、望遠。強くかけると画面の端がゆがみ、ぶれたコマだけが残って変に見えます。わざと揺れを残すのも演出です。"],["例","なし"]]},{"g":"追いかける","n":"画面の差し替え（Screen replacement）","b":[["見え方","スマホ・パソコン・テレビの画面に、後から作った中身が映ります。"],["作り方","撮影では画面を緑か、目印つきの灰色にしておき、四隅を追って絵をはめます。このMacでは、平面トラッキングで四隅を出すか、カメラ固定なら ffmpeg perspective で絵を台形に変形して overlay。上に薄い反射と指の重なり（マスク）を戻します。"],["使いどころ","画面の内容を編集の最後まで決めたくない時。画面の光が顔に当たっていないと嘘になります。"],["例","なし（多くのドラマで使われますが、特定の場面は確かめていません）"]]},{"g":"追いかける","n":"空の差し替え（Sky replacement）","b":[["見え方","白く飛んだ空が、夕焼けや嵐の空になります。"],["作り方","空の部分を明るさと青さで切り抜き、別の空を奥に敷きます。このMacでは、numpy で「明るくて青い所」をマスクにし、縁をぼかして別の空の写真と混ぜます。カメラが動くなら、空を動きに合わせて少しだけずらします（空は遠いので動きは小さく）。"],["使いどころ","天気がそろわなかった日のつなぎ、気分の強調。地面の色と光の向きも空に合わせないと浮きます。"],["例","なし"]]},{"g":"足す","n":"デジタルの背景画（Digital matte painting）","b":[["見え方","実写の奥に、描いた都市・山・宇宙が広がります。"],["作り方","写真の切り貼りと筆で1枚の絵を作り、層に分けて奥に置きます。このMacでは、Krita などで描いた絵を層ごとの PNG にし、Blenderで奥行きをずらした板に貼って少しだけカメラを動かします（下の「カメラ投影」や 2.5次元 ✓ と同じ）。"],["使いどころ","場所を見せる最初の引きの絵。動かない絵なので、煙・鳥・光のゆらぎを足します。"],["例","『ロード・オブ・ザ・リング 旅の仲間』（2001）裂け谷の全景 [知識]"]]},{"g":"足す","n":"セットの延長（Set extension）","b":[["見え方","役者の周りだけ本物で、上や奥が続いて見えます。"],["作り方","セットは手の届く高さまで建て、その上をCGや絵で足します。境目は柱の縁や影の線に隠します。このMacでは、マッチムーブしたカメラでBlenderの建物を上に足し、境目をマスクでぼかします。"],["使いどころ","競技場・城・街。役者が境目をまたぐと切り抜きが要ります。"],["例","『グラディエーター』（2000）コロッセオの上の段と観客 [知識]"]]},{"g":"足す","n":"CGキャラクター（CG character）","b":[["見え方","実在しない生き物が、実写の人と同じ光の中で演じます。"],["作り方","形を作る→骨を入れる→動かす→毛・筋肉・布を計算→現場の光で照らす→合成。このMacでは、Blenderで骨入りの模型を動かし、現場の光は下の「HDRI」で写します。M1 では毛と肌の細かい計算は重いので、まずは影と接地（足元の影）だけをきちんと合わせるのが近道です。"],["使いどころ","人が演じられない体。目の動きと、足が床を踏む重さでばれます。"],["例","『ヤング・シャーロック ピラミッドの謎』（1985）ステンドグラスの騎士 [知識]／『ロード・オブ・ザ・リング 二つの塔』（2002）ゴラム [知識]"]]},{"g":"足す","n":"デジタルダブル（Digital double）","b":[["見え方","危ない動きの瞬間だけ、役者がCGの写しに入れ替わっています。"],["作り方","役者の体と顔を立体で読み取り、そっくりのCGを作ります。動きの速い所・遠い所で入れ替えます。このMacでは、Blenderの人型模型に同じ服の色を付け、遠景と速い動きのコマだけに使います（寄りは避ける）。"],["使いどころ","落下、変身、役者には無理な動き。入れ替えは、ぶれたコマや物の陰で行います。"],["例","『タイタニック』（1997）沈む船から落ちる人々・甲板を歩く人々 [知識]"]]},{"g":"足す","n":"群衆（Crowd simulation）","b":[["見え方","何万人もの兵士や観客が、一人ずつ少し違う動きをします。"],["作り方","一人ずつに簡単な判断（進む・よける・戦う）を持たせて一斉に動かします。このMacでは、Blenderの Geometry Nodes で人の模型を点の上に大量に並べ（インスタンス）、動きの始まりの時間・大きさ・色を乱数で少しずつずらします。"],["使いどころ","戦場、競技場。全員が同じ瞬間に同じ動きをすると一目でばれます。"],["例","『ロード・オブ・ザ・リング 二つの塔』（2002）ヘルム峡谷の軍勢 [知識]"]]},{"g":"足す","n":"粒子（火・煙・水／Particles・Fluid simulation）","b":[["見え方","火、煙、ほこり、水しぶき、魔法の光。"],["作り方","小さな粒や、空間を箱に区切った流れの計算で作ります。このMacでは、Blenderの Mantaflow（煙・火は Gas、水は Liquid）。M1 では区切りの細かさ（Resolution）を 64〜128 にとどめます。軽く済ませるなら、numpy で粒の位置と速さを毎コマ更新して点を描き、ぼかして screen で重ねます。"],["使いどころ","空気を足すとCGがなじみます。大きい現象ほどゆっくり動かします（技法10「ミニチュアの高速度撮影」と同じ理屈）。"],["例","『パーフェクト ストーム』（2000）巨大な波 [知識]"]]},{"g":"足す","n":"破壊（Destruction／Rigid body）","b":[["見え方","建物が崩れ、壁が砕け、地面が割れます。"],["作り方","物をあらかじめかけらに割り、硬い物どうしのぶつかりを計算し、ほこりと細かい破片を足します。このMacでは、Blenderの Cell Fracture アドオンで割り、Rigid Body で落とします。かけらは数百個までにし、煙は別に足します。"],["使いどころ","災害、戦い。大きなかけら・小さなかけら・ほこりの3段がそろうと本物らしくなります。"],["例","『2012』（2009）ロサンゼルスが崩れる場面 [知識]"]]},{"g":"足す","n":"銃口の光（Muzzle flash）","b":[["見え方","撃った瞬間の火と、顔や壁への一瞬の照り返し。"],["作り方","火の絵を銃口に1〜2コマだけ足し算で重ね、同じコマで周りを少し明るく暖色にします。薬きょう・煙も足します。このMacでは、Pillow で星形の炎を描いてぼかし、ffmpeg overlay を enable='between(n,30,31)' のようにコマ指定で出し、同じコマだけ eq=brightness で全体を少し明るくします。"],["使いどころ","安全のため本物の空砲を使わない撮影。3コマ以上続けると遅く見えます。"],["例","なし"]]},{"g":"足す","n":"天気（Weather FX）","b":[["見え方","雨・雪・霧・稲妻・濡れた地面。"],["作り方","粒子で雨や雪を作り、奥ほど薄く小さくし、霧で遠くをかすませます。このMacでは、numpy で3層（手前は太く速い、奥は細く遅い）の白い線を描いて重ね、全体の彩度を下げ、青みを足します。Blenderなら粒子＋ワールドの霧。"],["使いどころ","気分を変える、別の日に撮った絵をそろえる。地面と服が濡れていないと雨に見えません。"],["例","『デイ・アフター・トゥモロー』（2004）竜巻と大波 [知識]"]]},{"g":"消す・直す","n":"ワイヤー消し（Wire removal）","b":[["見え方","役者を吊っていた綱が消えます（見えないのが成功）。"],["作り方","綱の線をなぞり、両側の色で埋めるか、役者のいない同じ構図の絵（クリーンプレート）から背景を持ってきます。このMacでは、Pillow で線の範囲のマスクを作り、カメラ固定ならきれいな背景のコマから貼り戻します。動くカメラなら、線の左右のピクセルを平均して埋める方法が近い代わりです。"],["使いどころ","技法10「ワイヤーアクション」とセット。髪や服にかかった所が難所です。"],["例","『マトリックス』（1999）吊りを使った格闘場面 [知識]"]]},{"g":"消す・直す","n":"ごみ消し（Cleanup／Paint-out）","b":[["見え方","マイク、スタッフの映り込み、看板、電線、ほこりが消えます。"],["作り方","消したい所を囲み、周りや別のコマの絵で埋めます。このMacでは、カメラ固定なら「数秒ぶんの中央値」（numpy の np.median をコマの束にかける）で、通りすがりの物が消えたきれいな背景が作れます。それを消したい所だけに貼ります。"],["使いどころ","時代劇の現代の物、撮り直せない失敗。撮る時に何も無い背景を数秒撮っておくと後が楽です。"],["例","なし"]]},{"g":"消す・直す","n":"肌の修正（Beauty work／Digital makeup）","b":[["見え方","吹き出物・くま・しわが目立たなくなります。"],["作り方","顔を追いかけ、肌の細かい凹凸は残したまま、色のむらだけをならします。このMacでは、顔のマスクを作り、ぼかした絵と元の絵の差（細かい模様）を戻してから混ぜます（numpy で「元 − ぼかし」を足し戻す）。"],["使いどころ","広告、寄りの絵。やりすぎると蝋人形の肌になるので、毛穴は残します。"],["例","なし"]]},{"g":"消す・直す","n":"若返り（De-aging）","b":[["見え方","役者が数十年若い顔になります。"],["作り方","顔を追いかけて形を引き上げ、肌を直す方法と、顔ごとCGや機械学習の顔に入れ替える方法があります。このMacでは本格的な物は計算が重く、追跡の精度も要るので、一番近い代わりは「肌の修正＋あごの線を少し引き上げる変形（Pillow の MESH 変形）＋髪の色」を静かな短いカットに使うことです。"],["使いどころ","回想。顔は若くても体の動きは年のままなので、動きの少ない場面に。"],["例","『ベンジャミン・バトン 数奇な人生』（2008）[知識]／『アイリッシュマン』（2019）[知識]"]]},{"g":"消す・直す","n":"顔の差し替え（Face replacement）","b":[["見え方","代役の体に、本人や別人の顔が付きます。"],["作り方","代役の顔の向きを追いかけ、別に撮った顔やCGの顔を貼り、首の境目と光を合わせます。今は機械学習（ディープフェイク）も使います。このMacでは、無料の MediaPipe（顔の点を出す Python の道具）で顔の点を取り、Pillow の MESH 変形で別の顔写真を合わせて貼る方法が近い代わりです。正面に近い短いカットなら形になります。本人の許可が無い実在の人の顔には使いません。"],["使いどころ","1人2役、危ない場面の代役、亡くなった役者。"],["例","『ソーシャル・ネットワーク』（2010）双子の兄弟（1人の役者の顔を代役の体に）[知識]／『ローグ・ワン』（2016）ターキン総督 [知識]"]]},{"g":"動きを取る","n":"モーションキャプチャ（Motion capture）","b":[["見え方","人の体の動きが、そのままCGの体に移ります。"],["作り方","体に目印を付けて多数のカメラで撮るか、動きを測る服を着て、関節の動きを数字にします。このMacでは、普通の動画から MediaPipe Pose で関節の位置を出し、Python でBlenderの骨に写します。奥行きは粗いので、横からの動きが得意です（Hugoさんの ~/opensim-lab の人体の当てはめと同じ流れ）。"],["使いどころ","歩き・戦い・踊り。足が床を滑る、手が体にめり込む、は後で直します。"],["例","『ロード・オブ・ザ・リング 二つの塔』（2002）ゴラム [知識]"]]},{"g":"動きを取る","n":"演技キャプチャ（Performance capture）","b":[["見え方","体・顔・声を同時に取り、役者の芝居がまるごとCGキャラになります。"],["作り方","体の目印と、頭に付けた小さなカメラで顔を、同じ場で一緒に撮ります。このMacでは、体は上の MediaPipe Pose、顔は MediaPipe Face Mesh で別々に出して、同じ動画から両方を取れば近い形になります。"],["使いどころ","CGキャラが主役の作品。相手役と同じ場で演じられるのが強みです。"],["例","『アバター』（2009）[知識]／『猿の惑星：創世記』（2011）屋外での撮影 [知識]"]]},{"g":"動きを取る","n":"顔のキャプチャ（Facial capture）","b":[["見え方","まゆ・目・口の細かい動きがCGの顔に移ります。"],["作り方","顔に点を打つか、点なしで映像から顔の形を読み取り、CGの顔の「表情の部品」（シェイプキー）の強さに変えます。このMacでは、MediaPipe Face Mesh が出す表情の数値（口の開き、まばたきなど）を、Blenderのシェイプキーの値として毎コマ書き込みます。"],["使いどころ","しゃべるCGキャラ、VTuber。目の動きが止まると死んで見えます。"],["例","『ベンジャミン・バトン 数奇な人生』（2008）老いた顔 [知識]"]]},{"g":"見せ方の発明","n":"バレットタイム（Bullet time）","b":[["見え方","時間が止まるか極端に遅くなり、カメラだけが周りを回ります。"],["作り方","多数のカメラを円く並べて順に（またはほぼ同時に）撮り、1コマずつつなぎます。間はコマの補間で埋めます。このMacでは、Blenderが得意で、物の動きを極端に遅くして（Time Remapping、または動きのキーを止める）カメラだけ円の道を回します。実写なら、止まった物の周りをスマホで回って撮るのが近い代わりです。"],["使いどころ","決定的な一瞬。1作品に1〜2回が限度です。"],["例","『マトリックス』（1999）屋上でのけぞって弾をよける場面 [知識]"]]},{"g":"見せ方の発明","n":"モーフィング（Morphing）","b":[["見え方","顔や物が、ぬるっと別の形に変わります。"],["作り方","2つの絵で対応する点（目・鼻・口・輪郭）を決め、形をゆがめながら絵を溶かします。このMacでは、Pillow の Image.transform(..., Image.MESH) で両方の絵を「中間の形」へ変形し、Image.blend で混ぜる量を0→1に動かします。対応点は20〜40個ほど手で打ちます。"],["使いどころ","変身、年をとる、似た形どうしのつなぎ。形が似ているほどきれいです。"],["例","『ウィロー』（1988）動物が次々に変わる場面 [知識]／『ターミネーター2』（1991）液体金属の男 [知識]"]]},{"g":"見せ方の発明","n":"1人2役（分身／Twinning・Split screen）","b":[["見え方","同じ役者が同じ画面に2人います。"],["作り方","カメラを固定して左右で2回演じ、画面を分けて合わせます。カメラを動かす時はモーションコントロール（技法10）、重なる時は顔の差し替えを使います。このMacでは、三脚で2回撮り、ffmpeg で crop した左半分と右半分を hstack、または縁をぼかしたマスクで maskedmerge。境目は柱やドアの縁など動かない線に置きます。"],["使いどころ","双子、分身、過去の自分との会話。光が2回の間に変わるとばれます。"],["例","『バック・トゥ・ザ・フューチャー PART2』（1989）同じ役者が家族を何役も演じる場面 [知識]"]]},{"g":"見せ方の発明","n":"2.5次元の視差（Parallax／2.5D）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","1枚の写真や絵を手前・中・奥に切り分け、少しだけずらして動かすと立体に見えます。ドキュメンタリーの古い写真、背景画に奥行きを出す時の定番です。切り抜いた裏の穴は描き足して埋めます。"]]},{"g":"見せ方の発明","n":"カメラ投影（Camera projection／Camera mapping）","b":[["見え方","1枚の写真や絵の中へ、カメラが少し入っていけます。2.5次元より立体的です。"],["作り方","写真を、撮った位置から簡単な立体（箱や板）へスライドのように映し、別のカメラで少し動いて撮ります。このMacでは、Blenderで写真に合わせた箱を置き、UV Project モディファイアで写真を映し、Emission で貼ります。動かす範囲は元の位置から少しだけです（裏側は絵が無い）。"],["使いどころ","背景画に動きを付ける、写真1枚からの空撮風。大きく回ると絵が伸びます。"],["例","『マトリックス』（1999）バレットタイムの背景（写真を簡単な立体に映して作った）[知識]"]]},{"g":"見せ方の発明","n":"立体視（Stereoscopic 3D）","b":[["見え方","めがねをかけると、物が画面の手前や奥に見えます。"],["作り方","右目用と左目用を、少し離した2台のカメラで撮るか、1本の映像から奥行きを作って変換します。このMacでは、Blenderの出力設定 Stereoscopy を入れると左右2本が出ます。ffmpeg stereo3d=sbsl:arcg で赤青めがね用に変換できます。"],["使いどころ","奥行きが主役の作品。飛び出しを多用すると目が疲れます。"],["例","『アバター』（2009）[知識]"]]},{"g":"新しい道具","n":"AIの動画生成（Generative video）","b":[["見え方","文や1枚の絵から、数秒の動画が出ます。"],["作り方","文や画像を入れて生成します。このMacでは、M1・8GB で動画生成AIを手元で動かすのは重くて実用になりにくいので、契約中の Google AI Plus に付く動画生成など、ネット上の枠を使うのが現実的です。出てきた数秒を素材として、ffmpeg で切る・重ねる・色を合わせるのは手元でできます。"],["使いどころ","背景の素材、撮れない一瞬、絵コンテ代わり。同じ人物を別のカットで同じ顔に保つのが苦手で、権利と表示の決まりにも注意が要ります。"],["例","なし（動きが速い分野で、確かな代表例を確かめていません）"]]},{"g":"新しい道具","n":"AIの切り抜き・穴埋め（AI matting／Inpainting）","b":[["見え方","緑の幕なしで人物が抜け、消した物の跡が自然に埋まります。"],["作り方","機械学習が「人物らしさ」や「周りから見て自然な続き」を当てます。このMacでは、切り抜きは rembg（Python、CPUで動く）を1コマずつ。穴埋めは、カメラ固定なら「ごみ消し」の中央値の背景が確実です。動画用の穴埋めAIは M1・8GB では重いので、静止画1枚を直して背景画として使うのが近い代わりです。"],["使いどころ","ロトスコープの下ごしらえ、急ぎの仕事。髪の先と、コマごとのちらつきは手で直します。"],["例","『エブリシング・エブリウェア・オール・アット・ワンス』（2022）少人数のVFX班が切り抜きにAIの道具を使った [知識]"]]},{"g":"新しい道具","n":"コマの補間（Frame interpolation）","b":[["見え方","カクカクの映像がなめらかになり、普通の映像がスローになります。"],["作り方","前後のコマから物の動きを推定し、間の絵を作ります。このMacでは、ffmpeg minterpolate=fps=60:mi_mode=mci（遅いが追加の道具なし）。もっときれいにしたい時は、無料の RIFE（Mac用の実行ファイルがある [知識]、未検証）。"],["使いどころ","スロー、古い映像のコマ数直し。手足が速く動く所で絵が溶けます。アニメにかけると作り手のコマ打ち（技法14）を壊します。"],["例","『彼らは生きていた』（2018）百年前の手回しカメラの映像を今の速さに直した [知識]"]]},{"g":"新しい道具","n":"高画質化（Upscaling／Super resolution）","b":[["見え方","小さく粗い映像が、大きくくっきりします。"],["作り方","機械学習が細部を「ありそうな形」で描き足します。このMacでは、ふつうの拡大は ffmpeg scale=iw*2:ih*2:flags=lanczos。AIの拡大は無料の Real-ESRGAN（Mac用の実行ファイルがある [知識]、未検証）を1コマずつ。動画は時間がかかるので短い素材向きです。"],["使いどころ","古い素材、拡大して使いたいカット。細部は「作り物」なので、顔や文字が変わっていないか見比べます。"],["例","なし"]]},{"g":"新しい道具","n":"NeRF・ガウシアンスプラット（NeRF／3D Gaussian Splatting）","b":[["見え方","たくさんの写真から、その場所を写真のような見た目のまま立体にし、中を自由に飛べます。"],["作り方","同じ場所を数十〜数百枚撮り、機械学習で「どこから見てもその絵になる立体」を求めます。スプラットは色つきのぼんやりした粒の集まりで表します。このMacでは、学習は強いGPU向けが多く M1・8GB では重いので、スマホの無料アプリやネットの枠で作り、出来た物をBlender（表示用のアドオン）で見るのが現実的です。近い代わりは、写真から形を起こす写真測量（Mac標準の Object Capture の仕組み [知識]）です。"],["使いどころ","実在の場所を自由なカメラで、ロケ地の下見。動く物と、鏡・ガラスが苦手です。"],["例","なし"]]},{"g":"新しい道具","n":"立体の撮影（Volumetric capture）","b":[["見え方","演じている人を丸ごと立体の動画にし、後からどの角度からでも見られます。"],["作り方","人を多数のカメラ（または奥行きを測るセンサー）で囲んで撮り、コマごとに立体を作ります。このMacでは、囲むカメラが無いので、奥行きを測れるスマホで撮った「奥行きつき動画」を点の集まりとしてBlenderに読み込むのが近い代わりです（正面側だけの立体になります）。"],["使いどころ","VR、ライブ、自由視点の映像。データがとても大きく、髪と指が荒れます。"],["例","レディオヘッド「House of Cards」のミュージックビデオ（2008）カメラを使わずレーザーの測定の点だけで作った [知識]"]]},{"g":"足した技法（地図に無かったもの）","n":"なじませ（Integration：色・粒・ぶれ・ライトラップ）","b":[["見え方","足した物が「後から置いた」と分からなくなります。"],["作り方","(1) 一番暗い所と一番明るい所の色を背景にそろえる (2) 背景の光を人物の縁に少しにじませる（ライトラップ） (3) 同じ粒（グレイン）とぼけとレンズのゆがみを足す (4) 動きのぶれをそろえる。このMacでは、ffmpeg curves／colorbalance で黒と白を合わせ、背景をぼかした絵を縁だけに薄く足し、最後に全体へ noise=alls=6:allf=t をかけます。"],["使いどころ","すべての合成の最後。全体に同じ粒を最後にかけるだけでも、かなりなじみます。"],["例","なし（すべての合成に入っている作業）"]]},{"g":"足した技法（地図に無かったもの）","n":"HDRIで光を写す（Image-based lighting）","b":[["見え方","CGが現場と同じ光・同じ映り込みで照らされます。"],["作り方","現場で、周り360度を明るさの幅を広く取って撮り（銀色の球を撮る方法も）、その写真そのものを光としてCGを照らします。このMacでは、無料の HDRI（Poly Haven など）をBlenderのワールドに Environment Texture で入れます。自分の現場なら、スマホのパノラマでも向きと色の手がかりになります。"],["使いどころ","CGキャラ、CGの小物を実写に置く時。足元の影を受ける板（Shadow Catcher）とセットで使います。"],["例","なし"]]},{"g":"足した技法（地図に無かったもの）","n":"プリビズ（Previsualization／事前の動画コンテ）","b":[["見え方","本番前に、簡単なCGで場面全体の動きとカメラを確かめた仮の動画です。"],["作り方","箱と人形だけの粗い3Dでカメラを動かし、長さと順番を決めます。このMacでは、Blenderの Workbench（一番軽い表示）で箱人形を動かし、低い解像度で書き出して ffmpeg でつなぎます。"],["使いどころ","VFXや特撮の多い場面は、撮ってから直すと高くつくので先に決めます。ラウンド制の「一番あやしい所を先に小さく試す」と同じ考えです。"],["例","なし"]]}],"12":[{"g":"文字","n":"タイトルバック（Title sequence）","b":[["見え方","本編の前（または冒頭の後）に、題名とスタッフ名が絵や図形と一緒に出る1〜3分の小さな作品です。"],["作り方","本来は専門のデザイナーが本編の主題を1つの図形や動きに置きかえます。真似るなら「主題の形を1つ決める（線・円・切り抜き）→ 名前1つにつき2〜4秒 → 音楽の拍で切り替え」。書体と色は本編と同じ2色までにします。"],["使いどころ","作品の調子（怖い・軽い・おしゃれ）を説明なしで伝えたい時。短い動画では3〜5秒に縮めないと離脱されます [意見]。"],["例","『サイコ』（1960年）横線が走って文字を切りさく冒頭／『セブン』（1995年）引っかいたような震える文字 [知識]"]]},{"g":"文字","n":"キネティック・タイポグラフィ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","題字そのものが動いて場面の一部になります。台詞を全部文字にするのではなく、題名や強い一語だけに使うのが映画流です。"],["例","『北北西に進路を取れ』（1959年）斜めの線の上を文字が走り、そのままビルの窓に変わる冒頭 [知識]"]]},{"g":"文字","n":"テロップ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","場所・日時・翻訳の字幕が中心で、飾りは最小です。目安は1秒4文字、1行13文字前後で2行まで [知識]。"],["例","『シン・ゴジラ』（2016年）会議のたびに出る明朝体の肩書きと部署名 [知識]"]]},{"g":"文字","n":"ローワーサード（Lower third）","b":[["見え方","画面の下3分の1に出る、名前と肩書きの帯です。"],["作り方","帯（四角）が左から0.3〜0.5秒で伸びる → 0.1秒遅れて名前が出る → 3〜5秒止める → 0.3秒で消す。名前は肩書きの1.5〜2倍の大きさ。画面の端から5%は空けます（切れ防止）。コードなら四角の幅を0→100%に動かし、文字は透明度0→1と下から20pxの移動を同時に。"],["使いどころ","インタビュー、解説、紹介。出しっぱなしは邪魔なので、初登場の時だけにします。"],["例","『シン・ゴジラ』（2016年）人物が出るたびの名前と役職の表示 [知識]"]]},{"g":"文字","n":"吹き出し・指し線（Callout）","b":[["見え方","物から細い線が伸びて、その先に説明の文字や枠が出ます。"],["作り方","(1) 指す点に小さな丸が出る（4コマ）(2) 線が伸びる（8〜12コマ）(3) 文字が出る、の順。線は1〜3px、折れ線は1回まで。動く物を指すなら点だけを追跡させ、文字の枠は動かさないと読みやすいです。"],["使いどころ","商品の説明、ゲーム解説、人物紹介。3つ以上同時に出すと読めません。"],["例","『スコット・ピルグリム VS. 邪悪な元カレ軍団』（2010年）人物の横に名前や年齢の枠がゲーム風に出る [知識]"]]},{"g":"文字","n":"場面に張りつく文字（トラッキング文字・Tracked text）","b":[["見え方","壁や床、動く物に文字が貼ってあるように見え、カメラが動いてもずれません。"],["作り方","本来は追跡ソフトでカメラや面の動きを求めます。真似るなら、面の4つの角を追いかけて文字を同じ形にゆがめる（コーナーピン）。コードなら OpenCV で特徴点を追う（オプティカルフロー）→ 変形の行列を毎コマ文字にかける。仕上げに絵と同じ量の動きぶれ・粒子・少しのぼけを足すと「貼った感」が消えます。"],["使いどころ","頭の中の考えや数字を世界の一部として見せたい時。説明くさくならないのが利点です。"],["例","『主人公は僕だった』（2006年）歩数や歯みがきの回数が物の横に張りつく／『ゾンビランド』（2009年）生き残りのルールの文字が場面に置かれ、物が当たると揺れる [知識]"]]},{"g":"文字","n":"人の後ろに入る文字（Text behind subject）","b":[["見え方","大きな文字が、人や建物の後ろ・背景の手前にはさまって見えます。"],["作り方","重ねる順番を「背景 → 文字 → 切り抜いた人」にするだけです。人の切り抜きは毎コマ必要（自動の人物切り抜き、またはグリーンバック）。髪の毛の縁は1〜2pxぼかします。文字は画面幅の60〜90%と大きく、太い書体で。"],["使いどころ","題名、サムネ、ショート動画の冒頭。人が動いて文字が全部隠れる時間が長いと読めません。"],["例","『パニック・ルーム』（2002年）冒頭、スタッフ名が街のビルの間に立体で浮かぶ [知識]"]]},{"g":"文字","n":"手書き風の書き出し（Write-on）","b":[["見え方","見えないペンが書いているように、線が書き順どおりに現れます。"],["作り方","文字を線（パス）にして、線の「見える長さ」を0→100%に動かします（トリムパス）。1文字0.2〜0.4秒、1語で0.8〜1.5秒。画像の文字なら、書き順にそってマスクをなぞって広げます。線の先を少し太くするとインクらしくなります。"],["使いどころ","署名、ノート風、温かい・個人的な雰囲気。長文には向きません。"],["例","『JUNO／ジュノ』（2007年）手描きの線で作られた冒頭タイトル [知識]"]]},{"g":"文字","n":"エンドロール（End credits / crawl）","b":[["見え方","スタッフ名が下から上へ一定の速さで流れます。"],["作り方","1コマあたり「ちょうど整数のピクセル」で動かします（例：フルHD・24コマで2pxか4px）。半端な速さだと文字が震えます。文字は30px以上、行間は1.5倍、役職は小さく名前は大きく。"],["使いどころ","感謝と余韻。横にNG集や後日談の絵を置くと最後まで見てもらえます。"],["例","『スター・ウォーズ』（1977年）冒頭の、奥へ倒れて流れていく説明文（ロールの変形）／『バグズ・ライフ』（1998年）NG集つきのエンドロール [知識]"]]},{"g":"文字","n":"字幕カード（無声映画）（Intertitle）","b":[["見え方","絵を止めて、黒い画面に白い文字だけのカードがはさまります。"],["作り方","黒地・白文字・飾り枠・中央寄せ。読む時間は「自分がゆっくり2回読める長さ」。台詞の直前の口の動きの後に入れます。少しの揺れ（1〜2px）とフィルムの傷を足すと古く見えます。"],["使いどころ","昔風、コメディ、声を出せない場面。今は章の区切りにも使えます。"],["例","『メトロポリス』（1927年）／『アーティスト』（2011年）現代に作られた無声映画 [知識]"]]},{"g":"文字","n":"画面上のメッセージ表示（On-screen text message）","b":[["見え方","スマホの画面を映さず、メッセージの文字や吹き出しが人物の横に浮かびます。"],["作り方","人物の顔の横の空いた所に文字を置き、受信の瞬間に0.2秒で出す（下から10pxずれて透明度0→1）。入力中は1文字ずつ出し、消すと文字が戻る。人物が動くなら軽く追従させます。通知音を必ず付けます。"],["使いどころ","スマホのやり取りを、演技（顔）と同時に見せたい時。画面の大写しより速く、古びにくいです。"],["例","ドラマ『SHERLOCK／シャーロック』（2010年）メールの文が空中に出る／『君の名は。』（2016年）スマホの日記が画面に重なる [知識]"]]},{"g":"文字","n":"＋タイプライター表示（Typewriter / type-on）","b":[["見え方","文字が1つずつ打たれるように出ます。"],["作り方","1文字2〜3コマ（1秒に10〜15文字）。等幅の書体、最後に点滅する棒（カーソル）、打鍵の音を1文字ごとに。"],["使いどころ","場所と日時の表示、機密・捜査・ハッカーの雰囲気。長文だと待たされます（2行まで）。"],["例","ドラマ『X-ファイル』（1993年〜）場面の頭の場所と時刻の表示 [知識]"]]},{"g":"文字","n":"＋マスクで現れる文字（Mask reveal）","b":[["見え方","見えない線から文字がせり上がる、または帯が通りすぎた後に文字が残ります。"],["作り方","文字の行と同じ高さの「窓（マスク）」を置き、文字を窓の下から上へ動かす（8〜12コマ、終わりをゆるく）。帯ワイプは、色の帯が左から右へ通り、帯の後ろで文字を出します。"],["使いどころ","題名、見出し。きれいで読みやすく、どんな動画にも合う基本の出し方です。"],["例","なし"]]},{"g":"図と形","n":"図形のアニメ（Shape animation）","b":[["見え方","丸・四角・線だけが動いて、絵や場面を作ります。"],["作り方","形は単純に、色は2〜3色。動きは「大きさ0→100%」「位置」「回転」だけ。1つの動きは0.3〜0.6秒、次の形は2〜4コマ遅らせて出します。"],["使いどころ","説明動画、タイトル、転換。実写が撮れない抽象的な話に強いです。"],["例","『キャッチ・ミー・イフ・ユー・キャン』（2002年）切り絵のような人影と線だけの冒頭 [知識]"]]},{"g":"図と形","n":"インフォグラフィック（Infographic animation）","b":[["見え方","棒・円・線のグラフや図解が、育つように動きます。"],["作り方","棒は下から伸ばす（0.6〜1秒、終わりをゆるく）、数字は同時にカウント。1画面で言うことは1つ。比べる時は片方を先に出して0.5秒後にもう片方。"],["使いどころ","数字で驚かせたい時。飾りが多いと数字が伝わりません。"],["例","『不都合な真実』（2006年）二酸化炭素のグラフが画面の上へ伸び続ける場面 [知識]"]]},{"g":"図と形","n":"地図の移動線（Map route line）","b":[["見え方","地図の上を線が伸びて、旅の道すじを示します。"],["作り方","出発点から到着点への線の「見える長さ」を0→100%にします。地図を線の先に合わせてゆっくり動かすと旅らしくなります。線の先に乗り物の小さな絵を付けてもよいです。2〜4秒。"],["使いどころ","場所が大きく変わる時の時間の節約。"],["例","『レイダース／失われたアーク《聖櫃》』（1981年）飛行機の絵に重なる赤い線 [知識]"]]},{"g":"図と形","n":"数字のカウント","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","爆弾の残り時間、得点、お金などに使います。桁が動いても幅が変わらない数字（等幅数字）にします。"],["例","なし"]]},{"g":"図と形","n":"進み具合の棒（Progress bar）","b":[["見え方","動画や作業が「いまどこまで来たか」を細い棒で見せます。"],["作り方","幅を「今の時間÷全体の時間」にするだけです。高さは6〜10px、画面の一番上か下。章の区切りに小さな切れ目を入れます。"],["使いどころ","長めの解説、数え上げ、料理や制作の過程。終わりが見えると最後まで見てもらいやすいです [意見]。"],["例","なし"]]},{"g":"図と形","n":"HUD（機械の画面）（Heads-up display）","b":[["見え方","照準、輪、細い線、小さな数字が画面に重なり、機械や未来の目で見ているように見えます。"],["作り方","線は1〜2px、色は水色かオレンジの1色＋白。小さな等幅の文字、回る輪、流れる数字。重ね方は「加算（明るくなる合成）」にして少し光らせ、時々1〜2コマちらつかせます。顔の向きに0.1秒遅れて追従させると本物らしくなります。"],["使いどころ","ロボット・ゲーム・分析の場面。情報を全部読ませる必要はなく、雰囲気が8割です。"],["例","『アイアンマン』（2008年）ヘルメットの中の表示／『ターミネーター』（1984年）赤い視界に文字が流れる [知識]"]]},{"g":"図と形","n":"ロゴの決め（Logo sting / reveal）","b":[["見え方","ロゴが2〜5秒で現れ、短い音と一緒に「決まる」動きです。"],["作り方","(1) 部品が集まる・線が描かれる（1〜2秒）(2) 少し行きすぎて戻る (3) 光が1回横切る (4) 止まる。決まる瞬間に短い音（低い一打＋高いきらめき）を合わせます。"],["使いどころ","動画の最初か最後。毎回同じにすると覚えてもらえます。5秒を超えると飛ばされます [意見]。"],["例","ピクサーの、ランプが文字を踏むロゴ [知識]"]]},{"g":"図と形","n":"ホワイトボード風（Whiteboard animation）","b":[["見え方","白い板に、手が絵と文字を描いていくのを早回しで見ます。"],["作り方","本来は実際に描いて早回し（4〜8倍）。真似るなら、絵を線にして書き出し（トリムパス）で順に出し、手の写真を線の先に付けます。語りの言葉が出る瞬間に、その絵が描き終わるように合わせます。"],["使いどころ","講義、考え方の説明。目が線の先を追うので、長い説明でも見続けやすいです。"],["例","英国の講演アニメ「RSA Animate」シリーズ（2010年ごろ） [知識]"]]},{"g":"図と形","n":"＋線が伸びる（トリムパス）（Trim path）","b":[["見え方","線が端から伸びていき、枠や下線や矢印になります。"],["作り方","線の「始まり」と「終わり」の位置を別々に動かします。終わりを0→100%にすれば伸び、少し遅れて始まりも0→100%にすれば通りすぎて消えます。8〜15コマ。"],["使いどころ","下線、囲み、矢印、地図の線、手書き風。モーショングラフィックスの一番の基本部品です。"],["例","なし"]]},{"g":"動きの質","n":"イージング","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","題字やカメラの仮想の動きは、出だしと止まりをゆるくして「重さ」を出します。入ってくる物は「終わりをゆるく」、出ていく物は「出だしをゆるく」が基本です。"],["例","なし"]]},{"g":"動きの質","n":"アニメの12原則の応用（12 principles of animation）","b":[["見え方","ただの丸や文字が、重さと気持ちを持って見えます。"],["作り方","12原則はディズニーの作画家が本にまとめた動きの決まりです（1981年の本） [知識]。文字と図形でよく使うのは5つ。(1) つぶしと伸ばし：動く向きに10〜20%伸ばし、止まる時につぶす (2) 予備動作：動く前に逆へ2〜4コマ (3) あとから付いてくる動き：部品を2〜3コマ遅らせる (4) 弧：直線でなく曲線で動かす (5) タイミング：コマ数が少ないと軽く速く、多いと重く見える。"],["使いどころ","ロゴ、アイコン、キャラクターのない説明動画。やりすぎると子ども向けに見えます。"],["例","短編『ルクソーJr.』（1986年）電気スタンドが予備動作と伸び縮みだけで生き物に見える [知識]"]]},{"g":"動きの質","n":"オーバーシュート（Overshoot）","b":[["見え方","目的の位置や大きさを少し行きすぎてから、戻って止まります。"],["作り方","大きさなら 0 → 110% → 97% → 100%。全体で10〜14コマ、行きすぎの山は6〜8コマ目。コードなら「ばね」の式、または back/elastic と呼ばれるイージングを使います。"],["使いどころ","ボタン、スタンプ、絵文字、見出しの「ポン」。全部に付けると落ち着かない画面になります。"],["例","なし"]]},{"g":"動きの質","n":"液体のような動き（Liquid motion）","b":[["見え方","形が水あめのように伸び、くっつき、ちぎれます。"],["作り方","(1) 丸をいくつか動かす (2) 全体を10〜20pxぼかす (3) 明暗の差を極端に強めて縁を固くする、で形同士が近づくとつながります（メタボール）。動く向きへの伸びと、止まった後の小さな揺れを足します。"],["使いどころ","楽しい・やわらかい・食べ物や飲み物の雰囲気、場面の転換。"],["例","なし"]]},{"g":"動きの質","n":"形のモーフ（Shape morph）","b":[["見え方","ある形が、切れ目なく別の形に変わります。"],["作り方","2つの形の点の数をそろえ、点を1つずつ対応させて動かします。8〜12コマ。途中の形が汚い時は、途中で一度「丸」や「線」を通す、または回転と動きぶれでごまかします。"],["使いどころ","アイコンからアイコンへ、話題の切り替え。「AがBになる」という意味を持たせると効きます。"],["例","写真の顔が別の顔へ変わる型は、マイケル・ジャクソン「Black or White」の音楽ビデオ（1991年）の終盤 [知識]"]]},{"g":"動きの質","n":"視差スライド（Parallax slide）","b":[["見え方","写真や絵が層に分かれ、手前が速く奥が遅く動いて、奥行きが出ます。"],["作り方","絵を「手前・中・奥」に切り分け、同じ向きに動かす量を 1：0.5：0.2 ほどにします。切り抜いた跡の穴は周りの絵でうめます。3〜6秒かけてゆっくり。"],["使いどころ","写真しかない題材（歴史・思い出）、スライドの切り替え。MADで作った「写真の立体化」と同じ仕組みです。"],["例","『くたばれ！ハリウッド』（2002年）古い写真を層に分けて動かす [知識]"]]},{"g":"動きの質","n":"＋ずらし出し（スタッガー）（Stagger）","b":[["見え方","文字や部品が、同じ動きを少しずつ遅れて順番に行います。"],["作り方","1つごとに1〜3コマ（0.03〜0.1秒）遅らせます。文字なら1文字ずつ、表なら1行ずつ。遅れの合計は0.5秒以内に収めます。"],["使いどころ","ほぼ全部の文字と図形。同時に出すより、これだけで「プロっぽく」見えます。"],["例","なし"]]},{"g":"動きの質","n":"＋動きぶれ（モーションブラー）（Motion blur）","b":[["見え方","速く動く文字や形が、動く向きに少し流れて見えます。"],["作り方","ソフトのスイッチを入れるだけです。コードなら、1コマを4〜8回に細かく分けて描いて平均します。"],["使いどころ","速い動き全般。無いとカクカクして安く見え、あると実写になじみます。ゆっくりの動きには不要です。"],["例","なし"]]}],"13":[{"g":"種類","n":"物語の中の音と外の音（Diegetic / non-diegetic sound）","b":[["聞こえ方","中の音＝登場人物にも聞こえる音（足音、ラジオの曲）。外の音＝観客だけに聞こえる音（劇伴の音楽、語り）。"],["作り方","中の音は「その場の響き」と「出どころの方向」を付けます（ラジオなら高音と低音を削る、部屋の残響を足す）。外の音はきれいなまま全体に広げます。同じ曲を、中の音→外の音へ途中で切り替える手もあります（削りを外して音量を上げる）。"],["使いどころ","曲が「場面の中で鳴っている」と分かると現実味が出ます。外の音だと思わせて実は中の音だった、は笑いにもなります。"],["例","『ベイビー・ドライバー』（2017年）主人公のイヤホンの曲がそのまま場面の音楽になる／『ブレージングサドル』（1974年）劇伴だと思った楽団が砂漠で本当に演奏している [知識]"]]},{"g":"種類","n":"フォーリー（Foley）","b":[["聞こえ方","足音、衣ずれ、物を置く音など、人の動きの音。絵にぴったり合っています。"],["作り方","本来は録音室で絵を見ながら人が実演して録ります。真似るなら、素材の音を動きの「当たるコマ」に±1コマで合わせます。足音は床の種類をそろえ、1歩ごとに少しずつ違う音を使います（同じ音のくり返しは機械的に聞こえる）。"],["使いどころ","全部の場面。無いと「口だけ動く人形劇」のように感じます。アニメや3Dでは特に効きます。"],["例","『モンティ・パイソン・アンド・ホーリー・グレイル』（1975年）ココナッツの殻で馬の足音を出す、という定番の作り方をそのまま笑いにしている [知識]"]]},{"g":"種類","n":"環境音・ルームトーン（Ambience / room tone）","b":[["聞こえ方","その場所に流れ続ける音です（風、街、空調）。ルームトーンは「誰も話していない部屋の静けさ」の音。"],["作り方","現場で30秒以上、黙って録ります。編集では場面全体の下にずっと敷き、音量は声より20〜30dB小さく。カットの切れ目で環境音が変わると場所が変わったと伝わるので、同じ場所の中では切らずにつなげます。"],["使いどころ","全部の場面の土台。完全な無音（0）は機械の故障に聞こえるので、静かな場面でも必ず敷きます。"],["例","『ノーカントリー』（2007年）音楽がほとんど無く、風と足音だけで緊張を作る [知識]"]]},{"g":"種類","n":"アフレコ（ADR）","b":[["聞こえ方","撮影の後で録り直した声。雑音が無くはっきりしています。"],["作り方","本来は役者が絵を見ながら口に合わせて言い直します。なじませるには、(1) 口の動きに±1〜2コマで合わせる (2) その場のルームトーンを下に敷く (3) 部屋の響きを少し足す (4) 距離に合わせて高音を少し削る。"],["使いどころ","現場の音がうるさい時、台詞を変えたい時。後ろ姿や遠景なら口が見えないので、台詞を足すのも自由です。"],["例","『続・夕陽のガンマン』（1966年）当時のイタリア映画は全編の声を後から録っていた [知識]"]]},{"g":"種類","n":"ナレーション（Voice-over narration）","b":[["聞こえ方","場面の外から、語り手の声が説明や気持ちを話します。"],["作り方","近いマイクで響きなしに録り、中央に置きます。絵が見せていることは言わず、絵に無い情報（過去・気持ち・皮肉）を言います。語りの間は曲と環境音を下げます。"],["使いどころ","時間を大きく飛ばす時、人物の内面。絵の説明に使うと退屈になります。"],["例","『ショーシャンクの空に』（1994年）仲間の囚人が主人公を語る [知識]"]]},{"g":"種類","n":"ガヤ（Walla）","b":[["聞こえ方","大勢が話している、言葉が聞き取れないざわめき。"],["作り方","本来は数人〜十数人が録音室で適当に話して録ります。言葉がはっきり聞こえると主役の台詞の邪魔になるので、意味のない会話にします。少人数の録音を、時間をずらして3〜4回重ねると大人数になります。音量は台詞より15〜20dB下。"],["使いどころ","店、教室、駅、パーティ。人数に合った厚みにします（3人の店に100人のガヤは変）。"],["例","なし"]]},{"g":"種類","n":"＋画面外の音（Offscreen sound）","b":[["聞こえ方","画面に映っていない物の音が聞こえます。"],["作り方","音だけを置き、人物の「聞いた反応」を映します。方向があるなら左右に振り、壁の向こうなら高音を削ります。"],["使いどころ","見せると安くなる物（怪物・暴力）、予算が無い時。想像のほうが怖い、を使います。"],["例","『関心領域』（2023年）塀の向こうの出来事を、音だけで伝え続ける [知識]"]]},{"g":"種類","n":"＋電話・ラジオごしの声（Futz）","b":[["聞こえ方","細くて鼻にかかった、小さなスピーカーの声。"],["作り方","300Hzより下と3,400Hzより上を削ります（ffmpegなら highpass=f=300,lowpass=f=3400）。少しひずみを足すとより本物らしくなります。"],["使いどころ","電話の相手、無線、テレビの中の声。会話の途中で相手側に場面が移る時は、削りを外して切り替えます。"],["例","なし"]]},{"g":"つなぎ","n":"J・Lカット（J-cut / L-cut）","b":[["聞こえ方","Jカット＝次の場面の音が、絵より先に聞こえる。Lカット＝前の場面の音が、絵が変わった後も続く。"],["作り方","絵と音を同じ所で切らず、音だけ0.3〜1.5秒（8〜36コマ）ずらします。会話なら、話している人の声を残したまま、聞いている人の顔に絵を先に切り替えます（Lカット）。"],["使いどころ","ほぼ全部の会話。同時に切ると卓球のように硬く見えます。ずらすだけで自然になります。"],["例","ほとんどの映画の会話場面（特定の例は挙げません） [知識]"]]},{"g":"つなぎ","n":"音の橋わたし（Sound bridge）","b":[["聞こえ方","1つの音（曲・語り・環境音）が、場面の境目をまたいで続きます。"],["作り方","前の場面の音を次の場面へ2〜5秒のばす、または1つの曲を複数の場面の下に切らずに敷きます。場面が変わる時に、中の音から外の音へ（響きを外して）変えると滑らかです。"],["使いどころ","時間や場所が飛ぶ所、短い場面を並べるモンタージュ。"],["例","『市民ケーン』（1941年）年末のあいさつの言葉の途中で、十数年後の場面に飛ぶ [知識]"]]},{"g":"つなぎ","n":"音のマッチ（Sound match / match on sound）","b":[["聞こえ方","前の場面の最後の音と、次の場面の最初の音が似ていて、1つの音のようにつながります。"],["作り方","高さ・リズム・長さが近い2つの音を選び、切れ目で入れ替えます（重ねるのは2〜6コマ）。例：悲鳴→汽笛、羽音→扇風機、拍手→雨。"],["使いどころ","場面転換を「驚き」や「連想」にしたい時。"],["例","『三十九夜』（1935年）女性の悲鳴がそのまま汽車の汽笛になる／『地獄の黙示録』（1979年）ヘリの羽音と天井の扇風機 [知識]"]]},{"g":"つなぎ","n":"音の先行（Pre-lap）","b":[["聞こえ方","次の場面の音や台詞が、前の場面の終わりに先に聞こえ始めます。"],["作り方","Jカットを長く（0.5〜2秒）、目立つように使います。先に聞かせる音は、はっきりした1つの音（電話のベル、叫び、曲の頭）にします。"],["使いどころ","次への引っぱり。「何の音？」と思わせて切り替えると、観客が自分から次の場面へ進みます。"],["例","なし"]]},{"g":"音楽","n":"ライトモチーフ（人物の主題）（Leitmotif）","b":[["聞こえ方","人物・物・考えごとに決まった短い旋律があり、出るたびに鳴ります。"],["作り方","2〜8音の覚えやすい形を作ります。同じ形を、場面に合わせて速さ・楽器・明るさを変えて使います（強い時は金管で大きく、弱った時はピアノで遅く）。本人が画面にいなくても鳴らせば「存在」を示せます。"],["使いどころ","長い作品、連続もの。主題が多すぎると覚えられません（3つまでが無難 [意見]）。"],["例","『ジョーズ』（1975年）2つの音の主題だけで、見えないサメが来たと分かる／『スター・ウォーズ 帝国の逆襲』（1980年）帝国の行進曲 [知識]"]]},{"g":"音楽","n":"ミッキーマウシング（動きに音楽を合わせる）（Mickey Mousing）","b":[["聞こえ方","歩けば音が刻み、上がれば音階が上がり、転べばドラムが鳴ります。"],["作り方","動きの「当たるコマ」に音の頭を±1コマで合わせます。上への動き＝高くなる音、下＝低くなる音。先に絵の拍を決めてから曲を書く、または曲に合わせて絵の速さを直します。"],["使いどころ","コメディ、アニメ、子ども向け。まじめな場面で使うと安く見えます。"],["例","『蒸気船ウィリー』（1928年）／『トムとジェリー』 [知識]"]]},{"g":"音楽","n":"既成曲の使用（Needle drop）","b":[["聞こえ方","その作品のために書いた曲ではなく、すでにある有名な曲が流れます。"],["作り方","曲の「サビの頭」や「歌い出し」を、絵の一番の瞬間に合わせて逆算して入れます。曲に合わせて絵のカットを拍で切ります。実際に使うには曲の権利の許可が要ります。"],["使いどころ","時代を伝える、人物の好みを伝える、観客の思い出を借りる。歌詞と台詞がぶつかると両方聞こえません。"],["例","『2001年宇宙の旅』（1968年）宇宙船の動きにワルツ／『ガーディアンズ・オブ・ギャラクシー』（2014年）主人公のカセットの曲 [知識]"]]},{"g":"音楽","n":"対位法（絵と逆の音楽）（Contrapuntal music / soundtrack dissonance）","b":[["聞こえ方","ひどい・悲しい場面に、明るく陽気な曲が流れます。"],["作り方","場面の気持ちと正反対の曲を選び、音量を下げず堂々と流します。曲は場面の中の音（ラジオなど）にすると、より冷たく感じます。"],["使いどころ","皮肉、狂気、世界の無関心。何度も使うと効かなくなります（1作品1〜2回 [意見]）。"],["例","『時計じかけのオレンジ』（1971年）陽気な歌を歌いながらの暴力／『新世紀エヴァンゲリオン劇場版 Air/まごころを、君に』（1997年）世界の終わりに明るい歌 [知識]"]]},{"g":"音楽","n":"スティンガー（驚かせる一音）（Stinger）","b":[["聞こえ方","急に鳴る、短くて大きい和音や効果音。"],["作り方","0.2〜1秒の強い音（高い弦のきしみ、低い一打、金管）を、驚かせる絵と同じコマか1コマ前に置きます。直前の0.5〜2秒を静かにすると差で大きく聞こえます。"],["使いどころ","ホラーの驚かし、どんでん返しの瞬間、コメディの「ガーン」。多用すると観客が身構えて効かなくなります。"],["例","『サイコ』（1960年）シャワーの場面の、刺すような弦 [知識]"]]},{"g":"音楽","n":"＋ドローン（持続する低い音）（Drone）","b":[["聞こえ方","旋律のない低い音が、長くうなり続けます。"],["作り方","40〜120Hzの音（低い弦、シンセ）を長くのばし、ごくゆっくり音量や高さを揺らします。場面の進みに合わせて少しずつ大きくします。"],["使いどころ","不安、何かが起きる前。旋律が無いので、気づかれずに気持ちだけ動かせます。小さいスピーカー（スマホ）では聞こえにくいので、少し高い音も重ねます。"],["例","『ボーダーライン』（2015年）低くうなり続ける音楽 [知識]"]]},{"g":"音楽","n":"＋ダッキング（声の時だけ曲を下げる）（Ducking）","b":[["聞こえ方","誰かが話し始めると曲がすっと下がり、話し終わると戻ります。"],["作り方","声がある間だけ曲を8〜12dB下げます。下げるのは0.1〜0.2秒、戻すのは0.3〜0.6秒。自動なら「サイドチェーン」（声を合図に曲を圧縮する仕組み。ffmpegなら sidechaincompress）。"],["使いどころ","語り＋曲の動画すべて。YouTubeなら全体の大きさは−14LUFS前後が目安です [知識]。"],["例","なし"]]},{"g":"演出","n":"無音（Silence）","b":[["聞こえ方","それまであった音が消え、何も（またはごく小さな音しか）聞こえなくなります。"],["作り方","大事な瞬間の直前か、その瞬間に、曲と効果音を一気に切ります（0.5〜3秒）。本当の0にせず、ごく小さいルームトーンか低い音を残します。無音の後に大きな音を戻すと衝撃が倍になります。"],["使いどころ","衝撃、死、決断、宇宙。まわりがにぎやかなほど効きます。長すぎると故障だと思われます。"],["例","『2001年宇宙の旅』（1968年）宇宙の場面の無音／『スター・ウォーズ／最後のジェダイ』（2017年）艦が体当たりする瞬間の無音 [知識]"]]},{"g":"演出","n":"音の遠近（Sound perspective）","b":[["聞こえ方","近い物は大きくはっきり、遠い物は小さくぼんやり響いて聞こえます。"],["作り方","遠くするほど (1) 音量を下げる（距離が2倍で約6dB）(2) 高音を削る (3) 響きの割合を増やす。カメラが寄ったら音も寄せるのが基本ですが、遠景のまま声だけ近く聞かせる手もあります。"],["使いどころ","全部の場面。絵が遠いのに音が近いと「望遠でのぞいている」感じ、絵も音も遠いと「置いていかれた」感じになります。"],["例","なし"]]},{"g":"演出","n":"こもらせる（水中・壁ごし）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","人物の耳で聞いている（主観の音）ことを示します。水に入る、気を失う、ショックを受けた瞬間に高音を削り（400〜800Hzより上を切る）、我に返る時に一気に戻します。"],["例","『プライベート・ライアン』（1998年）海に沈んだ時と砲撃の直後／『サウンド・オブ・メタル』（2019年）聴力を失っていく主人公の聞こえ方 [知識]"]]},{"g":"演出","n":"爆発後の耳鳴り（Tinnitus ringing）","b":[["聞こえ方","爆発の後、「キーン」という高い音だけが残り、ほかの音は遠くこもります。"],["作り方","爆発の直後に (1) 3,000〜6,000Hzの細い音を入れ、3〜6秒かけて消す (2) ほかの音は高音を削って（300〜500Hzより上を切る）10dB以上下げる (3) 耳鳴りが消えるのに合わせて元に戻す。絵はスローと手ぶれを合わせます。"],["使いどころ","爆発、殴られた直後、強いショック。観客を人物の頭の中に入れます。"],["例","『プライベート・ライアン』（1998年）上陸の場面で主人公の音が遠のく [知識]"]]},{"g":"演出","n":"心臓の音（Heartbeat）","b":[["聞こえ方","「ドッ・ドッ」という低い2連の音が、一定の間隔でくり返します。"],["作り方","50〜80Hzの短い低音を2つ、0.25〜0.3秒あけて鳴らし、これを1拍とします。落ち着き＝1分60回、緊張＝100〜140回。場面が進むにつれて少しずつ速くします。ほかの音を下げると「自分の鼓動しか聞こえない」になります。"],["使いどころ","隠れている、待っている、決断の直前。分かりやすい分、使いすぎると古く感じます。"],["例","なし"]]},{"g":"演出","n":"シェパードトーン（上がり続ける音）（Shepard tone）","b":[["聞こえ方","音がずっと上がり続けているのに、いつまでも高くなりきらない、不思議な音です。"],["作り方","1オクターブずつ離れた音を8〜10個重ね、全部を同時にゆっくり上げます（1オクターブ上がるのに10〜20秒）。一番高い音は消えていき、一番低い音が小さく入ってくるように、音量を「真ん中が大きい山の形」にします。これをくり返すと切れ目が分かりません。"],["使いどころ","終わらない緊張、時間切れ。長く使えますが、聞き疲れします。"],["例","『ダンケルク』（2017年）音楽全体に使われている／『ダークナイト』（2008年）バイクの加速音 [知識]"]]},{"g":"演出","n":"ライザー","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","予告編で、題名や暗転の直前の2〜8秒に使います。上がりきった所で無音を0.2〜0.5秒はさむと、次の一打が強くなります。"],["例","なし"]]},{"g":"演出","n":"インパクト","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","題字、暗転、カットの切れ目に置く「ドン」。予告編の定番です。"],["例","『インセプション』（2010年）の予告で広まった、低い金管の長い一撃 [知識]"]]},{"g":"演出","n":"ドップラー（Doppler effect）","b":[["聞こえ方","近づく車やサイレンの音が高く、通りすぎた瞬間に低く変わります。"],["作り方","通りすぎる瞬間に音の高さを下げます。時速100kmなら、近づく時は約＋1.5半音、遠ざかる時は約−1.4半音（合わせて約3半音の落差）[知識・計算]。同時に音量を山の形（近づいて大きく、離れて小さく）にし、左右に振ります。"],["使いどころ","車、飛行機、弾、カメラの横を物が通る場面すべて。速さが音だけで伝わります。"],["例","なし（乗り物が横切る場面全般）"]]},{"g":"演出","n":"残響で広さを出す","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","場所の大きさを音で伝えます。響きの長さの目安は、小部屋0.3〜0.6秒、ホール1.5〜2.5秒、大聖堂や洞窟4〜8秒。夢や回想は実際より長い響きを付けます。"],["例","なし"]]},{"g":"演出","n":"現実より大きい音（Hyper-real sound）","b":[["聞こえ方","パンチ、刀、足音、布の音などが、本物よりずっと大きく太く聞こえます。"],["作り方","1つの音を「低い音（60〜100Hzの重さ）＋中の音（本体）＋高い音（鋭い当たり）」の3層で重ねます。別の物の音を混ぜると強くなります（パンチに肉をたたく音や動物の声など）。当たるコマにぴったり置きます。"],["使いどころ","アクション、料理、ASMR風の動画。本物の殴る音は小さくて地味なので、映画ではほぼ必ず作り物です。"],["例","『レイジング・ブル』（1980年）パンチに動物の声などを重ねている／『レイダース／失われたアーク《聖櫃》』（1981年）殴る音 [知識]"]]},{"g":"演出","n":"レコードの針が飛ぶ音（Record scratch）","b":[["聞こえ方","流れていた曲が「ギュッ」という音で急に止まります。"],["作り方","針の音（0.3〜0.5秒）と同じコマで曲を完全に切り、絵を止めるか、全員が振り向く絵にします。その後0.5〜1秒の無音。"],["使いどころ","空気が凍る瞬間、場違いな発言の笑い。止め絵＋語りと組み合わせた型はネットで定番の冗談になっています。"],["例","針の音＋止め絵＋語りの「元になった1本」は特定されていません。型としてネットで広まったのは2015年ごろからです [確認]。似た使い方の例として『穴／HOLES』（2003年）が挙げられています [確認・紹介記事による。Claudeは未視聴]"]]},{"g":"演出","n":"左右に振る","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","台詞は基本ずっと中央に置き、振るのは効果音・環境音・音楽です。画面の左から右へ動く物は、音も同じ向きに動かします。"],["例","なし"]]},{"g":"演出","n":"＋音を一気に切る（カットアウト）（Hard cut to silence）","b":[["聞こえ方","大きな音や曲が、余韻なしでぶつ切りに終わります。"],["作り方","消えていく処理（フェード）を付けず、絵のカットと同じコマで切ります。次の場面は静かな環境音から始めます。"],["使いどころ","夢から覚める、笑いのオチ、暴力の直後。差が大きいほど効きます。"],["例","なし"]]},{"g":"演出","n":"＋ウィルヘルムの叫び（Wilhelm scream）","b":[["聞こえ方","決まった1つの男の悲鳴。多くの映画で同じ録音が使い回されています。"],["作り方","昔の録音素材を、人が落ちる・吹き飛ぶ場面に入れます。音の作り手の内輪の遊びです。"],["使いどころ","気づく人だけが笑う小ネタ。真剣な場面では使いません。"],["例","『スター・ウォーズ』（1977年）ほか多数の作品 [知識]"]]}],"14":[{"g":"動きの原則","n":"つぶしと伸ばし（Squash and stretch）","b":[["見え方","ぶつかるとつぶれ、速く動くと伸びます。やわらかさと重さが出ます。"],["作り方","紙では、体積が同じに見えるよう、縦を縮めたら横を広げて描きます。このMacでは、縦の倍率を s にしたら横を 1/s にします（Pillow の resize、Blenderならスケールの Z と X・Y を逆に動かす）。接地の瞬間1〜2コマだけつぶします。"],["使いどころ","ボール、ほっぺ、ギャグ。硬い物（鉄球）には使いません。"],["例","『ルクソーJr.』（1986）電気スタンドとボール [知識]"]]},{"g":"動きの原則","n":"予備動作（Anticipation）","b":[["見え方","動く直前に、逆の方向へ少し引きます。次に何が起きるかが伝わります。"],["作り方","本番の動きの前に、逆向きの小さな動きを3〜6コマ入れます。このMacでは、Blenderで動き出しの前に逆方向のキーを1つ足すだけです。"],["使いどころ","ジャンプ、殴る、走り出す。大きい動きほど長く引きます。不意打ちを見せたい時はわざと抜きます。"],["例","なし"]]},{"g":"動きの原則","n":"見せ場の構図（Staging）","b":[["見え方","何が起きているかが一目で分かります。"],["作り方","1カットで伝えることを1つに絞り、ポーズを黒く塗りつぶした影（シルエット）だけで読めるようにします。このMacでは、Pillow でキャラを真っ黒に塗って、動作が読めるか確かめます。"],["使いどころ","すべてのカット。同時に2か所を動かすと目が迷います。"],["例","なし"]]},{"g":"動きの原則","n":"流し描きとポーズ描き（Straight ahead／Pose to pose）","b":[["見え方","流し描きは勢いと予想外の動き、ポーズ描きは狙った形とタイミングになります。"],["作り方","流し描きは1枚目から順に描き進めます。ポーズ描きは要の絵（原画）を先に決め、間を埋めます。このMacでは、Blenderのキーフレームがポーズ描き、物理の計算（布・火・粒子）が流し描きに当たります。"],["使いどころ","火・水・煙・髪は流し描き、芝居とアクションの骨組みはポーズ描き。両方を混ぜるのが普通です。"],["例","なし"]]},{"g":"動きの原則","n":"あとから付いてくる動き（Follow through／Overlapping action）","b":[["見え方","体が止まっても髪・服・しっぽが遅れて動き、行きすぎて戻ります。"],["作り方","体の先（頭→髪、腕→手→指）ほど、動きを2〜4コマ遅らせます。このMacでは、Blenderで子の骨のキーを数コマ後ろへずらすか、揺れ物に物理（布・ばね）を使います。"],["使いどころ","止まる動作、振り向き。全部が同時に止まるとロボットに見えます。"],["例","なし"]]},{"g":"動きの原則","n":"ゆっくり入りゆっくり出る（Slow in and slow out）","b":[["見え方","動き始めと終わりがなめらかで、真ん中が速くなります。"],["作り方","始めと終わりの近くに絵を多く、真ん中を少なく描きます。このMacでは、進み具合 t（0〜1）を t*t*(3-2*t) に通します。Blenderのキーは最初からこの形（ベジェ）です。"],["使いどころ","生き物のほぼすべての動き。機械や弾は一定の速さ（リニア）のほうが合います。日本の言い方は下の「タメとツメ」です。"],["例","なし"]]},{"g":"動きの原則","n":"弧（Arcs）","b":[["見え方","手や頭が直線でなく、ゆるい弧を描いて動きます。"],["作り方","動く先端の通り道を線で引き、弧からはみ出た絵を直します。このMacでは、Blenderの Motion Paths（動いた道を線で見せる機能）で先端の軌道を見て、角ばった所を直します。"],["使いどころ","腕の振り、首の動き。直線の動きは機械的に見えます。"],["例","なし"]]},{"g":"動きの原則","n":"副次的な動き（Secondary action）","b":[["見え方","主な動きに小さな動きが添えられ、気持ちが伝わります（歩きながら頭をかく、など）。"],["作り方","主な動きを先に完成させ、邪魔しない小さな動きを後から足します。このMacでも同じ順番で、主な動きのキーを固めてから別の骨に足します。"],["使いどころ","性格づけ。主な動きより目立つと失敗です。"],["例","なし"]]},{"g":"動きの原則","n":"タイミング（Timing）","b":[["見え方","同じ動きでも、コマ数で重さ・速さ・気持ちが変わります。"],["作り方","動きに何コマ使うかを決めます（24コマ＝1秒）。このMacでは、Blenderでキーの間隔を伸び縮みさせて見比べます。ffmpeg setpts で全体の速さだけ変えるのは別物で、間隔の配分は変わりません。"],["使いどころ","重い物は長く、軽い物は短く。迷ったら、まず半分のコマ数と倍のコマ数を試します。"],["例","なし"]]},{"g":"動きの原則","n":"誇張（Exaggeration）","b":[["見え方","本物より大げさで、かえって本物らしく感じます。"],["作り方","ポーズ・表情・動きの幅を、正しいと思う量の1.5〜2倍にします。このMacでは、Blenderでキーの値を中心から何倍かに広げます（グラフエディターで拡大）。"],["使いどころ","驚き、怒り、ギャグ。静かな芝居では控えます。"],["例","なし"]]},{"g":"動きの原則","n":"立体感（Solid drawing）","b":[["見え方","平らな絵なのに、厚みと重さのある体に見えます。"],["作り方","体を箱・筒・球の組み合わせで考え、左右対称の「双子の手足」を避けます。このMacでは、Blenderの簡単な人形を回して、どの角度の絵がどうなるかの手本にします（めぐろちゃんや human-3d と同じ使い方）。"],["使いどころ","振り向き、回り込み作画の土台。"],["例","なし"]]},{"g":"動きの原則","n":"魅力（Appeal）","b":[["見え方","見ていたくなる形と動き。かわいいだけでなく、悪役の魅力も含みます。"],["作り方","形を単純にし、大きい・小さい、直線・曲線の差をはっきり付けます。このMacでは、影（シルエット）にして形の読みやすさを確かめるのが手軽です。"],["使いどころ","キャラの設計の段階。細部を足す前に形を決めます。感覚で決まる部分なので、数字では確かめきれません。"],["例","なし"]]},{"g":"日本の作画","n":"コマ打ち（1コマ・2コマ・3コマ）","b":[["見え方","1コマ打ちはぬるぬる、2コマ打ちは普通、3コマ打ちは少しカクカクしてキレがあります。"],["作り方","映像は1秒24コマ。同じ絵を1コマだけ映すのが1コマ打ち（1秒24枚）、2コマずつが2コマ打ち（12枚）、3コマずつが3コマ打ち（8枚）。日本のテレビアニメは3コマ打ちが基本です。このMacでは、ffmpeg fps=8,fps=24 で「8枚を24コマに引き延ばす」＝3コマ打ちの見え方になります。Blenderなら補間を Constant にして3コマごとにキーを打ちます。"],["使いどころ","速い動き・カメラが大きく動く所は1コマ、芝居は2〜3コマ。途中で混ぜて緩急を付けます。"],["例","『スパイダーマン：スパイダーバース』（2018）主人公のコマ打ちが成長につれて変わる [知識]"]]},{"g":"日本の作画","n":"リミテッド（Limited animation）","b":[["見え方","動く所が少なく、止まった絵と口・目だけの動きが多くなります。"],["作り方","体は止め絵にして口だけ・目だけ別のセル（層）で動かし、同じ絵を使い回し、絵を引いて動かします。このMacでは、Pillow で口と目だけ別の PNG にして数枚を切り替えます。"],["使いどころ","会話、予算と時間が無い時。止め絵の力（構図・色・間）がそのまま見えます。"],["例","『鉄腕アトム』（1963）毎週放送のために枚数を減らす方法を広めた [知識]"]]},{"g":"日本の作画","n":"オバケ（スミア／Smear）","b":[["見え方","速い動きの途中の1コマだけ、手が何本もある・体が伸びている変な絵が入ります。普通の速さで見ると「速い」としか感じません。"],["作り方","始めと終わりの絵の間に、動きの道すじ全体をなぞるように伸ばした絵・ばらけた絵を1〜2コマ描きます。このMacでは、Pillow で動かす部分を進む向きに引き伸ばすか、3〜4個ずらして重ねた絵を1コマだけ入れます。"],["使いどころ","振り向き、パンチ、剣の振り。3コマ以上続けると見えてしまいます。"],["例","『ドーバー・ボーイズ』（1942）人物が伸びて次のポーズへ飛ぶ [知識]"]]},{"g":"日本の作画","n":"インパクトフレーム","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["アニメでの使い方","殴った・爆発した瞬間に、白黒反転や荒い線の絵を1〜2コマ入れます。当たる直前に入れると溜め、当たった瞬間に入れると衝撃になります。1話に何度も使うと効かなくなります。"]]},{"g":"日本の作画","n":"金田パース（かなだパース）","b":[["見え方","手前の手や足が画面いっぱいに大きく、体は奥へ急に小さくなる、極端な遠近のポーズ。ひじやひざを張った独特の構えになります。"],["作り方","アニメーター金田伊功（かなだ よしのり）の描き方で、「大胆に誇張された遠近感とポージング」と説明されます [確認]。広角・魚眼レンズで見たような絵を、中割りを省いた速い動きと合わせます [確認]。このMacでは、Blenderでカメラの焦点距離を 12〜18mm にし、手や武器をカメラのすぐ前に突き出すと近い絵になります。そこからさらに手前を1.2〜1.5倍に描き足すのがコツです。"],["使いどころ","ロボットやヒーローの決めポーズ、飛びかかる瞬間。静かな芝居には合いません。"],["例","『半熟英雄 対 3D』（2003、ゲーム）のオープニング [確認]／『銀河旋風ブライガー』（1981）のオープニング [知識]"]]},{"g":"日本の作画","n":"金田光り（かなだびかり）","b":[["見え方","爆発や光源の周りに、丸・多角形・十字の光が飛び散る、絵として形の決まった光。"],["作り方","実写でレンズに逆光が入った時に出る光の玉（ゴースト）を、絵の表現として取り入れたものです [確認]。このMacでは、Pillow で光源から画面中心を通る線の上に、大きさの違う丸や多角形を並べ、ぼかさずくっきり描いて足し算で重ねます。1コマごとに形と位置を変えるとそれらしくなります。"],["使いどころ","爆発、ビーム、変身。写実的なフレア（下の撮影処理）と違い、形のおもしろさを見せます。"],["例","『半熟英雄 対 3D』（2003、ゲーム）のオープニング [確認]"]]},{"g":"日本の作画","n":"板野サーカス（いたのサーカス）","b":[["見え方","たくさんのミサイルが、それぞれ別の曲がった道を煙の糸を引いて飛び、追われる機体がその間をすり抜け、カメラも一緒に飛び回ります。"],["作り方","アニメーター板野一郎の空中戦の描き方です [知識]。ミサイル1本ずつに違う道と速さを与え、カメラを機体に付けて背景ごと回します。このMacでは、Blenderで20〜50個の小さな物に、ゴールへ向かう曲線の道（乱数で少しずつ曲げる）を与え、粒子の煙を引かせ、カメラを機体の子にして追わせます。"],["使いどころ","空中戦の見せ場。全部が同じ動きだと花火になるので、数本だけ遅らせる・外すのが肝心です。"],["例","『超時空要塞マクロス』（1982）、『超時空要塞マクロス 愛・おぼえていますか』（1984）の空中戦 [知識]"]]},{"g":"日本の作画","n":"背動（はいどう／背景動画）","b":[["見え方","背景そのものが絵として描かれて動くので、カメラが地面すれすれを飛んだり、曲がり角を回ったりできます。"],["作り方","ふつう背景は1枚の絵で止まっていますが、背動では背景も線で描いてコマごとに動かします。枚数と手間が非常にかかります。このMacでは、Blenderで箱の街の中をカメラで飛び、線だけ（Freestyle やグリースペンシルの Line Art）で書き出すと下絵になります。今のアニメも3Dの背景を下敷きにすることが多いです。"],["使いどころ","追いかけ、落下、主観の絵。数秒で十分に効きます。"],["例","『NARUTO -ナルト-』第133話（2005）の戦い [知識・未確認]"]]},{"g":"日本の作画","n":"回り込み作画（まわりこみ）","b":[["見え方","カメラが人物の周りをぐるっと回るように、人物も背景も角度が変わっていきます。"],["作り方","回り込みは「カメラが被写体を捉えたまま、その周囲を移動すること」です [確認]。作画では、角度の違う絵を1枚ずつ描くので、立体を正しくつかむ力が要ります。このMacでは、Blenderの人形の周りでカメラを回し、8〜12コマ/秒で書き出して下絵にします。"],["使いどころ","決めの瞬間、二人の関係が変わる瞬間。背景も回すと背動になり、手間が倍になります。"],["例","『うる星やつら2 ビューティフル・ドリーマー』（1984）喫茶店で話す二人の周りを回る長いカット [知識・未確認]"]]},{"g":"日本の作画","n":"ウェブ系作画（Web系）","b":[["見え方","線が少なく影もあっさり、形は崩れてもよく、動きの間隔とタイミングがとても気持ちいい作画。"],["作り方","2000年代に、ネットで自作アニメを発表していた人たちがプロの現場に入って広まった作風です [知識]。パソコンで直接描き、中割りに任せず動きの絵をほぼ全部自分で描き、すぐ再生して間隔を直します。このMacでは、Krita のアニメ機能（タイムラインと前後の絵を透かす機能）で3コマ打ちで描き、その場で再生して直す、がまさにこの作り方です。"],["使いどころ","アクション、走り、感情が爆発する芝居。絵柄が設定からずれるので、好みが分かれます。"],["例","『鉄腕バーディー DECODE:02』（2009）第7話 [知識]"]]},{"g":"日本の作画","n":"止め絵・ハーモニー（出崎統）","b":[["見え方","決めの瞬間に動きが止まり、絵画のように塗り込まれた1枚絵になります。"],["作り方","ハーモニーは、背景のような筆のタッチで塗った絵に、線だけのセルを重ねた1枚絵です。回想・決めの場面・CM前・ラストカットで多く使われます [確認]。このMacでは、最後のコマを Pillow で取り出し、線を残したまま色の面に筆のむらの紙の質感（テクスチャ）を乗算し、ffmpeg -loop 1 で2〜3秒止めます。ゆっくり T.B（引き）を付けると定番の形です。"],["使いどころ","話の終わり、勝負が決まった瞬間。1話に1〜2回。"],["例","『あしたのジョー2』（1980〜81）最終回の最後の絵 [知識]"]]},{"g":"日本の作画","n":"3回パン（さんかいパン／繰り返しショット）","b":[["見え方","同じ絵に向かうカメラの動き（PANや寄り）が、続けて3回くり返されます。"],["作り方","監督 出崎統の手法で、印象づけたい大事な画面を複数回くり返して見せます。3回が圧倒的に多いです [確認]。このMacでは、同じ絵に対する「引きや寄り」の短い動画（各0.7〜1秒）を作り、ffmpeg concat で3回つなぎます。3回目だけ少し長く止めると締まります。"],["使いどころ","大事な人物の登場、衝撃の瞬間。話の中で1回だけ。"],["例","『エースをねらえ！』（1973、テレビ版）第1話のコーチ登場の場面で初めて使われた [確認]"]]},{"g":"日本の作画","n":"口パク（くちパク）","b":[["見え方","台詞に合わせて口だけが開け閉めします。"],["作り方","日本では口の絵は3枚（閉じ・中・開き）が基本で、絵を先に作り、声を後から合わせます（アフレコ）。アメリカは声を先に録り、音ごとの口の形を描きます（プレスコ）[知識]。このMacでは、声の音量を numpy で測り（しきい値2つで3段階に分ける）、3枚の口の PNG を切り替えます。"],["使いどころ","会話。大事な台詞では口を映さない（背中・手・目だけ）という逃げ方も演出になります。"],["例","『AKIRA』（1988）声を先に録って口の形を合わせた [知識]"]]},{"g":"日本の作画","n":"バンク（使い回し）","b":[["見え方","変身・合体・必殺技など、毎回同じ映像が流れます。"],["作り方","手間をかけた1本を作って保存（銀行＝バンク）し、毎話そのまま使います。このMacでは、1本の動画を作っておき、ffmpeg concat で差し込むだけです。背景や色だけ変える手もあります。"],["使いどころ","お約束の見せ場。節約でもあり、「来た！」という待ち遠しさにもなります。"],["例","『美少女戦士セーラームーン』（1992）変身の場面 [知識]"]]},{"g":"日本の作画","n":"ロトスコープ（アニメでの意味）","b":[["見え方","人の動きが生々しく、細かな重心の移動まで出ます。少し不気味に感じることもあります。"],["作り方","実写の映像を1コマずつなぞって絵にします（VFXでの「切り抜き」の意味は 技法11_VFX）。このMacでは、ffmpeg で動画を 8〜12コマ/秒の連番画像にし、Krita で下に敷いてなぞります。全部なぞらず、要のポーズだけ拾うと自然になります。"],["使いどころ","踊り、楽器の演奏、リアルな芝居。なぞっただけだと絵の魅力が消えます。"],["例","『惡の華』（2013）全編 [知識]／『白雪姫』（1937）実写を手本にした人物の動き [知識]"]]},{"g":"画面の記号","n":"スピード線","b":[["見え方","動く向きに沿った平行な線。物が速く動いている、または背景が流れていると感じます。"],["作り方","動きの向きに平行な線を、長さと太さをばらして描きます。背景全体を線にすることもあります（流線背景）。このMacでは、Pillow で乱数の位置に細長い線を描き、1コマごとに位置を変えます。2〜3枚のくり返しで足ります。"],["使いどころ","走り、突進。集中線 ✓ は中心に向かう線、スピード線は平行、と使い分けます。"],["例","なし"]]},{"g":"画面の記号","n":"集中線","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["アニメでの使い方","驚き・気づき・決め台詞の瞬間に、顔や物へ目を集めます。中心を少しずらすと動きが出ます。"]]},{"g":"画面の記号","n":"残像","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["アニメでの使い方","速すぎて見えない動き、分身。半透明の前の絵を2〜3枚残します。オバケ（1コマの変な絵）より長く見せたい時に使います。"]]},{"g":"画面の記号","n":"画面動（揺れ）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["アニメでの使い方","爆発・着地・怒鳴り声で画面全体を揺らします。撮影の段階で足すのが普通です [確認]。揺れ幅は始めが大きく、数コマで小さくします。"]]},{"g":"画面の記号","n":"カットイン","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["アニメでの使い方","必殺技の前に、目元や顔の帯が画面を横切って入ります。対決の二人を上下に並べる形も定番です。"]]},{"g":"画面の記号","n":"イメージ背景","b":[["見え方","その場所の背景が消え、色・花・稲妻・渦・光の粒など、気持ちを表す模様になります。"],["作り方","実際の場所の背景を外し、気持ちに合う色と模様の絵に差し替えます。このMacでは、Pillow でグラデーション＋ぼかした光の丸を描き、ゆっくり流します。"],["使いどころ","ときめき、ショック、怒り、ギャグの落ち込み。現実の場面へ戻るカットとセットで使います。"],["例","『少女革命ウテナ』（1997）人物の周りに薔薇が入る画面 [知識]"]]},{"g":"画面の記号","n":"劇画タッチ","b":[["見え方","急に線が太く荒くなり、影が斜めの線でびっしり入った、濃い絵になります。"],["作り方","影を色でなく線（斜線・かすれ）で描き、顔の彫りを深くします。このMacでは、Pillow で画像の暗い所に斜めの線の模様を乗算し、輪郭を太らせます（ImageFilter.MinFilter）。"],["使いどころ","本気の瞬間、またはギャグ（どうでもいい事で急に濃い顔になる）。"],["例","『北斗の拳』（1984）[知識]"]]},{"g":"画面の記号","n":"目のハイライト","b":[["見え方","瞳の中の白い光。あると生き生き、消すとうつろ、揺らすと動揺や涙になります。"],["作り方","瞳に白い点を1〜2個描きます。消す・大きくする・小刻みに揺らすで気持ちを変えます。このMacでは、瞳のハイライトだけ別の PNG にして、出す・消す・1〜2ピクセル揺らすを切り替えます。"],["使いどころ","絶望・洗脳（消す）、感動（増やして揺らす）。小さいのに効き目がとても大きい記号です。"],["例","なし"]]},{"g":"画面の記号","n":"シャフ度（シャフト角度）","b":[["見え方","キャラが、あごを上げ気味に首を大きくかしげて、肩ごしに振り向きます。"],["作り方","制作会社シャフトの作品でよく見るポーズから、ファンが付けた呼び名です [知識]。体は向こう向き、首だけ反らしてこちらを見る絵を描きます。このMacでは、Blenderの人形で首を後ろに反らし、横にかしげ、カメラを少し下から置くと近い形になります。本物の人には苦しい角度まで誇張します。"],["使いどころ","意味ありげな台詞、挑発。同じ作品で何度も使うと作品の「くせ」になります。"],["例","『化物語』（2009）[知識]"]]},{"g":"撮影処理","n":"透過光（とうかこう／T光）","b":[["見え方","ビーム、魔法、太陽、目の光などが、絵の具の色ではなく本当に光って見えます。"],["作り方","セルの時代は、黒い紙に穴を開けて下から光を当て、その光を直接カメラに写し込みました [確認]。線・帯・丸・点の形で使います [確認]。このMacでは、光らせたい形を白で描いた絵を、ffmpeg gblur でぼかして色を付け、blend=all_mode=screen（足し算系）で重ねます。芯は白のまま、ぼかした外側だけに色を付けます。"],["使いどころ","光る物すべて。画面じゅうを光らせると白く飛んで何も見えません。"],["例","『機動戦士ガンダム』（1979）ビームの光 [知識]"]]},{"g":"撮影処理","n":"入射光（にゅうしゃこう）","b":[["見え方","画面の外から、光の帯が斜めに差し込みます。"],["作り方","画面に光が差し込んだように見せる手法で、出崎統が映画『イージー・ライダー』の夕日の場面から思いついたものです [確認]。このMacでは、Pillow で画面の隅から斜めに広がる白〜黄色の帯（先へ行くほど透明）を描き、screen で重ねます。帯をゆっくり動かすと生きます。"],["使いどころ","朝、夕方、回想、決意の瞬間。光の来る向きは場面の中でそろえます。"],["例","出崎統の監督作品（『あしたのジョー2』など）[知識]"]]},{"g":"撮影処理","n":"パラ（色のかぶせ／パラフィン）","b":[["見え方","画面の端や半分に、暗い色や夕焼けの色がグラデーションでかかります。"],["作り方","もとは、色つきの透明なパラフィン紙をレンズの前に置いて画面の端に影を作りました。暗い場面は青や紫、夕方は赤やオレンジです [確認]。今は合成の時にグラデーションの素材を重ねます [確認]。このMacでは、Pillow で「色→透明」のグラデーションを作り、暗い色は乗算、明るい色は screen で重ねます。"],["使いどころ","時刻と気分を一手で変える、目を引きたい所以外を沈める。ほぼ全カットに薄く入っています。"],["例","出崎統の監督作品で舞台のスポットライトのように使われた [確認]"]]},{"g":"撮影処理","n":"フレア（Lens flare）","b":[["見え方","強い光の周りがにじみ、光の筋や丸い光の玉が画面に出ます。"],["作り方","実写のレンズで起きる光のにじみを、合成で足します。このMacでは、Blenderのコンポジターの Glare（Streaks＝筋、Ghosts＝玉、Fog Glow＝にじみ）を使います。ffmpeg だけなら、明るい所だけ取り出して大きくぼかし screen で戻します。"],["使いどころ","逆光、まぶしさ、夏。絵としての形を楽しむ「金田光り」とは目的が違い、こちらは実写らしさを足します。"],["例","『君の名は。』（2016）逆光の場面 [知識]"]]},{"g":"撮影処理","n":"ディフュージョン（ふんわり）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["アニメでの使い方","絵全体をぼかした物を薄く重ね、光に包まれた感じにします [確認]。回想・美少女・朝の光に。かけすぎると眠い絵になるので、線が読める所で止めます。"]]},{"g":"撮影処理","n":"波ガラス（なみガラス）","b":[["見え方","画面がゆらゆらと波打ちます。陽炎、水中、熱。"],["作り方","熱などによる空気のゆがみを表す処理で、昔は波打ったガラス板を撮影台に置いて動かしたのが名前の由来です [確認]。このMacでは、numpy で行ごとに sin(行×細かさ + 時間) ぶんだけ横にずらします。ffmpeg なら displace に動く波の絵を渡します。"],["使いどころ","夏の道路、炎の向こう、水の中、めまい。ずらす量は数ピクセルで十分です。"],["例","なし"]]},{"g":"撮影処理","n":"マルチプレーン・密着マルチ","b":[["見え方","手前・中・奥が別々の速さで動き、奥行きを感じます。"],["作り方","マルチプレーンは、絵をカメラからの距離を変えた何段ものガラスに置いて撮る台で、手前にピントを合わせると奥がぼけます [確認]。密着マルチは、段を分けずに絵を重ねたまま、それぞれ別の速さで滑らせる方法です [確認]（ぼけは出ません）。このMacでは、層ごとの PNG を ffmpeg overlay=x='-t*速さ' で、手前ほど速く動かします。マルチプレーン風にするなら奥の層だけ gblur を足します。"],["使いどころ","歩き・電車・空の雲。速さの比は、手前3：中2：奥1くらいから始めます。"],["例","『白雪姫』（1937）[確認]／『風車小屋のシンフォニー』（1937）[知識]／日本では持永只仁が多層式の撮影台を作った [確認]"]]},{"g":"撮影処理","n":"ブックの引き","b":[["見え方","手前の木や柱が、キャラの前を横切って流れます。"],["作り方","ブック（BOOK）は、手前の木・地面・岩などを切り抜いて描いた背景の絵です [確認]。キャラより上の層に置き、横に滑らせます（引き）。速さは「1コマあたり何ミリ」で指定します [確認]。このMacでは、切り抜いた PNG をキャラの上に overlay し、背景より速く動かします。"],["使いどころ","のぞき見の構図、奥行き、場面の出入りの目隠し。"],["例","なし"]]},{"g":"撮影処理","n":"Follow（フォロー）","b":[["見え方","走るキャラが画面の同じ場所にいて、背景が後ろへ流れます。"],["作り方","被写体の動きに合わせてカメラを動かし、画面に捉え続けるカメラワークで、「つけ」とも呼ばれます [確認]。作り方としては、キャラをその場で足踏みさせ（くり返しの絵）、背景を逆向きに引きます [知識]。このMacでは、端と端がつながる横長の背景を ffmpeg で横に流し続け、キャラの歩きのくり返しを上に重ねます。"],["使いどころ","歩きながらの会話、走り。少ない枚数で長くもたせられます。"],["例","なし"]]},{"g":"撮影処理","n":"つけPAN（つけパン）","b":[["見え方","キャラが画面の中を実際に移動し、カメラがそれを追って振られます。"],["作り方","大きな背景の上をキャラが動き、撮る枠（フレーム）をキャラに合わせて動かします。Follow との違いは、キャラ自身が絵の上で場所を変えることです [知識]。このMacでは、大きな絵の上にキャラを動かして描き、ffmpeg crop の位置を時間で動かしてキャラを追います。少し遅れて追うと自然です。"],["使いどころ","立ち上がる、部屋を横切る、飛び立つ。Follow より「場所が変わった」感じが出ます。"],["例","なし"]]},{"g":"撮影処理","n":"T.U・T.B（トラックアップ／トラックバック）","b":[["見え方","画面が寄っていく（T.U）、引いていく（T.B）。"],["作り方","実写では台車でカメラを前後に動かすことですが、セルアニメでは合成の時に絵全体を拡大・縮小することを指します [確認]。つまり中身はズームで、手前と奥のずれ（視差）は出ません。このMacでは、ffmpeg zoompan か、Pillow で1コマずつ crop→resize。大きめの絵を用意して、拡大でぼやけないようにします。"],["使いどころ","気づき・緊張（T.U）、孤独・状況の説明（T.B）。奥行きも出したい時は密着マルチと組み合わせます。"],["例","『あしたのジョー2』第46話で14回続けて使われた [確認]"]]},{"g":"撮影処理","n":"撮影ブレ","b":[["見え方","速い動きの絵が進む向きに流れてぼける、または手持ちカメラのように画面が細かく揺れます。"],["作り方","合成の段階で、動いている層に向きのあるぼかしを足したり、画面全体に小さな揺れを足したりします [知識・語の範囲は未確認]。このMacでは、流れるぼかしは ffmpeg tmix=frames=3（前後のコマを混ぜる）か Pillow で横だけのぼかし、小さな揺れは crop の位置を1〜3ピクセル乱数で動かします。"],["使いどころ","スピード感、実写カメラらしさ。大きな衝撃の揺れは「画面動 ✓」のほうです。"],["例","なし"]]},{"g":"撮影処理","n":"被写界深度のぼかし","b":[["見え方","ピントの合った層だけくっきり、手前や奥がぼけます。"],["作り方","合成の時、層ごとにぼかしの強さを変えます。ピントを途中で移すこともできます。このMacでは、層ごとに ffmpeg gblur=sigma=… をかけてから重ねます。Blenderなら層を奥行きに並べ、カメラの Depth of Field を入れます。"],["使いどころ","見せたい人物を浮かせる、実写のような空気。全部のカットに使うと目が疲れます。"],["例","『響け！ユーフォニアム』（2015）[知識]"]]},{"g":"撮影処理","n":"カメラマップ（3D背景）","b":[["見え方","手描きの背景の中へ、カメラが入っていったり回り込んだりします。"],["作り方","背景の絵を、簡単な3Dの形に映して貼り、3Dのカメラで動きます（技法11「カメラ投影」と同じ）。このMacでは、Blenderで背景画に合わせた箱や板を置き、UV Project モディファイアで絵を映します。動かす範囲は少しだけにします。"],["使いどころ","廊下を進む、街を見下ろして飛ぶ。背動を手で描く代わりになります。"],["例","『もののけ姫』（1997）走る場面の背景 [知識・未確認]"]]},{"g":"ほかの方式","n":"切り絵アニメ（Cutout animation）","b":[["見え方","紙を切った人形が、関節で折れて動きます。平らで影絵や絵本のような味になります。"],["作り方","部品（頭・胴・腕・足）を切り分け、台の上で少しずつ動かして1コマずつ撮ります。このMacでは、部品ごとの PNG を Pillow で回転（rotate と回す中心の指定）して貼り重ねます。Blenderなら板に貼って骨で動かします。"],["使いどころ","昔話、影絵、少人数の制作。奥を向く・振り向くが苦手です。"],["例","『アクメッド王子の冒険』（1926）影絵の長編 [確認]／『話の話』（1979）[知識]"]]},{"g":"ほかの方式","n":"コマ撮り（Stop motion）","b":[["見え方","人形や物が1コマずつ動きます。作り方の詳しくは 技法10_特撮 の「コマ撮り」。"],["作り方","1コマ撮っては動かす、のくり返し。このMacでは、スマホの連写を ffmpeg -framerate 12 で動画にします。"],["使いどころ","手ざわりのある世界。羊毛・布・粘土など素材で印象が変わります。"],["例","『PUI PUI モルカー』（2021）[知識]"]]},{"g":"ほかの方式","n":"砂・油絵アニメ","b":[["見え方","絵が溶けるように次の絵へ変わっていきます。前の絵のあとが少し残ります。"],["作り方","下から光を当てたガラスの上に砂や油絵の具を置き、少しずつ描き変えて1コマずつ撮ります。前の絵は残りません。このMacでは、Krita で1枚の絵を上から少しずつ描き変え、そのつど書き出して連番にします。前のコマを薄く残す（ffmpeg tmix）と味が近づきます。"],["使いどころ","記憶、夢、詩。やり直しがきかず、とても時間がかかります。"],["例","『老人と海』（1999）ガラスに油絵 [知識]／『ゴッホ 最期の手紙』（2017）油絵で全編 [知識]"]]},{"g":"ほかの方式","n":"モーションコミック","b":[["見え方","漫画のコマや1枚絵が、少しずつ寄る・ずれる・部品が動く、声と音が付く。"],["作り方","絵を層に分け、ゆっくりした寄り引きと視差、まばたきや口だけの動きを足します。このMacでは、ffmpeg zoompan と層ごとの overlay（2.5次元の視差 ✓）、文字と効果音で作れます。code-short-anime のスキルの平面の作り方がほぼこれです。"],["使いどころ","漫画の宣伝、ショート動画、少ない絵で話を語る時。"],["例","『ウォッチメン』モーションコミック（2008）[知識]"]]},{"g":"ほかの方式","n":"Live2D","b":[["見え方","1枚のイラストが、絵柄のまま、首を振り・まばたきし・息をします。"],["作り方","絵を部品（前髪・目・口・顔など）に分け、部品ごとに網目（メッシュ）を張って変形させ、少しの角度変化を立体のように見せます。このMacでは、Live2D Cubism に無料版があります [知識]。Blenderで真似るなら、部品を板に貼って少しずつ前後にずらし、シェイプキーやラティス（かご型の変形）で曲げます。Pillow の MESH 変形でも、まばたきと首かしげ程度は作れます。"],["使いどころ","VTuber、ゲームの立ち絵、歌の動画。大きく振り向くと絵が破れるので、左右30度くらいまでです。"],["例","『俺の妹がこんなに可愛いわけがない ポータブル』（2011、ゲーム）早い時期の採用例 [知識]"]]},{"g":"足した技法（地図に無かったもの）","n":"タメとツメ","b":[["見え方","動く前にぐっと溜め、動き出すと一気に速く、最後にすっと止まります。"],["作り方","タメ＝動く前や決めの所で絵の間隔を詰めて（または止めて）時間を使うこと、ツメ＝絵と絵の間隔の配分を決めること。原則の「ゆっくり入りゆっくり出る」「予備動作」の日本の現場での言い方です [知識]。このMacでは、Blenderのグラフエディターで曲線の傾きを急にする所・寝かせる所をはっきり分けます。"],["使いどころ","アクションすべて。等間隔の動きは「ぬるい」と言われます。"],["例","なし"]]},{"g":"足した技法（地図に無かったもの）","n":"リピート（くり返し）・なびき","b":[["見え方","歩き・走り・髪や旗のゆれが、数枚の絵のくり返しで続きます。"],["作り方","最後の絵が最初の絵につながるように描きます（歩きは1歩8〜12コマ、なびきは3〜4枚）。このMacでは、ffmpeg -stream_loop -1 でくり返すか、Blenderのキーに Cycles モディファイア（くり返し）を付けます。"],["使いどころ","Follow の歩き、風の中の立ち姿。長く見せるとくり返しに気づかれるので、途中でまばたきなどを足します。"],["例","なし"]]},{"g":"足した技法（地図に無かったもの）","n":"エフェクト作画","b":[["見え方","煙・爆発・炎・水・破片などを、手描きの絵として動かします。形そのものがかっこいいのが特徴です。"],["作り方","煙は「かたまりが回りながら広がる」、破片は「1つずつ回りながら弧を描く」と、形の決まりごとで描きます。このMacでは、Blenderの煙や破片の計算を2〜3コマ打ちで書き出して下絵にし、Krita で形を単純にしてなぞります。"],["使いどころ","爆発、魔法、ロケット。撮影の光（透過光・フレア）と重ねて仕上げます。"],["例","『王立宇宙軍 オネアミスの翼』（1987）ロケット発射ではがれ落ちる氷 [知識]"]]},{"g":"足した技法（地図に無かったもの）","n":"セルルックCG（手描き風の3D）","b":[["見え方","3Dで作っているのに、手描きのアニメのように見えます。"],["作り方","影を2〜3段のはっきりした色に分け（トゥーン）、輪郭線を付け、動きを2〜3コマ打ちにし、顔の影や形を角度ごとに直します。このMacでは、Blenderで Shader to RGB＋ColorRamp（影を段にする）、輪郭は Freestyle か「裏返した一回り大きい殻」、動きは補間 Constant で2コマごとにキーを打ちます（めぐろちゃんなどで使っている方法）。"],["使いどころ","回り込み、ライブ、メカ。なめらかすぎる動き（1コマ打ち）のままだと3Dに見えるので、コマを落とします。"],["例","『スパイダーマン：スパイダーバース』（2018）[知識]／『宝石の国』（2017）[知識]"]]}],"15":[{"g":"語りの仕掛け","n":"主観（POV shot）","b":[["見え方","カメラが人物の目になります。手や体の一部が画面に入り、ほかの人がカメラに向かって話します。"],["作り方","目の高さにカメラを置き、頭の動き（歩きの揺れ、見る向き）をそのままカメラで行います。基本は「見る人の顔 → 見ている物（主観）→ 反応する顔」の3カットで1組です。"],["使いどころ","のぞき、追われる、酔い、ゲーム風。全編主観は顔が見えないので感情移入しにくいと言われます。"],["例","『湖中の女』（1947年）ほぼ全編が主人公の目／『ハードコア』（2015年）全編が一人称のアクション [知識]"]]},{"g":"語りの仕掛け","n":"第四の壁を破る（Breaking the fourth wall）","b":[["見え方","登場人物がカメラ（観客）を見て、話しかけたり目くばせしたりします。"],["作り方","ほかの人物には聞こえていない約束で、人物だけがレンズをまっすぐ見ます。短い一言や一瞬の目線（0.5〜1秒）が一番効きます。"],["使いどころ","コメディ、悪だくみの共有、皮肉。使うなら最初の5分で一度見せて「この作品はこれをやる」と知らせます。"],["例","『フェリスはある朝突然に』（1986年）主人公が観客にずる休みのコツを話す／『デッドプール』（2016年） [知識]"]]},{"g":"語りの仕掛け","n":"夢の場面（Dream sequence）","b":[["見え方","現実と少しずれた世界。場所が急に変わる、物の大きさがおかしい、音がこもる。"],["作り方","(1) 入り口を隠す（普通の場面からそのまま続ける）か、はっきり示す（寄り＋ぼけ＋音が遠のく）かを決める (2) 中では1つだけ現実の決まりを破る（重力、時間、つながらない場所）(3) 出口は急な音かカットで起こす。色や画面比率を変えると見分けやすくなります。"],["使いどころ","人物の恐れや願いを絵で見せる時。「夢でした」で大事な出来事を無かったことにすると観客は怒ります。"],["例","『白い恐怖』（1945年）画家ダリが美術を手がけた夢／『パプリカ』（2006年） [知識]"]]},{"g":"語りの仕掛け","n":"回想","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","入る時は人物の顔への寄りや音の先行で合図し、戻る時は同じ顔に戻します。今の場面と色・粒子・画面比率のどれか1つを変えると迷いません。"],["例","『カサブランカ』（1942年）パリの思い出に入る場面 [知識]"]]},{"g":"語りの仕掛け","n":"冒頭のつかみ（コールドオープン）（Cold open）","b":[["見え方","題名やスタッフ名の前に、いきなり場面が始まります。"],["作り方","説明なしで、動きのある場面か謎を1つ見せます（1〜10分。短い動画なら3〜15秒）。その後に題名を出して、本編を落ち着いて始めます。"],["使いどころ","ほぼ全部の作品。冒頭の場面が本編と無関係すぎると、だまされた気分になります。"],["例","『ダークナイト』（2008年）冒頭の銀行強盗／007シリーズの毎回の冒頭 [知識]"]]},{"g":"語りの仕掛け","n":"止め絵＋語り（Freeze frame + narration）","b":[["見え方","動いている絵が急に止まり、その上で語り手が人物や状況を説明します。"],["作り方","動きの頂点（変な顔、物が当たる直前）で1コマを止め、2〜5秒そのままにします。止めた瞬間に音も切り、語りを入れます。名前の文字を足してもよいです。"],["使いどころ","人物紹介、「どうしてこうなったか」を戻って話す入り口。ネットでは定番の冗談にもなっているので、まじめに使うと古く見えることがあります。"],["例","『グッドフェローズ』（1990年）語りの途中で絵が止まる／『トレインスポッティング』（1996年）仲間の紹介で止まって名前が出る [知識]"]]},{"g":"語りの仕掛け","n":"題字カード（Title card / chapter card）","b":[["見え方","黒い画面などに、章の名前や曜日・時刻の文字だけが出ます。"],["作り方","1〜3秒、文字だけの画面をはさみます。書体・位置・音を毎回同じにします。音は無音か、1つの打撃音。"],["使いどころ","章立て、時間の経過、調子の切り替え。カード自体がリズムを作ります。"],["例","『キル・ビル Vol.1』（2003年）章の題／『シャイニング』（1980年）曜日だけのカードが不安を高める [知識]"]]},{"g":"語りの仕掛け","n":"偽ドキュメンタリー（Mockumentary / found footage）","b":[["見え方","作り話を、本物の記録映像のように撮ります。インタビュー、手持ちカメラ、カメラへの目線。"],["作り方","(1) 手持ちで、起きた事に「遅れて」カメラを向ける（先に構えない）(2) 探るようなズーム (3) 人物が1人でカメラに話す場面をはさむ (4) 照明はその場の光 (5) 画質をわざと落とす。拾った映像型（ファウンドフッテージ）は、登場人物が撮っている設定にします。"],["使いどころ","コメディ（気まずい間）、ホラー（本当らしさ）、予算が少ない時。"],["例","『スパイナル・タップ』（1984年）架空のバンドの記録／『ブレア・ウィッチ・プロジェクト』（1999年）拾った映像型／『シェアハウス・ウィズ・ヴァンパイア』（2014年） [知識]"]]},{"g":"語りの仕掛け","n":"画面だけの映画（スクリーンライフ）（Screenlife）","b":[["見え方","物語の全部が、パソコンやスマホの画面の中（通話、検索、メッセージ）で進みます。"],["作り方","画面録画を素材にし、編集で「寄り」と「移動」を足して見る場所を導きます。気持ちは、打ちかけて消す文字、カーソルの迷い、返信までの間で見せます。"],["使いどころ","捜索・失踪・ネットの怖さ。顔はビデオ通話の窓で見せます。"],["例","『search／サーチ』（2018年）／『アンフレンデッド』（2014年） [知識]"]]},{"g":"語りの仕掛け","n":"ワンカット映画（One-shot film / oner）","b":[["見え方","映画全体（または長い場面）が、一度もカットせずに続いて見えます。"],["作り方","本当に1回で撮るか、つなぎ目を隠します。隠し場所は (1) 暗い所や人の背中で画面が黒くなる瞬間 (2) 柱や壁が横切る瞬間 (3) 速いパンのぶれ。編集で真似るなら、2つのカットの終わりと頭を同じ「黒」や「ぶれ」にして4〜8コマ重ねます。"],["使いどころ","時間切れの緊張、その場にいる感じ。切って時間を飛ばせないので、移動の退屈な所の処理が難しいです。"],["例","『エルミタージュ幻想』（2002年）本当に1カットで約90分／『1917 命をかけた伝令』（2019年）つなぎ目を隠して1本に見せる／『ロープ』（1948年）／『カメラを止めるな！』（2017年）冒頭の約37分 [知識]"]]},{"g":"語りの仕掛け","n":"時間を入れ替える（Nonlinear narrative）","b":[["見え方","出来事が起きた順ではなく、ばらばらの順番や逆の順番で語られます。"],["作り方","(1) まず起きた順に全部を書く (2) 「結果を先に、原因を後に」なる所で並べ替える (3) いつの場面かを、色・髪型・文字・画面比率で見分けられるようにする。"],["使いどころ","謎（なぜこうなった？）で引っぱる時、平凡な話を新しく見せる時。目印が無いと迷子になります。"],["例","『パルプ・フィクション』（1994年）章の順が前後する／『メメント』（2000年）逆の順に進む／『(500)日のサマー』（2009年）日数の数字で行き来する [知識]"]]},{"g":"語りの仕掛け","n":"画面比率の切り替え（Aspect ratio shift）","b":[["見え方","作品の途中で、画面の形（横長・四角）が変わります。"],["作り方","時代・世界・気持ちごとに比率を決めます（例：昔＝四角に近い4:3、今＝横長）。編集で真似るなら、上下か左右の黒い帯を出し入れします。ゆっくり動かす（1〜3秒）と「世界が広がる」、一瞬で切ると「別の世界」に見えます。"],["使いどころ","解放・閉じこめ・時代の区別。回数が多いと効きません。"],["例","『Mommy／マミー』（2014年）真四角の画面を主人公が両手で押し広げる／『グランド・ブダペスト・ホテル』（2014年）時代ごとに比率が違う／『ダークナイト』（2008年）大きな場面だけ画面が広がる [知識]"]]},{"g":"語りの仕掛け","n":"白黒と色の切り替え（Black-and-white / color shift）","b":[["見え方","白黒の世界に色が付く、または一部だけ色が残ります。"],["作り方","世界ごとに白黒と色を分ける。または彩度を0にして、1つの物だけ切り抜いて色を戻す（MADで作った「色だけ残す」と同じ）。切り替える時は、扉を開ける・目を覚ますなどの動きに合わせます。"],["使いどころ","現実と夢、過去と今、客観と主観の区別。1つの物への注目。"],["例","『オズの魔法使』（1939年）扉を開けると色の世界／『シンドラーのリスト』（1993年）白黒の中の赤い服／『カラー・オブ・ハート』（1998年）白黒の町に少しずつ色が付く [知識]"]]},{"g":"語りの仕掛け","n":"ゆっくり見せる（スローリビール）（Slow reveal）","b":[["見え方","大事な物や人を、すぐには全部見せません。影、一部分、音、まわりの反応だけが先に来ます。"],["作り方","(1) 結果や痕跡を先に見せる (2) 一部分（手、足、後ろ姿）(3) まわりの人の顔 (4) 最後に全体、の順。カメラなら、ゆっくり動かして枠に入れる、ピントを移す、光を当てる。"],["使いどころ","怪物、主役の初登場、秘密。待たせた分、最後の絵が期待に負けない必要があります。"],["例","『第三の男』（1949年）暗い戸口に光が当たって顔が見える／『ジョーズ』（1975年）サメを後半まで見せない [知識]"]]},{"g":"語りの仕掛け","n":"リアクションで語る（Reaction shot）","b":[["見え方","すごい物そのものではなく、それを見た人の顔を先に（または代わりに）見せます。"],["作り方","(1) 人物が何かに気づく (2) 顔へゆっくり寄る（1〜3秒）(3) 2人目の顔 (4) やっと対象を見せる。顔の時間が長いほど対象が大きく感じられます。"],["使いどころ","驚き、恐怖、感動。対象を作るお金が無い時にも使えます（顔だけで済ませる）。"],["例","『ジュラシック・パーク』（1993年）初めて恐竜を見る場面で、顔が先に来る [知識]"]]},{"g":"語りの仕掛け","n":"視覚の繰り返し（モチーフ）（Visual motif）","b":[["見え方","同じ物・形・色・構図が、作品の中で何度も出てきます。"],["作り方","主題を表す物を1つ決め（階段、窓、ある色、ある果物）、大事な場面に3回以上置きます。最後に出す時は意味を変えます（同じ構図で人物の立場が逆、など）。"],["使いどころ","言葉で言わずに主題を伝える。2回目に見た人への贈り物にもなります。"],["例","『ゴッドファーザー』（1972年）不吉な事の前に出るオレンジ／『パラサイト 半地下の家族』（2019年）階段 [知識]"]]},{"g":"語りの仕掛け","n":"＋信頼できない語り手（Unreliable narrator）","b":[["見え方","語り手が見せてきた話が、実はうそ・思いこみだったと後で分かります。"],["作り方","語り手の「語りの絵」を事実のように撮っておき、終盤に別の視点の絵で同じ場面を見せ直します。見返すと分かる小さな手がかりを前半に置きます。"],["使いどころ","どんでん返し。手がかり無しでひっくり返すと、ずるいと感じられます。"],["例","『ユージュアル・サスペクツ』（1995年）／『ファイト・クラブ』（1999年） [知識]"]]},{"g":"語りの仕掛け","n":"＋同じ出来事を別の目で（羅生門型）（Rashomon structure）","b":[["見え方","1つの出来事が、人物ごとの言い分で何度も語り直され、毎回中身が違います。"],["作り方","同じ場所・同じ出来事を、語る人ごとに撮り直します。語り手は自分をよく見せるので、演技・カメラの位置・音楽を回ごとに変えます。"],["使いどころ","真実のあいまいさ、裁判、うわさ。3〜4回が限度です。"],["例","『羅生門』（1950年） [知識]"]]},{"g":"語りの仕掛け","n":"＋最初と最後を同じ絵に（ブックエンド）（Bookends）","b":[["見え方","最初の場面と最後の場面が、同じ構図・同じ場所・同じ動きです。"],["作り方","冒頭の絵を控えておき、最後に同じカメラ位置で撮ります。変わった1点（人がいない、表情が違う）だけを違えます。"],["使いどころ","変化を静かに見せる、きれいに閉じる。ショート動画のループにも使えます（→ 技法16_ショート動画の型）。"],["例","『捜索者』（1956年）戸口の枠ごしの絵で始まり、同じ枠で終わる [知識]"]]},{"g":"語りの仕掛け","n":"＋仕込みと回収（Setup and payoff）","b":[["見え方","前半でさりげなく見せた物や一言が、後半で決め手になります。"],["作り方","回収から逆算して、前半に「別の理由で」その物を映します（笑い話、背景の小物）。観客が覚えているが意識していない、を狙います。3回出すなら「紹介・念押し・回収」。"],["使いどころ","全部の物語。回収されない仕込みはごみに、仕込みのない回収はご都合に見えます。"],["例","『バック・トゥ・ザ・フューチャー』（1985年）序盤で受け取る時計台のチラシが後半の鍵になる [知識]"]]},{"g":"語りの仕掛け","n":"＋先の場面を先に見せる（フラッシュフォワード）（Flash-forward）","b":[["見え方","未来の場面が、今の話の途中や冒頭に一瞬はさまります。"],["作り方","回想と同じ作り（色や音を変えて区別）で、時間だけ逆にします。冒頭に結末近くの一場面を見せてから「◯日前」に戻る型が一番使いやすいです。"],["使いどころ","「どうしてそうなる？」で引っぱるつかみ。"],["例","『メッセージ』（2016年） [知識]"]]},{"g":"監督の型","n":"ヒッチコック（めまいショット・机の下の爆弾）","b":[["見え方","観客だけが危険を知っている時間が長く続きます。人物の不安な瞬間に、背景だけがぐにゃりと伸びます。"],["作り方","【机の下の爆弾】(1) 危険物を観客にはっきり見せる (2) 知らない人物たちの普通の会話を長く続ける (3) 途中で危険物と時計に2〜3回切り返す。【めまいショット】カメラを引きながら同じ速さでズームで寄り、人物の大きさを保ったまま背景だけを変える。【視線の3カット】見る顔→見ている物→反応の顔。"],["使いどころ","驚きは一瞬で終わるが、先に知らせた緊張は長く続く、という考え方です。日常の場面ほど効きます。"],["例","『めまい』（1958年）階段を見下ろす場面／『サボタージュ』（1936年）少年が中身を知らずに包みを運ぶ／『裏窓』（1954年）のぞく人と見える物の切り返し [知識]"]]},{"g":"監督の型","n":"キューブリック（一点透視・にらみ）","b":[["見え方","廊下や部屋の線が画面の真ん中の1点に集まる左右対称の絵。人物があごを引き、上目づかいでこちらをにらみます。"],["作り方","(1) カメラを通路の真ん中・壁に平行に置き、広角レンズで撮る (2) 人物を中心に置く (3) 一定の速さでまっすぐ前へ進むか、人物の後ろを付いていく (4) にらみは、頭を少し下げさせて目だけ上げる、下からの光。(5) ゆっくり引いていくズームで人物を風景の中に小さくする。音楽は既成のクラシック。"],["使いどころ","冷たさ、支配、狂気。きれいすぎる対称は「人の手で作られた不自然さ」を感じさせます。"],["例","『シャイニング』（1980年）廊下を三輪車で進む場面／『時計じかけのオレンジ』（1971年）冒頭の目線／『バリー・リンドン』（1975年）ゆっくり引くズーム [知識]"]]},{"g":"監督の型","n":"黒澤明（天気と動き・軸上のカット・ワイプ）","b":[["見え方","画面のどこかが必ず動いています（雨、風、霧、旗、火）。同じ向きのまま遠くから近くへ「ドン・ドン・ドン」と寄ります。場面は線が横切って変わります。"],["作り方","(1) 背景に天気か群衆の動きを入れる。気持ちに合わせて強さを変える（怒り＝豪雨、迷い＝霧）(2) 軸上のカット：カメラの向きを変えずに遠景→中→アップと2〜3回飛んで寄る（MADの3段寄りと同じ）(3) 場面転換はワイプ（線が横切って次の絵に変わる）(4) 動きの途中で切る (5) 望遠レンズで遠くから撮り、奥行きをつぶす。"],["使いどころ","静かな会話でも画面が生きます。大人数の戦いを分かりやすく見せたい時。"],["例","『七人の侍』（1954年）雨の中の決戦／『羅生門』（1950年）豪雨の門／『隠し砦の三悪人』（1958年）ワイプでの場面転換 [知識]"]]},{"g":"監督の型","n":"小津安二郎（低い固定・枕ショット）","b":[["見え方","畳に座った人より低い位置から、動かないカメラで撮ります。場面の間に、人のいない風景や物の絵が静かにはさまります。"],["作り方","(1) カメラを床に近い高さに固定し、パンも移動もズームもしない (2) レンズは標準1本 (3) 会話は人物をほぼ正面から撮り、交互に切る（目線の線をまたいでもよい）(4) 場面のつなぎは、煙突・廊下・洗濯物などの絵を2〜3枚、各3〜6秒（枕ショット）(5) フェードやディゾルブ（ゆっくり重なる転換）は使わず、普通のカットだけ。"],["使いどころ","家族、日常、別れ。動かないことで小さな仕草や沈黙が目立ちます。"],["例","『東京物語』（1953年） [知識]"]]},{"g":"監督の型","n":"スピルバーグ（長回しの中の構図替え）","b":[["見え方","カットしていないのに、引きの絵→2人の絵→アップと、絵が次々に変わります。長回しだと気づきません。"],["作り方","(1) 1〜3分の場面を1カットで計画する (2) カメラは少し動くだけで、人物のほうが手前に来る・奥へ去る・横切る (3) 止まるたびに新しい構図（3〜5種類）ができるよう立ち位置を決める。【スピルバーグ顔】見上げて口を開けた顔にゆっくり寄り、その後で対象を見せる。逆光と光の筋もよく使います。"],["使いどころ","会話の場面を、切らずにテンポよく見せたい時。派手な長回しと違い、目立たないのが良さです。"],["例","『ジョーズ』（1975年）フェリーの上での言い争い／『レイダース／失われたアーク《聖櫃》』（1981年）酒場の飲み比べ／『ジュラシック・パーク』（1993年）見上げる顔 [知識]"]]},{"g":"監督の型","n":"スコセッシ（長いステディカム・止め絵）","b":[["見え方","カメラが人物の後ろについて、裏口から廊下、厨房、客席まで一息で進みます。語りの途中で絵が止まります。"],["作り方","(1) ステディカム（体に付ける揺れ止め装置）で人物の1〜2m後ろを追う (2) 道の途中に、あいさつ・受け渡し・すれ違いを次々に置く (3) 既成の曲を1曲まるごと流し、曲の終わりに到着を合わせる (4) 止め絵は動きの頂点で2〜4秒＋語り (5) 顔への速い寄り。"],["使いどころ","「この世界に入っていく」高揚感、人物の力を見せる時。"],["例","『グッドフェローズ』（1990年）ナイトクラブの裏口から席までの約3分／同作の語りの止め絵 [知識]"]]},{"g":"監督の型","n":"タランティーノ（トランクの中から）","b":[["見え方","車のトランクの中から、のぞきこむ人物たちを見上げます。章の題字、長い雑談、突然の暴力。"],["作り方","(1) カメラを低い箱の中に置き、広角で見上げる。手前にふたの縁を入れる (2) 章ごとに題字カード (3) 関係なさそうな雑談を長く撮り、急に事件を起こす (4) 既成の曲 (5) 章の順番を入れ替える (6) 顔への急ズーム。"],["使いどころ","トランクの絵は「閉じこめられた側の目」です。見下ろす人物が強く見えます。"],["例","『レザボア・ドッグス』（1992年）／『パルプ・フィクション』（1994年）トランクを開ける2人／『キル・ビル Vol.1』（2003年）急ズーム [知識]"]]},{"g":"監督の型","n":"スパイク・リー（ダブルドリー）","b":[["見え方","人物が歩いていないのに、すーっと前へ滑ってきます。背景だけが流れ、体が浮いているようです。"],["作り方","(1) カメラを台車（ドリー）に載せる (2) 役者も同じ台車、または別の台車に乗せる (3) 一緒に動かす。役者は足を動かさず、顔はカメラのほうを向く。編集で真似るなら、人物を切り抜いて位置を固定し、背景だけをゆっくり拡大・移動します。ほかの癖：カメラを見て話す独白、斜めに傾けた構図。"],["使いどころ","運命に引っぱられる、我を忘れる、決意の瞬間。1作品に1〜2回、ここぞの場面で使います。"],["例","最初に使ったのは『モ'・ベター・ブルース』（1990年）とする資料が多い（『スクール・デイズ』（1988年）とする説もある）。代表は『マルコムX』（1992年）終盤、『25時』（2002年） [確認]"]]},{"g":"監督の型","n":"フィンチャー（人に同期するカメラ）","b":[["見え方","人物が立つ、座る、体を傾けると、カメラがまったく同じ速さ・同じ量だけ動きます。カメラの存在を感じないのに、目が人物から離れません。"],["作り方","(1) 基本は三脚で固定、手持ちはほぼ使わない (2) 人物の動き出しと止まりにカメラの動き出しと止まりをぴったり合わせる（遅れも行きすぎも無し）(3) 色は彩度を落とし、黄緑か青緑に寄せる (4) 暗部をしっかり暗く。編集で真似るなら、顔の位置を追跡して、画面を数%だけ同じ向きに動かします。"],["使いどころ","冷静・正確・執着。観客を人物の行動に縛りつけます。"],["例","『ソーシャル・ネットワーク』（2010年）／『ゾディアック』（2007年）。この型を解説した動画に、Nerdwriter の「フィンチャーは目を乗っ取る」という趣旨のものがあります [知識]"]]},{"g":"監督の型","n":"ノーラン（時間の並行）","b":[["見え方","進み方の違う複数の時間（1週間・1日・1時間など）が交互に進み、最後に1点で出会います。"],["作り方","(1) 2〜4本の筋を用意し、それぞれの時間の長さを決める (2) 交互に切る（クロスカット）。山場に近づくほど1本あたりを短く (3) 音楽を切らずに全部の筋の上に流し続ける（上がり続ける音＝シェパードトーン → 技法13_音）(4) 筋の見分けは色・場所・文字で。"],["使いどころ","大きな山場を長く引きのばす時。複雑なので、各筋の目的は1つにします。"],["例","『ダンケルク』（2017年）陸1週間・海1日・空1時間／『インセプション』（2010年）夢の階層ごとに時間の速さが違う／『メメント』（2000年）逆順と順行を交互に [知識]"]]},{"g":"監督の型","n":"エドガー・ライト（笑いのカット・急ズーム）","b":[["見え方","お茶をいれる、着替える、書類を書くなどの地味な動作が、アクション映画のような超短いカットと大きな効果音で一瞬で終わります。"],["作り方","(1) 動作を5〜10個のアップに分ける (2) 1カット4〜12コマ (3) 各カットに誇張した音（シュッ、ガチャ、ドン）(4) 最後は少し長い絵で落ち着く。ほかに：顔への急ズーム、画面の外から物や人が入ってきて笑いにする、動作を曲の拍に合わせる、ウィップパンでの場面転換。"],["使いどころ","退屈な説明や準備を笑いに変える。ショート動画と相性が良いです。"],["例","『ショーン・オブ・ザ・デッド』（2004年）／『ホット・ファズ 俺たちスーパーポリスメン！』（2007年）／『ベイビー・ドライバー』（2017年）動作と曲の同期 [知識]"]]},{"g":"監督の型","n":"ウェス・アンダーソン（左右対称・横移動）","b":[["見え方","絵本や人形の家のように、左右対称で平らな絵。カメラは真横にすべるか、90度ぴったり振ります。"],["作り方","(1) カメラは壁に対して真正面・真横・真上のどれかだけ (2) 人物は中央か左右対称に置き、正面を向かせる (3) 移動は真横のドリー、向きを変える時は90度の速いパン (4) 色は場面ごとに2〜3色のパステル (5) 文字は中央寄せ (6) 時代ごとに画面比率を変える。"],["使いどころ","かわいさ、とぼけた笑い、悲しみを距離を置いて見せる時。"],["例","『グランド・ブダペスト・ホテル』（2014年）／『ムーンライズ・キングダム』（2012年） [知識]"]]},{"g":"監督の型","n":"ウォン・カーウァイ（ステッププリント）","b":[["見え方","人物はカクカクと飛び飛びに動き、まわりの光や人は流れてにじみます。速いのに遅い、不思議な時間です。"],["作り方","低いコマ数で、シャッターを長く開けて撮り（ぶれが出る）、各コマを何回か複製して普通の速さに戻します。数字は資料で食い違い（12コマで撮って2回ずつ、など） [確認]。編集で真似るなら、(1) 前後のコマを混ぜてぶれを足す (2) コマ数を6〜12に落とし、同じコマを2〜4回くり返す。ほかに：ネオンの色、物ごしの狭い枠、同じ曲のくり返し。"],["使いどころ","追跡、人ごみの中の孤独、思い出の中の一瞬。"],["例","『恋する惑星』（1994年）冒頭の追跡（前半の撮影はアンドリュー・ラウ） [確認]／『花様年華』（2000年）曲に合わせたスロー [知識]"]]},{"g":"監督の型","n":"マイケル・ベイ（回り込みの英雄ショット）","b":[["見え方","低い位置から見上げた人物のまわりをカメラがぐるりと回り、人物がゆっくり立ち上がる（振り向く）。後ろの空や街が大きく流れます。"],["作り方","(1) カメラを腰より低く (2) 望遠ぎみのレンズで人物を中心に円を描いて動く（背景が速く流れる）(3) 人物は逆向きにゆっくり動く (4) スロー (5) 夕日や逆光、手前・中・奥の全部で何かが動いている。3Dなら、人物を中心にカメラを円の道に沿って90〜360度動かします。"],["使いどころ","「ここから反撃」の決めの瞬間。大げさなので、笑いのまねにも使われます。"],["例","『バッドボーイズ』（1995年）／『バッドボーイズ2バッド』（2003年） [知識]"]]},{"g":"監督の型","n":"ザック・スナイダー（速度の緩急）","b":[["見え方","1つのカットの中で、動きが速い→急にスロー→また速い、と変わります。当たる瞬間だけが引きのばされます。"],["作り方","高いコマ数で撮っておき、編集で速さを変えます。当たる直前まで100〜200%、当たる瞬間を20〜30%、抜けたらまた速く。切り替えは2〜4コマで。MADの速度編集と同じ仕組みです。色は彩度を落として明暗を強く。"],["使いどころ","格闘、絵画のような決めの絵。全部の攻撃に使うと長く感じます。"],["例","『300 〈スリーハンドレッド〉』（2006年）戦いの場面 [知識]"]]},{"g":"監督の型","n":"セルジオ・レオーネ（目の超アップ）","b":[["見え方","広い荒野の遠景から、画面いっぱいの「目だけ」へいきなり飛びます。決闘の前、だれも動かないのに緊張が上がり続けます。"],["作り方","(1) 超遠景と、目・手・銃の超アップだけを使い、中間の大きさを抜く (2) 3人の顔・目・手を順に切り、1カットの長さを少しずつ短くする（3秒→1秒→数コマ）(3) 音楽に合わせて切り、頂点で一気に撃つ (4) それまでは台詞なしの長い沈黙。"],["使いどころ","対決、にらみ合い、駆け引き。「何も起きない時間」を見せ場にします。"],["例","『続・夕陽のガンマン』（1966年）最後の3人の決闘 [知識]"]]},{"g":"監督の型","n":"宮崎駿（間）","b":[["見え方","話が進まない静かな数秒があります。ため息をつく、景色を見る、ただ座っている。"],["作り方","(1) 大きな出来事の後に、何も起きない場面を5〜30秒入れる (2) 人物は小さな日常の動作だけ（靴をはく、食べる、髪が風で動く）(3) 音楽は止めるか静かに。環境音を聞かせる (4) 風・水・雲など自然をゆっくり動かす。"],["使いどころ","観客が気持ちを整理する時間。間があるから、次の動きが大きく感じられます。"],["例","『千と千尋の神隠し』（2001年）水の上を走る電車の場面 [知識]"]]},{"g":"監督の型","n":"今敏（マッチカット）","b":[["見え方","振り向く、扉を開ける、落ちる、という動きの途中で、いつのまにか別の場所・別の時間・夢の中にいます。"],["作り方","(1) 2つの場面で、同じ形・同じ向き・同じ速さの動きを用意する (2) 動きの途中で切る (3) 切った後に「引き」の説明の絵を入れず、そのまま進める (4) 物や人が画面を横切るのを転換に使う。必要より数コマ早く切ると、置いていかれる感覚が出ます。"],["使いどころ","現実と夢、今と過去、演技と本心の境目をあいまいにしたい時。"],["例","『パプリカ』（2006年）冒頭の夢の連続／『千年女優』（2001年）走りながら時代と映画が変わる／『パーフェクトブルー』（1997年） [知識]"]]},{"g":"監督の型","n":"庵野秀明（明朝体・止め絵の長回し）","b":[["見え方","黒地に白の極太の明朝体が、直角に折れて画面に並びます。まったく動かない絵が、とても長く続きます。"],["作り方","(1) 題字は極太の明朝体を画面いっぱいに、縦と横を組み合わせてL字に置く (2) 文字だけのカットを数コマ〜1秒で差しこむ (3) 止め絵は1枚で数十秒。音（環境音や音楽）だけを流し続ける (4) 電柱・電線・信号・標識など物だけのカット (5) 極端な低い位置や物ごしの構図。"],["使いどころ","気まずさ、迷い、決断の重さ。止めている間、観客は人物と同じ時間を待たされます。"],["例","『新世紀エヴァンゲリオン』（1995〜96年）第22話のエレベーターの止め絵は約50秒（資料により45〜53秒）、第24話の握ったままの止め絵は約1分5秒 [確認]。題字の書体はマティスEBとされる [知識]／『シン・ゴジラ』（2016年）肩書きの文字 [知識]"]]},{"g":"監督の型","n":"新海誠（光と空）","b":[["見え方","空が画面の半分以上を占め、雲は高く、光の筋やレンズの光の輪が入ります。現実の街が、現実よりきれいです。"],["作り方","(1) 地平線を低くして空を広く (2) 逆光にして人物の縁を光らせる (3) 影には青や紫、光には暖かい色を入れ、彩度を高めに (4) 写真をもとに背景を描く (5) 夕方・明け方の時間を選ぶ (6) 語りと歌に合わせて、短い風景カットを連ねる。編集で真似るなら、光の筋とレンズの光を加算で重ね、空の色を2色のグラデーションにします。"],["使いどころ","せつなさ、遠さ、会えない2人。きれいすぎると人物が負けるので、人物は小さく置きます。"],["例","『君の名は。』（2016年）／『秒速5センチメートル』（2007年） [知識]"]]},{"g":"監督の型","n":"出崎統（ハーモニー・3回パン）","b":[["見え方","決めの瞬間に動きが止まり、絵が筆で描いた絵画のような質感に変わります。同じ動きのカメラが3回くり返されます。斜めの光の筋が入ります。"],["作り方","【ハーモニー】止めたい1コマを、背景画と同じ描き方（絵の具の筆あと、線の強弱）で描き直した1枚絵にして止める [確認]。編集で真似るなら、止め絵に絵画風の処理と紙の質感を重ねます。【3回パン】同じ絵・同じ向きの動きを3回続けてくり返す（くり返しの演出は [確認]、「3回パン」の語の定義は [知識]）。ほかに：入射光・透過光（斜めの光の筋）、画面の分割。"],["使いどころ","勝負の決着、衝撃、別れ。少ない枚数で強い印象を作れます。"],["例","『あしたのジョー2』（1980年）／『ベルサイユのばら』（1979年、後半を担当）／『エースをねらえ！』（1973年） [知識]"]]},{"g":"監督の型","n":"新房昭之（シャフ度）","b":[["見え方","人物があごを上げ、首を大きく後ろへ傾けて、振り向きながらこちらを見ます。背景は平らで図形のよう。文字のカットが一瞬はさまります。"],["作り方","(1) 首を、体に対して後ろ・横へ不自然なほど傾け、目だけこちらへ向ける (2) 背景は平面的な色面と図形に整理する (3) 文字だけのカットを数コマ差しこむ (4) 目や口のアップを多用 (5) 会話中にカメラ位置を大きく飛ばす。"],["使いどころ","動きの少ない会話劇を、絵として退屈させない時。挑発、余裕、謎めいた人物。"],["例","『化物語』（2009年）／『魔法少女まどか☆マギカ』（2011年） [知識]"]]},{"g":"監督の型","n":"＋ゴダール（ジャンプカット）","b":[["見え方","同じ人物を同じ向きで撮ったまま、途中の時間が飛んで、絵がぴょんと跳ねます。"],["作り方","1つの長いカットの中ほどを数秒ずつ抜くだけです。カメラの位置は変えません。今のしゃべり動画の「無言を切る」編集の先祖です。"],["使いどころ","落ち着かなさ、速さ、決まりを破る若さ。"],["例","『勝手にしやがれ』（1960年）車の中の場面 [知識]"]]},{"g":"監督の型","n":"＋タルコフスキー（長回しと自然）","b":[["見え方","とても長いカットで、カメラがゆっくり動きます。水、火、風、雨、霧がいつも画面にあります。"],["作り方","(1) 1カットを数分にのばす (2) カメラはごく遅い横移動か前進 (3) 水たまり、ぬれた床、燃える物、風で揺れる草を置く (4) 音楽を減らし、水の音や足音を聞かせる。"],["使いどころ","時間そのものを感じさせる、祈り、思い出。短い動画には向きませんが、1カットだけ入れると空気が変わります。"],["例","『ノスタルジア』（1983年）火を消さずに運ぼうとする約9分の1カット／『ストーカー』（1979年） [知識]"]]},{"g":"監督の型","n":"＋ポン・ジュノ（上下と線）","b":[["見え方","金持ちは上、貧しい人は下。階段、坂、窓の位置で人の立場が見えます。画面の中の線が人と人を分けます。"],["作り方","(1) 立場の違いを高さで決め、場所を設計する (2) 移動は階段と坂。下る時は長く見せる (3) 窓わく、柱、ガラスの境目で、画面を2つに分ける (4) 雨や水を上から下へ流す。"],["使いどころ","差、越えられない境目。言葉で言わずに構図で伝えます。"],["例","『パラサイト 半地下の家族』（2019年）大雨の夜に階段を下り続ける場面 [知識]"]]},{"g":"監督の型","n":"＋細田守（同じ構図のくり返し・横移動）","b":[["見え方","同じ場所を同じ構図で何度も見せ、季節や人の変化だけが変わります。カメラが真横にすべって時間が進みます。"],["作り方","(1) カメラ位置を1つ決め、時間を変えて何度も戻る（同ポジ）(2) 真横に移動しながら、部屋や学年が次々に変わる絵をつなぐ (3) 人物に影を付けず、線と色だけで描く (4) 夏の入道雲と青空。"],["使いどころ","成長、年月、日常のくり返し。"],["例","『おおかみこどもの雨と雪』（2012年）教室を横へ進むと学年が上がっていく場面／『時をかける少女』（2006年） [知識]"]]},{"g":"監督の型","n":"＋山田尚子（足と手で語る）","b":[["見え方","顔ではなく、足もと、指先、後ろ姿のアップで気持ちが伝わります。望遠レンズで撮ったような、やわらかいぼけがあります。"],["作り方","(1) 大事な台詞の時に、顔を映さず足・手・髪を映す (2) 足の向き、つま先の動き、指のもじもじで感情を出す (3) 手前と奥を大きくぼかし、色のにじみや光のもやを足す (4) 小さな揺れ。"],["使いどころ","言えない気持ち、恥ずかしさ、すれ違い。"],["例","『聲の形』（2016年）／『リズと青い鳥』（2018年） [知識]"]]}],"16":[{"g":"つかみと持続","n":"最初の1〜3秒のフック（Hook）","b":[["見え方","再生した瞬間から、もう何かが起きています。あいさつや自己紹介はありません。"],["作り方","0秒に次のどれかを置きます。(1) 結果を先に見せる（完成品、失敗の瞬間）(2) 問い（「もし〜なら」）(3) 意外な絵や動き (4) 相手を名指し（「◯◯な人へ」）。最初の1文は1.5〜2秒で言い切り、同じ内容を文字でも出します。1コマ目が止まった絵や黒い画面にならないようにします。"],["使いどころ","全部の動画。フックで約束したことを本編で出さないと、途中で離れられます。"],["例","yastor200 の物語動画は第1文で問いを言い切る（→ yastor200 のバズ分析）。「3秒以内に離脱が決まる」などの数字に公式の出典は見つけていません [意見]。YouTubeの分析画面には「視聴された／スワイプされた」の割合が出るので、自分の動画で確かめられます [知識]"]]},{"g":"つかみと持続","n":"文字のフック（Text hook）","b":[["見え方","最初のコマから、画面の上のほうに大きな見出しの文字があります。"],["作り方","10〜15文字以内、2行まで。太い書体に黒いふちか帯を付けます。位置は上から15〜25%（下はアプリの表示で隠れる）。中身は「数字」「意外な組み合わせ」「見る人の得」のどれか。最初の3〜5秒、または全編出しっぱなしにします。"],["使いどころ","音を出さずに見ている人、途中から見た人に「何の動画か」を伝える時。"],["例","なし"]]},{"g":"つかみと持続","n":"数秒ごとの変化（パターン・インタラプト）（Pattern interrupt）","b":[["見え方","同じ絵が続かず、数秒ごとに何かが変わります。"],["作り方","2〜4秒に1回、次のどれか1つを変えます。画面の大きさ（寄り・引き）、カメラの角度、Bロール、文字、効果音、色、話す速さ、音楽。全部を同時に変えず、1回に1つ。"],["使いどころ","しゃべり動画や解説。落ち着いて聞かせたい話（感動、まじめな説明）では間隔を長くします。変化が多すぎると中身が頭に入りません。"],["例","なし（yastor200 の26本では、カット数と再生数に関係は見られませんでした → yastor200 のバズ分析）"]]},{"g":"つかみと持続","n":"ループする終わり方（Seamless loop）","b":[["見え方","動画が終わったことに気づかず、2周目に入っています。"],["作り方","(1) 最後のコマと最初のコマを同じ絵・同じ構図にする (2) 最後の文を言い切らず、最初の文につながる形にする（「…だから」→「◯◯なんです」）(3) 音楽も最後と最初で拍をそろえ、消えていく処理を付けない。"],["使いどころ","15秒以下の短い動画、作る過程、目に気持ちいい映像。くり返し再生は視聴時間に数えられます。"],["例","冒頭の小物や言葉が最後に戻って意味が変わる型は yastor200 のバズ分析。映画での同じ考え方は「ブックエンド」（→ 技法15_語りと監督の型）"]]},{"g":"つかみと持続","n":"進み具合の表示（Progress indicator）","b":[["見え方","画面の端に、細い棒や「3/5」のような数字が出て、あとどれだけかが分かります。"],["作り方","棒は高さ6〜10px、幅を「今の時間÷全体」にします。数字なら項目が変わるたびに「ポン」と入れ替えます。位置は上のほう（下は隠れる）。"],["使いどころ","数え上げ、手順、挑戦もの。終わりが見えると待ってもらえます。"],["例","なし（作り方は 技法12_文字とモーショングラフィックス の「進み具合の棒」）"]]},{"g":"つかみと持続","n":"数え上げ（Listicle / countdown）","b":[["見え方","「◯◯な3つ」「5位から1位」のように、番号つきで進みます。"],["作り方","3個か5個。1個あたり5〜10秒。一番強いものを最後に置き、冒頭で「最後が一番」と予告します。番号は毎回同じ位置・同じ動きで出します。"],["使いどころ","知識、おすすめ、ランキング。個数が多いと1個が薄くなります。"],["例","なし"]]},{"g":"つかみと持続","n":"＋オープンループ（答えを後回しにする）（Open loop）","b":[["見え方","最初に出た問いや「結果」が、なかなか明かされません。"],["作り方","冒頭で問いを1つ開け、答えを最後の2〜3秒まで取っておきます。途中に小さな問いと答えを2〜3回はさんで、待つ苦しさを減らします。"],["使いどころ","実験、ビフォーアフター、物語。引っぱりすぎ・答えがしょぼい、は低評価のもとです。"],["例","yastor200 の「転換の一文」で代償に切り替わる構成（→ yastor200 のバズ分析）"]]},{"g":"つかみと持続","n":"＋シリーズ化（Part 2 / episodic）","b":[["見え方","「その2」「◯日目」のように、同じ型の動画が続きます。"],["作り方","題・冒頭の一言・文字の位置・音を毎回同じにし、中身だけ変えます。番号を画面に出します。"],["使いどころ","当たった型を見つけた後。見た人が過去の回も見に来ます。"],["例","yastor200 は当たった「物語」の型に集中した（→ yastor200 のバズ分析）"]]},{"g":"つかみと持続","n":"＋問いで終わる（コメントを誘う）（Comment bait / CTA）","b":[["見え方","最後に、見た人が一言で答えられる質問が出ます。"],["作り方","二択か「どれ？」の形にします。画面とキャプションの両方に書きます。1〜2秒で読める長さに。"],["使いどころ","意見が分かれる題材。わざと怒らせる問いは荒れます。"],["例","yastor200 の YES / NO と「1つだけ戻せる、どれ？」（→ yastor200 のバズ分析）"]]},{"g":"しゃべり動画の編集","n":"無言を切るジャンプカット（Jump cut / silence removal）","b":[["見え方","息つぎや言いよどみが無く、言葉が次々に続きます。切れ目で体が少し跳ねます。"],["作り方","0.3〜0.5秒以上の無音を全部切ります。言葉の頭と尻に2〜3コマの余白を残すと聞き取りやすいです。自動なら、音量で無音を見つける道具を使います（ffmpegの silencedetect で −35dB・0.4秒以上を探す、など）。跳ねが気になる所は、次の「パンチイン」かBロールで隠します。"],["使いどころ","ほぼ全部のしゃべり動画。全部の間を切ると息苦しいので、大事な一言の前だけ0.5秒残します。"],["例","先祖は『勝手にしやがれ』（1960年）のジャンプカット（→ 技法15_語りと監督の型） [知識]"]]},{"g":"しゃべり動画の編集","n":"強調のパンチイン（自動ズーム）（Punch-in）","b":[["見え方","大事な言葉の瞬間に、顔へ少し寄ります。"],["作り方","(1) 切れ目で100%→110〜130%に一瞬で切り替える（跳ねを「寄り」に見せる）(2) または1文の間に100→108%へゆっくり寄る。寄る中心は目の高さ。4K（大きめの解像度）で撮っておくと、寄ってもぼけません。次の文で100%に戻します。"],["使いどころ","強調、オチ、秘密を言う時。毎文やると酔います（3〜4文に1回）。"],["例","なし"]]},{"g":"しゃべり動画の編集","n":"1語ずつ出る字幕（Word-by-word captions）","b":[["見え方","話している言葉が、1〜3語ずつ画面の真ん中あたりに大きく出て、声と同じ速さで入れ替わります。"],["作り方","音声から言葉ごとの時刻を取り（自動の文字起こし）、1回に出すのは1〜3語（日本語なら4〜8文字）。太い書体、白文字＋黒ふち、横幅1080pxの画面で70〜100pxほど。位置は中央より少し下（下端からは30%以上あける）。出る時に0→110→100%の小さな「ポン」を付けます。"],["使いどころ","音なしで見る人が多い場所。目が文字に固定されるので見続けやすいです。静かな話では文単位の普通の字幕に。"],["例","米国の起業家アレックス・ホルモジの動画で広まった型として知られる [知識]"]]},{"g":"しゃべり動画の編集","n":"色つき強調語（Highlighted keywords）","b":[["見え方","字幕の中で、大事な言葉だけ黄色や緑になります。"],["作り方","1つの字幕につき1語だけ色を変えます（数字、名前、気持ちの言葉）。色は動画全体で1〜2色に決めます。今話している語だけ色が付く「カラオケ式」もあります。"],["使いどころ","流し見でも要点だけ拾えるように。全部に色を付けると強調になりません。"],["例","なし"]]},{"g":"しゃべり動画の編集","n":"絵文字・スタンプの飛び出し（Emoji / sticker pop）","b":[["見え方","言葉に合った絵文字や小さな絵が、字幕の横や頭の上に「ポン」と出ます。"],["作り方","大きさ0→115→100%を6〜8コマで。出ているのは0.5〜1.5秒。効果音を1つ付けます。字幕や顔に重ならない所へ置きます。"],["使いどころ","軽い話、笑い。まじめな話や高級感のある動画では安く見えます。"],["例","なし"]]},{"g":"しゃべり動画の編集","n":"効果音（ポン・シュッ・ピン）（SFX）","b":[["聞こえ方","文字が出る時に「ポン」、絵が切り替わる時に「シュッ」、気づきに「ピン」。"],["作り方","動きの始まりのコマに音の頭を合わせます。音量は声より12〜18dB小さく。種類は1本の動画で3〜5個にしぼり、同じ動きには同じ音を使います。"],["使いどころ","字幕、転換、強調。全部に付けるとうるさいので、1文に1個まで。"],["例","なし"]]},{"g":"しゃべり動画の編集","n":"Bロールかぶせ（B-roll overlay）","b":[["見え方","声は続いたまま、絵だけが話の内容を見せる映像に変わります。"],["作り方","話に出た物・場所・動作の映像を、声の上に2〜4秒重ねます。言葉が出る0.2〜0.3秒前に絵を出すと自然です。素材が無ければ写真に「ゆっくり寄り」を付けます。"],["使いどころ","ジャンプカットの跳ねを隠す、説明を早く伝える。顔を出す時間が減りすぎると親しみが落ちます。"],["例","なし"]]},{"g":"しゃべり動画の編集","n":"ミームの差し込み（Meme insert）","b":[["見え方","話の途中に、有名な映像や画像のネタが0.5〜1.5秒だけはさまります。"],["作り方","つっこみや気持ちを、言葉の代わりにネタの一場面で言います。音ごと入れ、すぐ本編に戻ります。他人の映像なので、権利と引用の決まりに注意が要ります。"],["使いどころ","笑い、共感。ネタは古くなるのが早く、知らない人には通じません。"],["例","なし"]]},{"g":"しゃべり動画の編集","n":"画面録画とカーソルへの寄り（Screen recording + cursor zoom）","b":[["見え方","パソコンやスマホの画面で、クリックや入力をする所へカメラがなめらかに寄ります。"],["作り方","画面録画を素材にし、クリックの位置を中心に150〜200%へ0.3〜0.5秒で寄り（出だしと終わりをゆるく）、操作が終わったら戻します。カーソルを大きくし、クリックに輪っかの印と「カチッ」の音を付けます。縦動画では、見せたい部分だけを切り出して縦に置きます。"],["使いどころ","アプリの紹介、使い方。寄らないとスマホでは文字が読めません。"],["例","自動でカーソルに寄る録画ソフトの宣伝動画でよく見る形 [知識]"]]},{"g":"しゃべり動画の編集","n":"＋読み上げ音声（Text-to-speech voice）","b":[["聞こえ方","人ではなく合成の声が、字幕と同じ文を読みます。"],["作り方","台本を合成音声に読ませ、言葉の時刻に字幕と絵を合わせます。1文を短く（15〜25文字）すると読みが自然です。日本語なら VOICEVOX など（使う時はクレジットの決まりを守ります）。"],["使いどころ","顔や声を出したくない時、量産。声の種類が流行と結びつくので、古くなることがあります。"],["例","yastor200 の声はAI（→ yastor200 のバズ分析）"]]},{"g":"見せ技","n":"手で隠す転換（Hand cover transition）","b":[["見え方","手のひらがレンズをふさいで真っ暗になり、手がどくと別の場所・別の服になっています。"],["作り方","(1) 1本目の最後に手でレンズを完全にふさぐ (2) 2本目は手でふさいだ状態から始めてどける (3) どちらも一番暗いコマで切ってつなぐ。手を動かす速さと向きをそろえます。"],["使いどころ","場所の移動、ビフォーアフター。一番かんたんで失敗しにくい転換です。"],["例","魔法のような転換で知られるザック・キングの動画に多い型 [知識]"]]},{"g":"見せ技","n":"ジャンプ転換（Jump transition）","b":[["見え方","跳び上がった瞬間に、背景や服が変わります。"],["作り方","2本とも同じ位置・同じ高さで跳び、一番高い所（体が一瞬止まるコマ）で切ります。カメラは三脚で固定。着地は2本目だけ使います。"],["使いどころ","場所の移動、着替え、旅の動画。"],["例","なし"]]},{"g":"見せ技","n":"着替え転換（Outfit change transition）","b":[["見え方","同じ場所・同じポーズのまま、服だけが一瞬で変わります。"],["作り方","カメラを固定し、足の位置に印を付けます。きっかけの動き（指パッチン、回る、布を投げる、靴を落とす）を2本とも同じ速さで行い、その動きの途中で切ります。体の位置がずれたら、編集で2本目を数px動かして合わせます。"],["使いどころ","服の紹介、変身、ビフォーアフター。"],["例","なし"]]},{"g":"見せ技","n":"指パッチン転換（Snap transition）","b":[["見え方","指を鳴らした瞬間に、絵がぱっと変わります。"],["作り方","指の音の一番大きい所（波形の山）を見つけ、そのコマで切ります。音は後から大きめのものに差し替えてもよいです。1〜2コマの白い光や小さな揺れを足すと決まります。"],["使いどころ","変化の合図ならなんでも。音がきっかけなので、曲の拍にも合わせやすいです。"],["例","なし"]]},{"g":"見せ技","n":"スピンつなぎ（Spin / whip transition）","b":[["見え方","カメラ（または体）がぐるっと回り、ぶれの中で次の場面に変わります。"],["作り方","1本目の終わりと2本目の頭で、同じ向き・同じ速さにカメラを振ります。ぶれている4〜6コマの真ん中で切ります。編集だけで作るなら、切れ目の前後に回転と動きぶれを足します。MADのウィップパンと同じ仕組みです。"],["使いどころ","場所の移動、勢いを付けたい時。続けて使うと酔います。"],["例","なし"]]},{"g":"見せ技","n":"止め絵＋白ふちの切り抜き","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["ショートでの使い方","人物や商品の紹介の瞬間に0.5〜1秒止め、白いふち付きで切り抜いて名前の文字を添えます。"],["例","なし"]]},{"g":"見せ技","n":"写真の立体化","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["ショートでの使い方","動画素材が無く写真しか無い話（歴史、思い出、ニュース）で、2〜4秒ずつ使います。"],["例","なし"]]},{"g":"見せ技","n":"人の後ろに入る文字（Text behind subject）","b":[["見え方","大きな題の文字が、人の後ろ・背景の手前に入ります。"],["作り方","技法12_文字とモーショングラフィックス の同じ項目と同じです（背景→文字→切り抜いた人の順に重ねる）。"],["使いどころ","冒頭の題、サムネ。スマホの編集アプリにも自動の機能があります。"],["例","なし"]]},{"g":"見せ技","n":"物に張りつくスタンプ（Tracked sticker）","b":[["見え方","絵文字や文字が、動く顔や物にくっついて一緒に動きます。"],["作り方","付けたい物を追跡（トラッキング）して、位置と大きさをスタンプに写します。編集アプリの追跡機能、またはコードなら特徴点の追跡。少し遅れて付いてくる（1〜2コマ）ほうがかわいく見えます。"],["使いどころ","顔を隠す、注目させる、ふざける。"],["例","なし"]]},{"g":"見せ技","n":"色だけ残す","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["ショートでの使い方","商品や服の色だけ残して、ほかを白黒にします。見てほしい物が1つの時に。"],["例","なし"]]},{"g":"見せ技","n":"速度編集（ベロシティ）","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["ショートでの使い方","ダンス、スポーツ、乗り物の動画で、曲の拍に合わせて速→遅をくり返します。"],["例","なし"]]},{"g":"見せ技","n":"拍の揺れ・光","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["ショートでの使い方","曲が主役の動画で、拍ごとに小さな寄りや光を入れます。1拍1回までにします。"],["例","なし"]]},{"g":"見せ技","n":"黒帯で映画風（Cinematic bars）","b":[["見え方","上下に黒い帯が入り、横長の映画のような画面になります。"],["作り方","上下に黒い四角を置くだけです。横長（1920×1080）の動画を映画の比率（2.39:1）にするなら、上下それぞれ約138px。縦動画なら上下それぞれ10〜15%。帯が0.5〜1秒かけて入ってくる動きを曲の盛り上がりに合わせると、それ自体が見せ場になります。"],["使いどころ","旅、風景、かっこよく見せたい場面。縦動画ではただでさえ狭い絵がさらに小さくなります。"],["例","なし"]]},{"g":"見せ技","n":"＋音ハメ（流行の音に動きを合わせる）（Sound sync / trend audio）","b":[["見え方","はやっている曲や音声の「決まった所」で、決まった動きや転換が起きます。"],["作り方","音の中の合図（拍、歌詞の一語、効果音）のコマを先に全部メモし、そこに切れ目や動きを置きます。口の動きを合わせる（口パク）型もあります。"],["使いどころ","流行に乗る時。同じ音を使った動画がまとめて見られます。流行は数週間で終わります。"],["例","なし"]]},{"g":"画面の組み方","n":"上下2画面（下にゲーム）（Split screen with gameplay）","b":[["見え方","上半分に本編（話や切り抜き）、下半分に関係のないゲームや気持ちいい作業の映像が流れます。"],["作り方","1080×1920を上下に分け（半々、または上60%・下40%）、下に走り続けるゲームや砂を切る映像などを音なしで置きます。字幕は2つの境目に。"],["使いどころ","絵の変化が少ない長い話。「目のひま」をうめます。安っぽく見える、内容に集中できないという批判もあります。"],["例","走るゲームや積み木ゲームの映像を下に置く型（海外で「スラッジ・コンテンツ」と呼ばれる） [知識]"]]},{"g":"画面の組み方","n":"リアクションの小窓","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["ショートでの使い方","元の動画を大きく、自分の顔を角に小さく（画面幅の30〜40%）置きます。下と右端はアプリの表示で隠れるので、左上か上の中央に。"],["例","なし"]]},{"g":"画面の組み方","n":"グリーンバック背景（Green screen）","b":[["見え方","話す人の後ろに、記事の画像・スクリーンショット・動画が大きく出ます。"],["作り方","本来は緑の布の前で撮り、緑を透明にします。スマホのアプリでは自動の人物切り抜きで同じ事ができます。人を下3分の1に小さく置き、上に資料を大きく見せます。光は人と背景の布に均一に当て、布から1.5〜2m離れると緑の映りこみが減ります。"],["使いどころ","ニュースの解説、画像へのつっこみ、反応もの。"],["例","なし"]]},{"g":"画面の組み方","n":"縦型の安全枠（Safe zone）","b":[["見え方","（見え方ではなく決まりです）アプリのボタン・説明文・名前が動画の上に重なる場所を避けます。"],["作り方","1080×1920で作り、文字と顔は真ん中に置きます。各社が公式に数字を出しているのは主に広告向けで、普通の投稿の決まった数字はありません [確認]。広告向けの数字の例：TikTok＝上240・下660・左右120px、リール＝上269・下672・左右65px、ショート＝上288・下672・左48・右192px [確認・点検サイトによる]。3つ共通で安全なのは中央の900×1400pxという案があります [確認]。"],["使いどころ","全部の縦動画。下の約3分の1と右端は使わない、と覚えれば足ります。表示はアプリの更新で変わるので、投稿前に下書きの画面で見て確かめます。"],["例","なし"]]},{"g":"画面の組み方","n":"＋コメント返信の貼り付け（Reply to comment）","b":[["見え方","画面の上に、視聴者のコメントの吹き出しが貼られ、それに答える動画になっています。"],["作り方","アプリの「コメントに動画で返信」機能を使うか、コメントの画像を上のほうに貼ります。最初の1文でコメントを読み上げます。"],["使いどころ","ネタ切れ防止、常連づくり。きついコメントへの返信は伸びやすいですが荒れやすいです。"],["例","なし"]]},{"g":"画面の組み方","n":"＋デュエット・ステッチ（Duet / Stitch）","b":[["見え方","他の人の動画が横（または冒頭）に流れ、それに反応・続きを足します。"],["作り方","アプリの機能で元の動画を横並び（デュエット）にするか、冒頭の数秒を引用（ステッチ）して自分の動画をつなげます。元の動画の一番気になる所で切って自分に替えます。"],["使いどころ","反応、つっこみ、専門家としての補足。"],["例","なし"]]},{"g":"画面の組み方","n":"＋POV形式（POV video）","b":[["見え方","「POV：◯◯な時」と文字が出て、見る人がその場面の当事者になる短い芝居です。"],["作り方","カメラを相手の目の位置に置き、演じる人がレンズに向かって話します。状況は文字1行で説明します。"],["使いどころ","あるある、共感、短い芝居。映画の主観ショット（→ 技法15_語りと監督の型）と同じ仕組みです。"],["例","なし"]]},{"g":"画面の組み方","n":"＋サムネと題名（YouTubeの長い動画）（Thumbnail and title）","b":[["見え方","一覧に並ぶ小さな絵と1行の題。再生前に見えるのはこれだけです。"],["作り方","絵は「顔の表情＋物1つ＋文字3〜4語まで」。小さく表示しても分かるか、スマホの大きさで確かめます。題と絵で同じことを言わず、合わせて1つの問いになるようにします。動画の最初の5秒で、絵と題の約束がうそでないと見せます。"],["使いどころ","YouTubeの横長の動画。ショートではサムネの役目は「最初の1コマ」が代わりにします。"],["例","なし"]]}],"17":[{"g":"比率","n":"4:3（1.33:1、スタンダード）","b":[["見え方","正方形に近い、昔のテレビと古い映画の形です（映画では1.37:1）。左右が狭く、顔や全身が収まりやすい形です。"],["作り方","1440×1080で作る、または16:9の左右を240pxずつ切ります。"],["使いどころ","昔の時代、記憶、閉じこめられた感じ、人物に集中させたいとき。高さのある物（建物、立った人）も映えます。"],["例","ジャスティス・リーグ：ザック・スナイダーカット（2021）全編が4:3 [知識]／ファースト・カウ（2019）[知識]"]]},{"g":"比率","n":"16:9（1.78:1）","b":[["見え方","今のテレビ、YouTube、パソコンのふつうの形です。"],["作り方","1920×1080（フルHD）、3840×2160（4K）。"],["使いどころ","迷ったらこれ。どの画面でも黒帯なしで全部に映ります。そのぶん「特別な感じ」はありません。"],["例","なし"]]},{"g":"比率","n":"1.85:1（アメリカンビスタ）","b":[["見え方","16:9よりほんの少し横長。映画館で「ふつうの幅」の映画の形です。"],["作り方","1920×1038（上下に21pxの黒帯）。映画館用のデータでは1998×1080です。"],["使いどころ","会話劇、コメディ、人物中心の映画。高さがあるので人も建物も収めやすいです。"],["例","なし"]]},{"g":"比率","n":"2.39:1（シネマスコープ、シネスコ）","b":[["見え方","とても横長。上下に黒帯が付き、「映画らしい」と感じる形です（古い作品は2.35:1）。"],["作り方","1920×803（上下に約138pxの黒帯）。もともとはアナモルフィックレンズ（横を縮めて撮るレンズ）で作る形です。黒帯を足すだけでなく、最初から横長の構図で撮ります。"],["使いどころ","景色、大作、横に並ぶ人物、広い余白。顔のアップは額やあごが切れます。"],["例","続・夕陽のガンマン（1966）横長の画面いっぱいの顔と、広い荒野 [知識]"]]},{"g":"比率","n":"IMAX 1.43:1","b":[["見え方","ほぼ正方形に近い巨大な画面で、床から天井まで視界がうまります。デジタルのIMAXは1.90:1です。"],["作り方","1544×1080。上下に余裕のある構図にして、大事な物は真ん中の2.39:1の範囲に収めておくと、ふつうの映画館でも使えます。"],["使いどころ","高さのある景色、落下、宇宙、見せ場。見せ場だけこの形に広げる映画が多いです。"],["例","ダークナイト（2008）冒頭の銀行強盗などがIMAXカメラで撮られ、対応する映画館では画面が上下に広がる [知識]／オッペンハイマー（2023）[知識]"]]},{"g":"比率","n":"縦 9:16","b":[["見え方","スマホを立てて持ったときの全画面。TikTok、YouTubeショート、Instagramリールの形です。"],["作り方","1080×1920。人は1人を大きく、動きは上下方向に。横長の素材を使うときは、中央を切り抜くか、上下に置いてすき間をぼかした複製や文字で埋めます。"],["使いどころ","SNSのショート動画、自撮り、縦に長い物（人、滝、ビル）。横の広がりは出ません。"],["例","なし"]]},{"g":"比率","n":"正方形 1:1","b":[["見え方","真四角。Instagramの昔の投稿や、顔写真のような近さがあります。"],["作り方","1080×1080。主役を真ん中に置く中心構図が合います。"],["使いどころ","肖像画のような親密さ、息苦しさ、SNSの投稿。"],["例","Mommy／マミー（2014）ほぼ全編が正方形で、主人公が両手で画面を左右に押し広げる場面がある [知識]"]]},{"g":"比率","n":"黒帯（レターボックス・ピラーボックス）","b":[["見え方","画面と映像の形が合わないとき、上下（レターボックス）や左右（ピラーボックス）に付く黒い帯。上下左右すべてに付くとウィンドウボックスと言います。"],["作り方","上の表の大きさで黒い四角を重ねます。帯を0.5〜1秒かけてすっと出し入れすると、「ここから映画の場面」という合図になります。"],["使いどころ","映画らしさ、回想、ゲームのイベント場面。帯の上に字幕を置けます。素材の上下が切れるので、大事な物が隠れないか確かめます。"],["例","なし"]]},{"g":"比率","n":"途中で比率を変える（可変アスペクト比）【足した技法】","b":[["見え方","場面によって画面の形が変わります。"],["作り方","全体をいちばん大きい枠で作り、場面ごとに黒帯の位置を変えます。切り替えはカットの変わり目で一気に、またはゆっくり動かします。"],["使いどころ","時代の区別、現実と夢、心が開く瞬間（狭い→広い）。"],["例","グランド・ブダペスト・ホテル（2014）話の時代ごとに3つの比率を使い分ける [知識]"]]},{"g":"比率","n":"黒帯からはみ出す（フレームブレイク）【足した技法】","b":[["見え方","物や人が黒帯の上にはみ出し、画面から飛び出してきたように見えます。"],["作り方","黒帯を映像の上に重ね、はみ出させたい物だけを切り抜いて黒帯のさらに上に重ねます。3Dなら物だけを別に描き出して重ねます。"],["使いどころ","迫力、驚き、MADやショート動画の見せ場。1本の中で1〜2回にします。"],["例","ライフ・オブ・パイ／トラと漂流した227日（2012）トビウオの群れが黒帯の上まで飛び出す [知識]／オズ はじまりの戦い（2013）冒頭の4:3白黒の場面で、物が枠の外へはみ出す [知識]"]]},{"g":"比率","n":"変わった比率（超横長・ほぼ真四角）【足した技法】","b":[["見え方","2.76:1のような極端な横長や、1.19:1のようなほぼ真四角。見た瞬間に「ふつうではない」と分かります。"],["作り方","1080の高さなら、2.76:1は1920×696、1.19:1は1285×1080。"],["使いどころ","超横長は広い景色と大人数、ほぼ真四角は古さ・狭さ・狂気。"],["例","ヘイトフル・エイト（2015）2.76:1 [知識]／ライトハウス（2019）1.19:1の白黒 [知識]／ナポレオン（1927）最後に3台の映写機で横3面に広がる [知識]"]]},{"g":"比率","n":"セーフエリア（文字が隠れない範囲）【足した技法】","b":[["見え方","見た目の技法ではなく、画面の端に大事な物を置かないという決まりです。"],["作り方","テレビ向けは画面の内側90%（文字は80%）に収めます。縦9:16のSNSでは、上の約10〜15%、下の約20〜25%、右端の約10〜15%にアプリのボタンや説明文が重なるので、文字や顔を置きません（アプリごとに違うので目安です）。"],["使いどころ","字幕、タイトル、顔。ショート動画では必ず確かめます。"],["例","なし"]]},{"g":"フィルムと記録の味","n":"8mm・16mm・35mm・70mmの違い（Film Gauge）","b":[["見え方","フィルムの幅が小さいほど、粒が大きく、絵があまく、ゆれが大きくなります。8mmは家庭の思い出、16mmは記録映像や低予算映画、35mmはふつうの映画、70mm（IMAXを含む）は粒がほとんど見えない細かさです。"],["作り方","1コマの大きさは、スーパー8が約5.8×4.0mm、スーパー16が約12.5×7.4mm、スーパー35が約24.9×18.7mm、70mm（5穴）が約52×23mm、IMAX（15穴）が約70×48mm。同じ画面に広げるので、35mmとくらべて16mmの粒は約2倍、8mmは約4倍の大きさに見え、70mmは約半分です。コードでは「粒の大きさ・ぼかしの量・ゆれの量」を、この倍率で一緒に変えます。8mmは4:3、1秒18コマにするとさらにそれらしくなります。"],["使いどころ","時代と「だれが撮ったか」を伝える。回想、劇中のホームムービー、ドキュメンタリー風。"],["例","ブラック・スワン（2010）16mmで撮り、粒の粗い生々しい画にした [知識]／アラビアのロレンス（1962）70mmの大きなフィルムで砂漠を撮った [知識]"]]},{"g":"フィルムと記録の味","n":"粒","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","デジタルで撮った映画でも、最後に粒を足してなじませることがよくあります。CGと実写の境目を隠す、のっぺりした面に生きた感じを出す働きがあります。暗い所ほど目立たせ、真っ白と真っ黒には乗せないと本物らしくなります。"]]},{"g":"フィルムと記録の味","n":"ゆれ（ゲートウィーブ / Gate Weave）","b":[["見え方","画面全体が、ごくわずかに、ふわふわと左右（と上下）にゆれます。止まった字幕や題名で特によく分かります。"],["作り方","フィルムが機械の中で1コマごとに少しずれることで起きます。コードでは、画面全体の位置を毎コマ乱数でずらし、ならして（数コマの平均）ゆっくりした動きにします。目安は35mmで画面幅の0.05〜0.1%（1920なら1〜2px）、16mmで0.1〜0.3%、8mmで0.3〜1%。縁が見えないよう1〜2%拡大します。"],["使いどころ","フィルムらしさの仕上げ。デジタルの題名や静止画が「動かなすぎる」とき。強すぎると酔います。"],["例","なし"]]},{"g":"フィルムと記録の味","n":"傷とほこり","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","何度も上映された古いフィルムの印です。場末の映画館、古い記録映像、B級映画への愛を表します。ずっと同じ強さではなく、巻の変わり目や激しい場面で増やすと本物らしくなります。"],["例","グラインドハウス（2007）わざと傷、コマ飛び、「巻が1本なくなった」という断りまで入れた [知識]"]]},{"g":"フィルムと記録の味","n":"VHS","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","80〜90年代の家庭の録画、発見された謎のテープ（ファウンドフッテージ）。4:3と組み合わせ、画面の下の乱れ、色のにじみ、日付の文字を足します。"],["例","V/H/S シンドローム（2012）見つかったビデオテープの映像として全編が進む [知識]"]]},{"g":"フィルムと記録の味","n":"走査線・ブラウン管","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","劇中のテレビ、監視カメラ、古いゲーム機の画面。カメラでブラウン管を撮ると出る、上下に流れる黒い帯（コマ数のずれ）も足すと本物らしくなります。"]]},{"g":"フィルムと記録の味","n":"デジタルノイズ","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","通信の乱れ、ハッキング、壊れたデータ、機械の目線。また、暗い所を高感度のデジタルカメラで撮ったときのざらつきは、フィルムの粒とは違う「今の夜」の味になります。"],["例","コラテラル（2004）夜のロサンゼルスを初期のデジタルカメラで撮り、ざらついた明るい夜空を見せた [知識]"]]},{"g":"フィルムと記録の味","n":"ドット絵化","b":[["メモ","作り方は MAD動画のエフェクトと作り方 で済み"],["映画での使い方","ゲームの世界、昔のゲームへの愛、顔を隠すモザイク。現実の物をブロックに変える見せ方もあります。"],["例","ピクセル（2015）現実の街や物が、ゲームのような光る四角いブロックに変わっていく [知識]"]]},{"g":"フィルムと記録の味","n":"無声映画の色つけ（染色・調色 / Tinting・Toning）","b":[["見え方","白黒の画面全体が1つの色に染まっています。染色は白い所まで色が付き、調色は黒い所だけが色に変わって白は白のままです。"],["作り方","染色はフィルムを染料にひたす、調色は銀を色の付いた物質に置きかえる方法でした。コードでは、白黒にしてから、染色＝色を乗算で重ねる、調色＝「黒→色→白」の階調に置きかえる（グラデーションマップ）。約束ごとは、夜＝青、火事や戦い＝赤、ろうそくや室内＝黄〜琥珀、森＝緑。場面ごとに色を変えます。"],["使いどころ","無声映画の時代の再現、夢や回想、色で場所や時刻を知らせたいとき。"],["例","吸血鬼ノスフェラトゥ（1922）夜の場面を青く染めて「夜」と伝える [知識]"]]},{"g":"フィルムと記録の味","n":"手彩色・ステンシル彩色【足した技法】","b":[["見え方","白黒の画面の中で、服や炎や煙など一部だけに色が付き、色が少しはみ出してちらちら動きます。"],["作り方","フィルムの1コマ1コマに筆で色を塗る、または型紙（ステンシル）で塗りました。コードでは、白黒の上に、色を付けたい部分だけのマスクで色を重ね（乗算かカラー合成）、マスクの縁を毎コマ1〜3pxずらします。"],["使いどころ","絵本のような古さ、1色だけを目立たせたいとき。"],["例","月世界旅行（1902、ジョルジュ・メリエス）1コマずつ手で色を塗った版がある [知識]"]]},{"g":"フィルムと記録の味","n":"光漏れ・フィルムの焼け・枠見せ（Light Leak / Film Burn）【足した技法】","b":[["見え方","画面の端からオレンジや赤の光がふわっと入る（光漏れ）、巻の最初と最後が白〜オレンジに焼ける、フィルムの穴や枠が見える。"],["作り方","カメラのすき間から光が入ったり、巻の端が光に当たったりして起きます。編集では、ぼかしたオレンジ〜赤のグラデーションを画面の端から「スクリーン」か加算で0.3〜1秒重ねます。場面の変わり目に置くと、つなぎの効果にもなります。"],["使いどころ","8mmの思い出、夏、MV、場面転換。"],["例","なし"]]},{"g":"フィルムと記録の味","n":"HDR（High Dynamic Range）","b":[["見え方","対応した画面で見ると、太陽・炎・ネオンが本当にまぶしく、同時に暗い所の細部も見えます。色も濃く出ます。"],["作り方","ふつうの映像（SDR）は明るさ100ニト（明るさの単位）を基準に作りますが、HDRは1000ニト以上まで使い、10ビット以上・広い色の範囲（Rec.2020）で記録します。方式はHDR10、ドルビービジョン、HLGなど。Blenderは内部で広い明るさを持っているので、EXR形式で書き出せば材料になります。仕上げにはHDR対応の画面と書き出し設定が要ります。"],["使いどころ","明るい所だけを明るくして、全体の明るさは上げないのがコツです。対応していない画面やSNSでは色がくすんだり白っぽくなったりするので、ふつうの版も作ります。"],["例","なし"]]}]};
